INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u1-C1','soc',6,2,'u1',1,'세계의 다양한 지형과 지형 경관 — 세계에는 산지·하천·해안·사막 등 다양한 지형이 있고, 같은 갈래의 지형도 저마다 독특한 경관 특징이 있으며(피오르·아치 바위·화산·위가 평평한 산 등), 지형 경관은 그곳 사람들의 생활 모습에 영향을 줌 · 조사는 인터넷 조사 → 정리 → 소개 자료 → 발표',ARRAY['[6사10-01] 세계의 여러 지역의 지형 경관을 살펴보고, 이를 통해 다양한 삶의 모습을 이해한다.']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u1-C2','soc',6,2,'u1',2,'산지 지형과 생활 모습 — 산지는 해발 고도가 높고 대체로 경사가 급하지만 고원처럼 넓고 평평한 곳, 정상이 움푹 파이거나 물이 고인 화산도 있으며, 사람들은 계단식 농사·가축 기르기·광업·관광(스키장·휴양림·화산 관광)으로 산지를 이용함',ARRAY['[6사10-01] 세계의 여러 지역의 지형 경관을 살펴보고, 이를 통해 다양한 삶의 모습을 이해한다.']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u1-C3','soc',6,2,'u1',3,'하천 지형과 생활 모습 — 하천을 따라 계곡·넓은 평야·거대한 폭포가 나타나고, 사람들은 어업·평야의 큰 규모 농사·수력 발전·폭포 관광·물건을 나르고 사고파는 수상 시장으로 하천을 이용함(강이 나른 흙이 쌓여 평야)',ARRAY['[6사10-01] 세계의 여러 지역의 지형 경관을 살펴보고, 이를 통해 다양한 삶의 모습을 이해한다.']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u1-C4','soc',6,2,'u1',4,'해안 지형과 생활 모습 — 바다와 육지가 만나는 해안에는 갯벌·모래사장·절벽·돌기둥이 나타나고, 사람들은 어업·양식업을 하며 배가 드나들기 좋은 곳에 항구, 경관이 아름다운 곳에 관광지, 갯벌이 넓은 곳에 염전을 둠 · 관광은 일자리·소득과 쓰레기·오염을 함께 늘림',ARRAY['[6사10-01] 세계의 여러 지역의 지형 경관을 살펴보고, 이를 통해 다양한 삶의 모습을 이해한다.']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u1-C5','soc',6,2,'u1',6,'기후의 뜻과 세계의 기후 분포 — 기후는 한 지역에서 여러 해에 걸쳐 되풀이되는 대기의 평균 상태(날씨와 다름)이고, 위도뿐 아니라 위치·지형·해발 고도에 따라 달라지며, 기온과 강수량을 기준으로 열대·건조·온대·냉대·한대·고산 기후로 나눔 — 적도에서 극으로 열대→건조→온대→냉대→한대, 적도를 기준으로 남북이 비슷(냉대는 주로 북반구), 매우 높은 산지는 고산, 우리나라는 온대·냉대',ARRAY['[6사10-02] 세계의 다양한 기후를 알아보고 기후 환경과 인간생활 간의 관계를 탐구한다.']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u1-C6','soc',6,2,'u1',7,'열대 기후와 생활 모습 — 적도 주변 저위도, 일 년 내내 기온이 높고 기온 변화가 거의 없음, 비가 많아 열대 우림이 되거나 건기·우기가 번갈아 초원이 펼쳐짐 · 화전 농업(카사바·얌·옥수수), 천연고무·카카오·바나나·커피 대규모 재배, 생태 관광, 바람이 통하는 큰 창·바닥을 띄운 고상 가옥·얇은 옷',ARRAY['[6사10-02] 세계의 다양한 기후를 알아보고 기후 환경과 인간생활 간의 관계를 탐구한다.']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u1-C7','soc',6,2,'u1',7,'건조 기후와 생활 모습 — 저위도·중위도의 강수량이 적은 곳, 낮과 밤의 기온 차이가 큼, 사막 또는 약간의 비로 초원 · 햇볕과 모래바람을 막는 온몸을 감싸는 옷, 벽이 두껍고 창이 작은 흙벽돌 집, 오아시스 주변 농사, 초원의 유목 생활과 이동식 가옥',ARRAY['[6사10-02] 세계의 다양한 기후를 알아보고 기후 환경과 인간생활 간의 관계를 탐구한다.']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u1-C8','soc',6,2,'u1',8,'온대 기후·냉대 기후와 생활 모습 — 온대는 중위도, 사계절이 비교적 뚜렷, 서부 유럽(여름 서늘·겨울 따뜻·비 고름 — 밀·낙농업)·지중해 주변(여름 덥고 건조·겨울 비 — 올리브·포도)·우리나라(여름 덥고 비·겨울 춥고 건조 — 벼농사) · 냉대는 북반구 중·고위도, 겨울이 여름보다 길고 몹시 추우며 눈이 많음, 여름에 밀·옥수수·감자, 침엽수림으로 목재·펄프 생산',ARRAY['[6사10-02] 세계의 다양한 기후를 알아보고 기후 환경과 인간생활 간의 관계를 탐구한다.']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u1-C9','soc',6,2,'u1',9,'한대 기후·고산 기후와 생활 모습 — 한대는 남극·북극 주변 고위도, 겨울이 길고 기온이 매우 낮아 눈과 얼음에 덮인 곳이 많음, 사냥한 생선·고기, 이끼 자라는 곳의 순록 유목, 지하자원 개발·극지 연구, 오로라·빙하 관광 · 고산은 해발 고도가 높은 곳, 적도 주변 일부는 일 년 내내 서늘해 사람이 많이 모여 삶, 감자·옥수수, 알파카·라마, 챙 넓은 둥근 모자·여러 겹 옷과 망토로 낮과 밤의 기온 차이에 적응 · 추운 기후로 가는 길은 둘(고위도·고산)',ARRAY['[6사10-02] 세계의 다양한 기후를 알아보고 기후 환경과 인간생활 간의 관계를 탐구한다.']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u1-C10','soc',6,2,'u1',10,'기후에 적응·극복하는 생활 조사와 자연환경을 고려한 상품 계획 — 사람들은 기후에 적응하고 이를 극복하며 살아가고 같은 기후에서도 생활 모습은 여러 가지임 · 조사: 주제 정하기 → 인터넷 조사 → 디지털 영상 지도에 표시 → 공유 · 상품 계획: 나라 정하기 → 지형과 기후 조사 → 아이디어 이야기 → 판매 계획 → 글과 그림, 자연환경의 특징을 상품 기능에 담고 실현 가능성도 생각',ARRAY['[6사10-02] 세계의 다양한 기후를 알아보고 기후 환경과 인간생활 간의 관계를 탐구한다.']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X01','soc',6,'u1',ARRAY['SO6-2-u1-C1']::text[],'세계의 지형은 모두 비슷하거나, 같은 갈래(산지 등)의 지형은 경관 특징도 하나뿐이라고 여긴다','같은 산지라도 — 화산? 위가 평평? 거대한 바위?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X02','soc',6,'u1',ARRAY['SO6-2-u1-C1','SO6-2-u1-C10']::text[],'지형 경관이나 기후는 그곳 사람들의 생활 모습과 관계가 없다고 여긴다','「그래서 그곳 사람들은 무엇을 하며 살까?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X03','soc',6,'u1',ARRAY['SO6-2-u1-C1','SO6-2-u1-C2','SO6-2-u1-C3','SO6-2-u1-C4']::text[],'지형의 갈래(산지·하천·해안·사막)를 헷갈린다(피오르를 하천으로, 수상 시장을 해안으로 등)','바다와 육지가 만나나? 강을 따라가나? 높이 솟았나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X04','soc',6,'u1',ARRAY['SO6-2-u1-C2']::text[],'산지는 모두 경사가 급해 사람이 살 수 없다고 여기거나, 고원·화산 같은 산지의 여러 모습을 모른다','고원은 넓고 평평 — 가축을 길러요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X05','soc',6,'u1',ARRAY['SO6-2-u1-C3']::text[],'하천 지역의 생활(평야 농사·어업·수력 발전·폭포 관광·수상 시장)을 다른 지형의 생활과 헷갈린다','물이 흐르며 무엇을 주나? 흙·물고기·힘·길') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X06','soc',6,'u1',ARRAY['SO6-2-u1-C4']::text[],'해안의 이용을 자리와 맞지 않게 짝짓는다(배가 드나들기 좋은 곳에 염전, 갯벌에 항구 등)','배 → 항구 · 넓은 갯벌 → 염전 · 아름다운 경관 → 관광지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X07','soc',6,'u1',ARRAY['SO6-2-u1-C4','SO6-2-u1-C10']::text[],'관광이나 개발의 한쪽 영향(좋은 점만 또는 나쁜 점만)만 본다','늘어나는 것 둘 — 일자리·소득과 쓰레기·오염') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X08','soc',6,'u1',ARRAY['SO6-2-u1-C5']::text[],'기후를 하루나 며칠의 날씨와 같은 것으로 여긴다','여러 해에 걸쳐 되풀이되는 평균 상태') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X09','soc',6,'u1',ARRAY['SO6-2-u1-C5','SO6-2-u1-C9']::text[],'기후가 위도만으로 정해진다고 여겨 위치·지형·해발 고도의 영향을 놓친다(적도 주변은 어디나 덥다)','적도 주변이라도 산 위로 오르면?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X10','soc',6,'u1',ARRAY['SO6-2-u1-C5']::text[],'기후 구분의 기준(기온과 강수량)이나 적도에서 극으로 가는 기후의 차례를 헷갈린다','열대 → 건조 → 온대 → 냉대 → 한대') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X11','soc',6,'u1',ARRAY['SO6-2-u1-C6','SO6-2-u1-C7']::text[],'열대 기후와 건조 기후의 특징을 헷갈린다(열대는 일교차가 크다, 건조는 비가 많다 등)','열대 — 늘 덥고 비 많음 · 건조 — 비 적고 낮밤 차이 큼') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X12','soc',6,'u1',ARRAY['SO6-2-u1-C6','SO6-2-u1-C7']::text[],'기후에 맞춘 집·옷·농업을 다른 기후의 것과 바꾸어 짝짓는다(사막에 고상 가옥, 열대에 두꺼운 벽 등)','그 기후에서 막을 것과 들일 것은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X13','soc',6,'u1',ARRAY['SO6-2-u1-C8']::text[],'온대 기후와 냉대 기후, 또는 온대 안의 서부 유럽·지중해·우리나라의 특징과 농업을 헷갈린다','겨울이 여름보다 길고 몹시 추우면 냉대') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X14','soc',6,'u1',ARRAY['SO6-2-u1-C9']::text[],'한대 기후와 고산 기후를 헷갈리거나, 고산 기후는 극지방에만 있다고 여긴다','고위도로 멀리 → 한대 · 높이 오르면 → 고산') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X15','soc',6,'u1',ARRAY['SO6-2-u1-C6','SO6-2-u1-C7','SO6-2-u1-C8','SO6-2-u1-C10']::text[],'한 곳의 생활 모습을 그 기후 전체의 모습으로 여기거나, 같은 기후 지역은 생활이 모두 같다고 여긴다','같은 온대에도 밀·올리브·벼') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X16','soc',6,'u1',ARRAY['SO6-2-u1-C10']::text[],'상품을 구상할 때 그곳의 지형·기후를 고려하지 않거나 한 상품이 어디서나 똑같이 쓰인다고 여긴다','그곳 사람들의 불편은 자연환경의 어떤 특징에서 오나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X17','soc',6,'u1',ARRAY['SO6-2-u1-C1','SO6-2-u1-C10']::text[],'조사·계획의 차례를 헷갈리거나 출처를 확인하지 않고 자료를 쓴다','정하고 → 조사하고 → 정리하고 → 나누기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X18','soc',6,'u1',ARRAY['SO6-2-u1-C7']::text[],'건조 기후 지역은 비가 적어 어디에서도 농사를 지을 수 없다고 여긴다(오아시스나 강 주변의 밀·대추야자 농사를 놓친다)','물이 있는 오아시스와 강 주변을 떠올려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X19','soc',6,'u1',ARRAY['SO6-2-u1-C5','SO6-2-u1-C10']::text[],'한 나라에는 한 가지 기후만 나타난다고 여긴다(러시아·캐나다·미국·칠레·노르웨이처럼 여러 기후가 나타나는 나라를 놓친다)','넓은 나라나 남북으로 긴 나라는 지역마다 기후가 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X20','soc',6,'u1',ARRAY['SO6-2-u1-C2','SO6-2-u1-C3','SO6-2-u1-C4','SO6-2-u1-C10']::text[],'자연환경이 사람의 생활을 정하기만 한다고 여겨, 사람들이 자연환경에 적응하고 극복하며 이용하는 모습을 놓친다','가파른 산비탈의 계단식 논처럼 사람들이 바꾸고 이겨 낸 모습도 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X21','soc',6,'u1',ARRAY['SO6-2-u1-C5','SO6-2-u1-C6','SO6-2-u1-C8','SO6-2-u1-C9']::text[],'기후 그래프에서 막대(강수량)와 선(기온)을 바꾸어 읽는다','막대는 강수량, 선은 기온이에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L01_basic#1','soc',6,2,'u1','L01','tb_g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',1,'ox','auto','세계에는 산지, 하천, 해안, 사막 등 다양한 지형이 있어요.',ARRAY['SO6-2-u1-X01']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C1","difficulty":1,"kind":"ox","stem":"세계에는 산지, 하천, 해안, 사막 등 다양한 지형이 있어요.","answer":"O","reason_options":[{"t":"교과서 12쪽에서 세계에 산지·하천·해안·사막 등 다양한 지형이 있다고 했기 때문에","correct":true},{"t":"세계의 땅은 어디나 같은 모습이기 때문에","mis":"SO6-2-u1-X01"}],"mis":"SO6-2-u1-X01","explanation":["꼭 기억해요 첫 문장이에요.","지형의 갈래가 여럿이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L01_basic#2','soc',6,2,'u1','L01','tb_g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',1,'sa','auto','「(    )은/는 그곳에서 살아가는 사람들의 생활 모습에 영향을 줍니다.」 빈칸에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u1-C1","difficulty":1,"kind":"sa","stem":"「(    )은/는 그곳에서 살아가는 사람들의 생활 모습에 영향을 줍니다.」 빈칸에 알맞은 말을 쓰세요.","answer":["지형 경관","지형경관"],"explanation":["꼭 기억해요 둘째 문장이에요.","땅의 생김새가 보여 주는 모습이에요.","지형 경관이에요."],"mis":"SO6-2-u1-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L01_basic#3','soc',6,2,'u1','L01','tb_g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',1,'mc','auto','캐나다 친구가 초대한 곳으로 알맞은 지형은 어디인가요?',ARRAY['SO6-2-u1-X03']::text[],true,'{"seq":3,"concept":"SO6-2-u1-C1","difficulty":1,"kind":"mc","stem":"캐나다 친구가 초대한 곳으로 알맞은 지형은 어디인가요?","options":[{"t":"로키산맥","correct":true},{"t":"베나길 동굴","mis":"SO6-2-u1-X03"},{"t":"사하라 사막","mis":"SO6-2-u1-X03"},{"t":"황허강","mis":"SO6-2-u1-X03"}],"explanation":["캐나다 친구의 말을 읽어요.","일 년 내내 높은 산에서 눈을 볼 수 있대요.","캐나다의 로키산맥이에요."],"asset":{"type":"speech","turns":[{"who":"캐나다 친구","text":"일 년 내내 높은 산에서 눈을 볼 수 있는 우리 나라로 여행 오는 게 어때?"},{"who":"포르투갈 친구","text":"하늘이 보이는 동굴에서 바닷소리를 들을 수 있는 우리 나라로 초대할게."}]},"variant_rule":{"alt":[{"stem":"포르투갈 친구가 초대한 곳으로 알맞은 지형은 어디인가요?","options":[{"t":"베나길 동굴","correct":true},{"t":"로키산맥","mis":"SO6-2-u1-X03"},{"t":"울루루","mis":"SO6-2-u1-X03"},{"t":"마우나로아","mis":"SO6-2-u1-X03"}],"explanation":["포르투갈 친구의 말을 읽어요.","하늘이 보이는 동굴에서 바닷소리를 들을 수 있대요.","포르투갈의 베나길 동굴이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L01_basic#4','soc',6,2,'u1','L01','tb_g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',1,'match','auto','교과서 13~14쪽의 지형과 그 지형이 있는 나라를 이으세요.','{}'::text[],false,'{"seq":4,"concept":"SO6-2-u1-C1","difficulty":1,"kind":"match","stem":"교과서 13~14쪽의 지형과 그 지형이 있는 나라를 이으세요.","pairs":[{"l":"송네 피오르","r":"노르웨이"},{"l":"사하라 사막","r":"리비아"},{"l":"황허강","r":"중국"},{"l":"울루루","r":"오스트레일리아"}],"mis":"SO6-2-u1-X03","explanation":["지도에서 번호를 찾아요.","송네 피오르는 노르웨이, 사하라 사막은 리비아에 있어요.","황허강은 중국, 울루루는 오스트레일리아예요."],"asset":{"type":"passage","lines":["① 송네 피오르(노르웨이) — 가파른 산으로 둘러싸인 매우 좁고 긴 해안선","② 사하라 사막(리비아) — 광활하게 펼쳐진 모래 언덕","③ 황허강(중국) — 황토가 섞여 색이 누런 강물이 굽이쳐 길게 흐름","④ 울루루(오스트레일리아) — 하나의 거대한 암석 바위산이 드넓은 평지에 솟음","⑤ 마우나로아(미국) — 용암이 흐르는 모습을 볼 수 있는 화산","⑥ 엘 아르코(멕시코) — 바다 위에 우뚝 솟은 아치 모양의 바위","⑦ 호라이마산(베네수엘라 볼리바르) — 우뚝 솟아 있지만 위쪽이 평평함"],"numbered":false,"title":"교과서 13~14쪽 세계의 유명한 지형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L01_basic#5','soc',6,2,'u1','L01','tb_g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',2,'mc','auto','「하나의 거대한 암석으로 이루어진 바위산이 드넓은 평지에 솟아 있는」 곳은 어디인가요?',ARRAY['SO6-2-u1-X01','SO6-2-u1-X03']::text[],true,'{"seq":5,"concept":"SO6-2-u1-C1","difficulty":2,"kind":"mc","stem":"「하나의 거대한 암석으로 이루어진 바위산이 드넓은 평지에 솟아 있는」 곳은 어디인가요?","options":[{"t":"울루루","correct":true},{"t":"마우나로아","mis":"SO6-2-u1-X01"},{"t":"호라이마산","mis":"SO6-2-u1-X01"},{"t":"엘 아르코","mis":"SO6-2-u1-X03"}],"explanation":["일곱 곳의 특징을 견줘요.","거대한 바위 하나가 평지에 솟아 있어요.","오스트레일리아의 울루루예요."],"asset":{"type":"passage","lines":["① 송네 피오르(노르웨이) — 가파른 산으로 둘러싸인 매우 좁고 긴 해안선","② 사하라 사막(리비아) — 광활하게 펼쳐진 모래 언덕","③ 황허강(중국) — 황토가 섞여 색이 누런 강물이 굽이쳐 길게 흐름","④ 울루루(오스트레일리아) — 하나의 거대한 암석 바위산이 드넓은 평지에 솟음","⑤ 마우나로아(미국) — 용암이 흐르는 모습을 볼 수 있는 화산","⑥ 엘 아르코(멕시코) — 바다 위에 우뚝 솟은 아치 모양의 바위","⑦ 호라이마산(베네수엘라 볼리바르) — 우뚝 솟아 있지만 위쪽이 평평함"],"numbered":false,"title":"교과서 13~14쪽 세계의 유명한 지형"},"variant_rule":{"alt":[{"stem":"「광활하게 펼쳐진 모래 언덕을 볼 수 있는」 곳은 어디인가요?","options":[{"t":"사하라 사막","correct":true},{"t":"황허강","mis":"SO6-2-u1-X03"},{"t":"송네 피오르","mis":"SO6-2-u1-X03"},{"t":"울루루","mis":"SO6-2-u1-X01"}],"explanation":["일곱 곳의 특징을 견줘요.","모래 언덕이 끝없이 펼쳐져 있어요.","리비아의 사하라 사막이에요."],"asset":{"type":"passage","lines":["① 송네 피오르(노르웨이) — 가파른 산으로 둘러싸인 매우 좁고 긴 해안선","② 사하라 사막(리비아) — 광활하게 펼쳐진 모래 언덕","③ 황허강(중국) — 황토가 섞여 색이 누런 강물이 굽이쳐 길게 흐름","④ 울루루(오스트레일리아) — 하나의 거대한 암석 바위산이 드넓은 평지에 솟음","⑤ 마우나로아(미국) — 용암이 흐르는 모습을 볼 수 있는 화산","⑥ 엘 아르코(멕시코) — 바다 위에 우뚝 솟은 아치 모양의 바위","⑦ 호라이마산(베네수엘라 볼리바르) — 우뚝 솟아 있지만 위쪽이 평평함"],"numbered":false,"title":"교과서 13~14쪽 세계의 유명한 지형"}},{"stem":"「용암이 흐르는 모습을 볼 수 있는 화산」은 어디인가요?","options":[{"t":"마우나로아","correct":true},{"t":"울루루","mis":"SO6-2-u1-X01"},{"t":"호라이마산","mis":"SO6-2-u1-X01"},{"t":"사하라 사막","mis":"SO6-2-u1-X03"}],"explanation":["일곱 곳의 특징을 견줘요.","용암이 흐르는 산이에요.","미국의 마우나로아예요."],"asset":{"type":"passage","lines":["① 송네 피오르(노르웨이) — 가파른 산으로 둘러싸인 매우 좁고 긴 해안선","② 사하라 사막(리비아) — 광활하게 펼쳐진 모래 언덕","③ 황허강(중국) — 황토가 섞여 색이 누런 강물이 굽이쳐 길게 흐름","④ 울루루(오스트레일리아) — 하나의 거대한 암석 바위산이 드넓은 평지에 솟음","⑤ 마우나로아(미국) — 용암이 흐르는 모습을 볼 수 있는 화산","⑥ 엘 아르코(멕시코) — 바다 위에 우뚝 솟은 아치 모양의 바위","⑦ 호라이마산(베네수엘라 볼리바르) — 우뚝 솟아 있지만 위쪽이 평평함"],"numbered":false,"title":"교과서 13~14쪽 세계의 유명한 지형"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L01_basic#6','soc',6,2,'u1','L01','tb_g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',2,'blank','auto','교과서 13쪽 「피오르」의 뜻은 「빙하에 의해 침식된 유(U) 자 모양의 계곡에 바닷물이 들어와 만들어진 (    )」이에요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C1","difficulty":2,"kind":"blank","stem":"교과서 13쪽 「피오르」의 뜻은 「빙하에 의해 침식된 유(U) 자 모양의 계곡에 바닷물이 들어와 만들어진 (    )」이에요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"해안선","correct":true},{"t":"강줄기","mis":"SO6-2-u1-X03"},{"t":"모래 언덕","mis":"SO6-2-u1-X03"},{"t":"화산","mis":"SO6-2-u1-X03"}],"explanation":["피오르 낱말 풀이를 떠올려요.","빙하가 깎은 계곡에 바닷물이 들어왔어요.","바다와 땅이 만나는 해안선이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L01_basic#7','soc',6,2,'u1','L01','tb_g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',2,'mc','auto','「무지개같이 한가운데가 높고 길게 굽은 모양」을 뜻하는 말과, 그 모양의 바위가 바다 위에 솟은 곳을 바르게 짝지은 것은 무엇인가요?',ARRAY['SO6-2-u1-X01','SO6-2-u1-X03']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C1","difficulty":2,"kind":"mc","stem":"「무지개같이 한가운데가 높고 길게 굽은 모양」을 뜻하는 말과, 그 모양의 바위가 바다 위에 솟은 곳을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"아치 — 엘 아르코","correct":true},{"t":"아치 — 울루루","mis":"SO6-2-u1-X01"},{"t":"피오르 — 엘 아르코","mis":"SO6-2-u1-X03"},{"t":"피오르 — 마우나로아","mis":"SO6-2-u1-X03"}],"explanation":["교과서 14쪽 낱말 풀이예요.","가운데가 높게 굽은 모양은 아치예요.","바다 위 아치 바위는 엘 아르코예요."],"asset":{"type":"passage","lines":["① 송네 피오르(노르웨이) — 가파른 산으로 둘러싸인 매우 좁고 긴 해안선","② 사하라 사막(리비아) — 광활하게 펼쳐진 모래 언덕","③ 황허강(중국) — 황토가 섞여 색이 누런 강물이 굽이쳐 길게 흐름","④ 울루루(오스트레일리아) — 하나의 거대한 암석 바위산이 드넓은 평지에 솟음","⑤ 마우나로아(미국) — 용암이 흐르는 모습을 볼 수 있는 화산","⑥ 엘 아르코(멕시코) — 바다 위에 우뚝 솟은 아치 모양의 바위","⑦ 호라이마산(베네수엘라 볼리바르) — 우뚝 솟아 있지만 위쪽이 평평함"],"numbered":false,"title":"교과서 13~14쪽 세계의 유명한 지형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L01_basic#8','soc',6,2,'u1','L01','tb_g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',2,'ox','auto','호라이마산은 우뚝 솟아 있지만 위쪽이 평평한 모습이에요.',ARRAY['SO6-2-u1-X01']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C1","difficulty":2,"kind":"ox","stem":"호라이마산은 우뚝 솟아 있지만 위쪽이 평평한 모습이에요.","answer":"O","reason_options":[{"t":"스스로 활동에서 살펴본 호라이마산은 우뚝 솟았지만 위쪽이 평평했기 때문에","correct":true},{"t":"산은 모두 꼭대기가 뾰족하기 때문에","mis":"SO6-2-u1-X01"}],"mis":"SO6-2-u1-X01","explanation":["스스로 활동 그림을 떠올려요.","탁자처럼 위가 평평해요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 송네 피오르(노르웨이) — 가파른 산으로 둘러싸인 매우 좁고 긴 해안선","② 사하라 사막(리비아) — 광활하게 펼쳐진 모래 언덕","③ 황허강(중국) — 황토가 섞여 색이 누런 강물이 굽이쳐 길게 흐름","④ 울루루(오스트레일리아) — 하나의 거대한 암석 바위산이 드넓은 평지에 솟음","⑤ 마우나로아(미국) — 용암이 흐르는 모습을 볼 수 있는 화산","⑥ 엘 아르코(멕시코) — 바다 위에 우뚝 솟은 아치 모양의 바위","⑦ 호라이마산(베네수엘라 볼리바르) — 우뚝 솟아 있지만 위쪽이 평평함"],"numbered":false,"title":"교과서 13~14쪽 세계의 유명한 지형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L01_basic#9','soc',6,2,'u1','L01','tb_g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',2,'mc','auto','교과서 12쪽에서 「지형 경관은 그곳에서 살아가는 사람들의 생활 모습에 영향을 줍니다」라고 했어요. 그 예로 가장 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X02']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C1","difficulty":2,"kind":"mc","stem":"교과서 12쪽에서 「지형 경관은 그곳에서 살아가는 사람들의 생활 모습에 영향을 줍니다」라고 했어요. 그 예로 가장 알맞은 것은 무엇인가요?","options":[{"t":"지형 경관이 아름다운 곳은 여행지가 되어 여행객이 많이 찾아와요","correct":true},{"t":"지형 경관은 사람들이 사는 모습과 아무 관계가 없어요","mis":"SO6-2-u1-X02"},{"t":"아름다운 지형에는 사람이 한 명도 찾아오지 않아요","mis":"SO6-2-u1-X02"},{"t":"지형은 날마다 모습이 바뀌어서 생활에 쓸 수 없어요","mis":"SO6-2-u1-X02"}],"explanation":["지형과 생활을 이어 봐요.","아름다운 경관은 여행객을 불러요.","사람들의 일과 생활이 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L01_basic#10','soc',6,2,'u1','L01','tb_g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',3,'error','auto','일곱 곳의 지형 경관을 두고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C1","difficulty":3,"kind":"error","stem":"일곱 곳의 지형 경관을 두고 친구들이 한 말 가운데 바르지 않은 것을 고르세요.","options":[{"t":"친구 다 — 「송네 피오르에서는 광활하게 펼쳐진 모래 언덕을 볼 수 있어.」","correct":true,"mis_target":"SO6-2-u1-X03"},{"t":"친구 가 — 「황허강은 황토가 섞여 강물이 누렇게 보여.」","mis":"SO6-2-u1-X03"},{"t":"친구 나 — 「엘 아르코는 바닷가에 있는 아치 모양의 바위야.」","mis":"SO6-2-u1-X03"}],"explanation":["일곱 곳의 특징을 하나씩 견줘요.","모래 언덕은 사하라 사막의 경관이에요.","친구 다가 지형을 바꿔 말했어요."],"asset":{"type":"passage","lines":["① 송네 피오르(노르웨이) — 가파른 산으로 둘러싸인 매우 좁고 긴 해안선","② 사하라 사막(리비아) — 광활하게 펼쳐진 모래 언덕","③ 황허강(중국) — 황토가 섞여 색이 누런 강물이 굽이쳐 길게 흐름","④ 울루루(오스트레일리아) — 하나의 거대한 암석 바위산이 드넓은 평지에 솟음","⑤ 마우나로아(미국) — 용암이 흐르는 모습을 볼 수 있는 화산","⑥ 엘 아르코(멕시코) — 바다 위에 우뚝 솟은 아치 모양의 바위","⑦ 호라이마산(베네수엘라 볼리바르) — 우뚝 솟아 있지만 위쪽이 평평함"],"numbered":false,"title":"교과서 13~14쪽 세계의 유명한 지형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L01_challenge#1','soc',6,2,'u1','L01','tb_g6_2_soc_u1_L01_challenge','lesson_challenge','SO6-2-u1-C1',2,'mc','auto','교과서 26~29쪽에서 세계의 지형 경관과 생활 모습을 조사해 소개한 차례로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X17']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C1","difficulty":2,"kind":"mc","stem":"교과서 26~29쪽에서 세계의 지형 경관과 생활 모습을 조사해 소개한 차례로 알맞은 것은 무엇인가요?","options":[{"t":"인터넷으로 조사하기 → 조사 내용 정리하기 → 소개 자료 만들기 → 발표하기","correct":true},{"t":"소개 자료 만들기 → 인터넷으로 조사하기 → 발표하기 → 조사 내용 정리하기","mis":"SO6-2-u1-X17"},{"t":"발표하기 → 조사 내용 정리하기 → 인터넷으로 조사하기 → 소개 자료 만들기","mis":"SO6-2-u1-X17"},{"t":"조사 내용 정리하기 → 발표하기 → 소개 자료 만들기 → 인터넷으로 조사하기","mis":"SO6-2-u1-X17"}],"explanation":["먼저 조사할 것을 찾아요.","찾은 것을 정리해 소개 자료로 만들어요.","마지막에 친구들에게 발표해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L01_challenge#2','soc',6,2,'u1','L01','tb_g6_2_soc_u1_L01_challenge','lesson_challenge','SO6-2-u1-C1',2,'match','auto','프레젠테이션 도구로 소개 자료를 만들 때 하고 싶은 일과 쓰는 기능을 이으세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u1-C1","difficulty":2,"kind":"match","stem":"프레젠테이션 도구로 소개 자료를 만들 때 하고 싶은 일과 쓰는 기능을 이으세요.","pairs":[{"l":"새 문서 만들기","r":"「+」 누르기"},{"l":"모둠원과 함께 작업하기","r":"「공유」 기능"},{"l":"글, 사진, 동영상 넣기","r":"「삽입」 기능"},{"l":"여러 장의 소개 자료 만들기","r":"「새 슬라이드」 추가"}],"mis":"SO6-2-u1-X17","explanation":["교과서 28쪽 차례를 떠올려요.","함께 작업할 때는 공유, 넣을 때는 삽입이에요.","여러 장은 새 슬라이드로 늘려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L01_challenge#3','soc',6,2,'u1','L01','tb_g6_2_soc_u1_L01_challenge','lesson_challenge','SO6-2-u1-C1',3,'mc','auto','소개 자료 예시에서 에트나 화산 주변 주민들이 화산이 만든 검은 토양으로 하는 일은 무엇인가요?',ARRAY['SO6-2-u1-X20','SO6-2-u1-X03']::text[],true,'{"seq":3,"concept":"SO6-2-u1-C1","difficulty":3,"kind":"mc","stem":"소개 자료 예시에서 에트나 화산 주변 주민들이 화산이 만든 검은 토양으로 하는 일은 무엇인가요?","options":[{"t":"오렌지 농사를 지어요","correct":true},{"t":"검은 토양을 덮어 아무것도 기르지 않아요","mis":"SO6-2-u1-X20"},{"t":"화산 위에 배가 드나드는 곳을 만들어요","mis":"SO6-2-u1-X03"},{"t":"검은 토양으로 눈썰매장을 만들어요","mis":"SO6-2-u1-X03"}],"explanation":["생활 모습 칸을 읽어요.","화산이 만든 검은 토양을 이용해요.","오렌지 농사를 지어요."],"asset":{"type":"passage","lines":["조사한 지형 — 이탈리아 에트나 화산(산지 지형, 높이 약 3,323 m)","소개 — 지금도 유럽에서 왕성하게 활동하는 화산 가운데 하나,","　2013년에 유네스코 세계유산으로 선정됨","생활 모습 — 화산이 만든 검은 토양을 이용하여 오렌지 농사를 지음","소개하고 싶은 내용 — 위험한 화산 지역 주변에서도 주민들은","　화산의 혜택을 이용하며 살아감"],"numbered":false,"title":"교과서 27~28쪽 소개 자료 예시"},"variant_rule":{"alt":[{"stem":"소개 자료 예시에서 에트나 화산은 어느 나라에 있고 어떤 지형인가요?","options":[{"t":"이탈리아 — 산지 지형","correct":true},{"t":"이탈리아 — 해안 지형","mis":"SO6-2-u1-X03"},{"t":"노르웨이 — 산지 지형","mis":"SO6-2-u1-X03"},{"t":"멕시코 — 사막 지형","mis":"SO6-2-u1-X03"}],"explanation":["조사한 지형 칸을 읽어요.","이탈리아에 있는 화산이에요.","화산은 산지 지형이에요."],"asset":{"type":"passage","lines":["조사한 지형 — 이탈리아 에트나 화산(산지 지형, 높이 약 3,323 m)","소개 — 지금도 유럽에서 왕성하게 활동하는 화산 가운데 하나,","　2013년에 유네스코 세계유산으로 선정됨","생활 모습 — 화산이 만든 검은 토양을 이용하여 오렌지 농사를 지음","소개하고 싶은 내용 — 위험한 화산 지역 주변에서도 주민들은","　화산의 혜택을 이용하며 살아감"],"numbered":false,"title":"교과서 27~28쪽 소개 자료 예시"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L01_challenge#4','soc',6,2,'u1','L01','tb_g6_2_soc_u1_L01_challenge','lesson_challenge','SO6-2-u1-C1',3,'ox','auto','박람회 표지판 문장 ㉢ 「강 주변의 넓은 평야에서 계단식 농사를 짓습니다.」는 옳은 설명이에요.',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C1","difficulty":3,"kind":"ox","stem":"박람회 표지판 문장 ㉢ 「강 주변의 넓은 평야에서 계단식 농사를 짓습니다.」는 옳은 설명이에요.","answer":"X","reason_options":[{"t":"계단식 농사는 경사가 가파른 산지에서 짓고, 강 주변의 넓은 평야에서는 큰 규모로 농사를 짓기 때문에","correct":true},{"t":"평야와 산지의 농사 방법은 똑같기 때문에","mis":"SO6-2-u1-X03"}],"mis":"SO6-2-u1-X03","explanation":["계단식 논을 떠올려요.","가파른 산비탈에 만들어요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉠ 지형 경관이 아름다운 곳은 관광 산업이 발달하기도 합니다.","㉡ 산지 지형에서는 농사를 지을 수 없습니다.","㉢ 강 주변의 넓은 평야에서 계단식 농사를 짓습니다.","㉣ 해안 지역에는 세계 여러 나라의 배가 오가는 항구가 발달합니다.","㉤ 산지 지형에는 고원과 같이 비교적 넓고 평평한 곳도 있습니다.","㉥ 세계의 지형 경관과 생활 모습은 다양합니다."],"numbered":false,"title":"교과서 29쪽 박람회 표지판 완성하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L01_challenge#5','soc',6,2,'u1','L01','tb_g6_2_soc_u1_L01_challenge','lesson_challenge','SO6-2-u1-C1',3,'mc','auto','박람회 표지판의 여섯 문장 가운데 옳지 않은 설명을 고르세요.',ARRAY['SO6-2-u1-X07','SO6-2-u1-X04','SO6-2-u1-X01']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C1","difficulty":3,"kind":"mc","stem":"박람회 표지판의 여섯 문장 가운데 옳지 않은 설명을 고르세요.","options":[{"t":"㉡ 산지 지형에서는 농사를 지을 수 없습니다.","correct":true},{"t":"㉠ 지형 경관이 아름다운 곳은 관광 산업이 발달하기도 합니다.","mis":"SO6-2-u1-X07"},{"t":"㉤ 산지 지형에는 고원과 같이 비교적 넓고 평평한 곳도 있습니다.","mis":"SO6-2-u1-X04"},{"t":"㉥ 세계의 지형 경관과 생활 모습은 다양합니다.","mis":"SO6-2-u1-X01"}],"explanation":["문장을 하나씩 따져요.","산지에서도 계단식 논을 만들고 고원에서 가축을 길러요.","㉡이 옳지 않아요."],"asset":{"type":"passage","lines":["㉠ 지형 경관이 아름다운 곳은 관광 산업이 발달하기도 합니다.","㉡ 산지 지형에서는 농사를 지을 수 없습니다.","㉢ 강 주변의 넓은 평야에서 계단식 농사를 짓습니다.","㉣ 해안 지역에는 세계 여러 나라의 배가 오가는 항구가 발달합니다.","㉤ 산지 지형에는 고원과 같이 비교적 넓고 평평한 곳도 있습니다.","㉥ 세계의 지형 경관과 생활 모습은 다양합니다."],"numbered":false,"title":"교과서 29쪽 박람회 표지판 완성하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L01_challenge#6','soc',6,2,'u1','L01','tb_g6_2_soc_u1_L01_challenge','lesson_challenge','SO6-2-u1-C1',3,'error','auto','소개 자료를 만들며 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.',ARRAY['SO6-2-u1-X17']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C1","difficulty":3,"kind":"error","stem":"소개 자료를 만들며 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.","options":[{"t":"친구 나 — 「조사는 인터넷으로만 해야 해. 책이나 여행 책자는 쓰면 안 돼.」","correct":true,"mis_target":"SO6-2-u1-X17"},{"t":"친구 가 — 「동영상으로 지형 경관과 사람들의 생활 모습을 생생하게 보여 주자.」","mis":"SO6-2-u1-X17"},{"t":"친구 다 — 「사진으로 여러 각도에서 본 지형 경관을 보여 주면 좋겠어.」","mis":"SO6-2-u1-X17"}],"explanation":["조사 방법을 떠올려요.","책, 신문, 여행 책자도 쓸 수 있어요.","친구 나의 말이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L01_challenge#7','soc',6,2,'u1','L01','tb_g6_2_soc_u1_L01_challenge','lesson_challenge','SO6-2-u1-C1',3,'mc','auto','활동지 예시에서 할롱베이에 관광객이 많아지며 나타난 일을 바르게 말한 것은 무엇인가요?',ARRAY['SO6-2-u1-X07','SO6-2-u1-X02']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C1","difficulty":3,"kind":"mc","stem":"활동지 예시에서 할롱베이에 관광객이 많아지며 나타난 일을 바르게 말한 것은 무엇인가요?","options":[{"t":"주민들의 소득은 늘었지만 쓰레기 문제 등 환경 오염이 심각해졌어요","correct":true},{"t":"주민들의 소득도 줄고 바다도 더 깨끗해졌어요","mis":"SO6-2-u1-X07"},{"t":"좋은 일만 생겨 걱정할 것이 없어요","mis":"SO6-2-u1-X07"},{"t":"관광객이 많아져도 주민들의 생활은 그대로예요","mis":"SO6-2-u1-X02"}],"explanation":["소개하고 싶은 내용 칸을 읽어요.","소득이 늘었어요.","하지만 환경 오염이 심해졌어요."],"asset":{"type":"passage","lines":["소개하고 싶은 지형 — 해안 지형(베트남 할롱베이)","생활 모습 — 다양한 물고기가 잡히는 바다에서 어업을 하거나,","　독특한 자연 경관을 보러 온 관광객을 상대로 관광업을 함","소개하고 싶은 내용 — 관광객이 많아져 주민들의 소득은 늘었지만","　쓰레기 문제 등 환경 오염이 심각해져, 할롱베이를 지키려는","　사람들의 노력을 소개하고 싶음"],"numbered":false,"title":"활동지 예시 — 소개 자료에 들어갈 정보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L01_challenge#8','soc',6,2,'u1','L01','tb_g6_2_soc_u1_L01_challenge','lesson_challenge','SO6-2-u1-C1',4,'mc','auto','친구 4의 주제로 소개 자료를 만들 때 담기에 가장 알맞은 내용은 무엇인가요?',ARRAY['SO6-2-u1-X17','SO6-2-u1-X01','SO6-2-u1-X07']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C1","difficulty":4,"kind":"mc","stem":"친구 4의 주제로 소개 자료를 만들 때 담기에 가장 알맞은 내용은 무엇인가요?","options":[{"t":"관광으로 생긴 문제와, 지형 경관을 지키려고 사람들이 하는 노력","correct":true},{"t":"그 지형의 사진 한 장만 크게 넣기","mis":"SO6-2-u1-X17"},{"t":"지형 이름과 나라 이름만 적기","mis":"SO6-2-u1-X01"},{"t":"관광객이 늘어 좋아진 점만 쓰기","mis":"SO6-2-u1-X07"}],"explanation":["친구 4의 주제를 다시 읽어요.","보호받는 지형과 지키려는 노력이 핵심이에요.","문제와 노력을 함께 담아요."],"asset":{"type":"passage","lines":["친구 1 — 세계의 유명한 산지 지형과 사람들의 생활 모습을 조사하고 싶어.","친구 2 — 대륙별 큰 강과 그곳에서 살아가는 사람들의 생활 모습을 알아보고 싶어.","친구 3 — 세계의 유명한 해변과 관광 산업의 모습을 살펴보려 해.","친구 4 — 세계적으로 보호받고 있는 지형 경관과 이를 지키려는 사람들의 노력을 알아보고 싶어."],"title":"교과서 26쪽 조사하고 싶은 지형 경관과 생활 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L01_challenge#9','soc',6,2,'u1','L01','tb_g6_2_soc_u1_L01_challenge','lesson_challenge','SO6-2-u1-C1',4,'essay','teacher','교과서 13~14쪽의 지형 가운데 하나를 골라 여행 마그넷을 디자인하려고 해요. 고른 지형의 나라, 지형 경관의 특징, 마그넷에 넣을 그림을 차례로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u1-C1","difficulty":4,"kind":"essay","stem":"교과서 13~14쪽의 지형 가운데 하나를 골라 여행 마그넷을 디자인하려고 해요. 고른 지형의 나라, 지형 경관의 특징, 마그넷에 넣을 그림을 차례로 쓰세요.","answer_guide":{"answer":"예: 오스트레일리아의 울루루를 골랐어요. 하나의 거대한 암석으로 이루어진 바위산이 드넓은 평지에 솟아 있어요. 마그넷에는 끝없는 평지 위에 우뚝 솟은 바위산 하나와 그 앞에서 사진을 찍는 여행객을 그리겠어요.","scoring_points":["지형과 나라를 바르게 짝지었는가","지형 경관의 특징을 썼는가","마그넷 그림에 그 특징이 드러나는가"]},"explanation":["일곱 곳 가운데 하나를 골라요.","경관의 특징을 찾아 써요.","특징이 보이는 그림을 정해요."],"asset":{"type":"passage","lines":["① 송네 피오르(노르웨이) — 가파른 산으로 둘러싸인 매우 좁고 긴 해안선","② 사하라 사막(리비아) — 광활하게 펼쳐진 모래 언덕","③ 황허강(중국) — 황토가 섞여 색이 누런 강물이 굽이쳐 길게 흐름","④ 울루루(오스트레일리아) — 하나의 거대한 암석 바위산이 드넓은 평지에 솟음","⑤ 마우나로아(미국) — 용암이 흐르는 모습을 볼 수 있는 화산","⑥ 엘 아르코(멕시코) — 바다 위에 우뚝 솟은 아치 모양의 바위","⑦ 호라이마산(베네수엘라 볼리바르) — 우뚝 솟아 있지만 위쪽이 평평함"],"numbered":false,"title":"교과서 13~14쪽 세계의 유명한 지형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L01_challenge#10','soc',6,2,'u1','L01','tb_g6_2_soc_u1_L01_challenge','lesson_challenge','SO6-2-u1-C1',4,'essay','teacher','박람회 표지판 문장 가운데 옳지 않은 두 문장을 찾아 기호를 쓰고, 각각 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u1-C1","difficulty":4,"kind":"essay","stem":"박람회 표지판 문장 가운데 옳지 않은 두 문장을 찾아 기호를 쓰고, 각각 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: ㉡ — 산지 지형에서도 경사가 가파른 곳에서는 계단식 농사를 짓고, 비교적 평탄한 곳에서는 가축을 기릅니다. ㉢ — 산지의 경사가 가파른 곳에서 계단식 농사를 짓고, 강 주변의 넓은 평야에서는 큰 규모로 농사를 짓습니다.","scoring_points":["㉡과 ㉢을 찾았는가","㉡을 산지의 생활에 맞게 고쳤는가","㉢을 계단식 농사와 평야 농사에 맞게 고쳤는가"]},"explanation":["여섯 문장을 하나씩 따져요.","틀린 부분을 찾아요.","배운 사실로 고쳐 써요."],"asset":{"type":"passage","lines":["㉠ 지형 경관이 아름다운 곳은 관광 산업이 발달하기도 합니다.","㉡ 산지 지형에서는 농사를 지을 수 없습니다.","㉢ 강 주변의 넓은 평야에서 계단식 농사를 짓습니다.","㉣ 해안 지역에는 세계 여러 나라의 배가 오가는 항구가 발달합니다.","㉤ 산지 지형에는 고원과 같이 비교적 넓고 평평한 곳도 있습니다.","㉥ 세계의 지형 경관과 생활 모습은 다양합니다."],"numbered":false,"title":"교과서 29쪽 박람회 표지판 완성하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L02_basic#1','soc',6,2,'u1','L02','tb_g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',1,'sa','auto','「(    ) 지형은 해발 고도가 높고 대체로 경사가 급합니다.」 빈칸에 알맞은 말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u1-C2","difficulty":1,"kind":"sa","stem":"「(    ) 지형은 해발 고도가 높고 대체로 경사가 급합니다.」 빈칸에 알맞은 말을 두 글자로 쓰세요.","answer":["산지"],"explanation":["꼭 기억해요 첫 문장이에요.","높고 경사가 급한 지형이에요.","산지예요."],"mis":"SO6-2-u1-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L02_basic#2','soc',6,2,'u1','L02','tb_g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',1,'blank','auto','바다 표면으로부터 잰 육지의 높이를 (    )(이)라고 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-2-u1-X04','SO6-2-u1-X03']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C2","difficulty":1,"kind":"blank","stem":"바다 표면으로부터 잰 육지의 높이를 (    )(이)라고 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"해발 고도","correct":true},{"t":"경사","mis":"SO6-2-u1-X04"},{"t":"고원","mis":"SO6-2-u1-X04"},{"t":"해안선","mis":"SO6-2-u1-X03"}],"explanation":["교과서 15쪽 낱말 풀이예요.","바다 표면을 기준으로 재요.","해발 고도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L02_basic#3','soc',6,2,'u1','L02','tb_g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',1,'mc','auto','세계에서 가장 높은 산과 그 산이 있는 산맥을 바르게 짝지은 것은 무엇인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C2","difficulty":1,"kind":"mc","stem":"세계에서 가장 높은 산과 그 산이 있는 산맥을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"에베레스트산 — 히말라야산맥","correct":true},{"t":"파리나코타화산 — 히말라야산맥","mis":"SO6-2-u1-X03"},{"t":"에베레스트산 — 안데스산맥","mis":"SO6-2-u1-X03"},{"t":"아비시니아고원 — 알프스산맥","mis":"SO6-2-u1-X03"}],"explanation":["교과서 15쪽 사진 ①을 봐요.","에베레스트산은 8,848 m예요.","히말라야산맥에 있어요."],"asset":{"type":"passage","lines":["① 히말라야산맥(네팔) — 세계에서 가장 높은 에베레스트산(8,848 m)이 있음","② 아비시니아고원(에티오피아) — 아프리카에서 가장 큰 고원, 「아프리카의 지붕」","③ 파리나코타화산(칠레) — 칠레와 볼리비아의 국경, 안데스산맥에 속함"],"numbered":false,"title":"교과서 15쪽 산지 사진 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L02_basic#4','soc',6,2,'u1','L02','tb_g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',1,'ox','auto','「지하자원이 풍부한 산지에는 스키장, 휴양림 등 관광 산업이 발달합니다.」는 바른 문장이에요.',ARRAY['SO6-2-u1-X04']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C2","difficulty":1,"kind":"ox","stem":"「지하자원이 풍부한 산지에는 스키장, 휴양림 등 관광 산업이 발달합니다.」는 바른 문장이에요.","answer":"X","reason_options":[{"t":"지하자원이 풍부한 산지에는 광업이 발달하고, 스키장·휴양림은 아름다운 지형 경관을 이용한 것이기 때문에","correct":true},{"t":"땅속 자원과 관광지는 같은 것이기 때문에","mis":"SO6-2-u1-X04"}],"mis":"SO6-2-u1-X04","explanation":["꼭 기억해요 둘째 문장이에요.","지하자원이 풍부하면 광업이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L02_basic#5','soc',6,2,'u1','L02','tb_g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',2,'match','auto','교과서 16~17쪽 산지와 그곳 사람들의 생활 모습을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u1-C2","difficulty":2,"kind":"match","stem":"교과서 16~17쪽 산지와 그곳 사람들의 생활 모습을 이으세요.","pairs":[{"l":"파미르고원","r":"양을 키워요"},{"l":"알프스산맥","r":"관광지가 발달했어요"},{"l":"추키카마타","r":"구리를 캐는 광업이 발달했어요"},{"l":"바나우에","r":"계단식 논을 만들었어요"}],"mis":"SO6-2-u1-X02","explanation":["사진 설명을 하나씩 읽어요.","평탄한 고원은 가축, 아름다운 산맥은 관광이에요.","구리는 광업, 가파른 비탈은 계단식 논이에요."],"asset":{"type":"passage","lines":["㉠ 파미르고원(타지키스탄) — 땅이 비교적 평탄하고 풀이 잘 자라 양을 키움","㉡ 알프스산맥(스위스) — 아름다운 지형 경관을 이용한 관광지가 발달함","㉢ 추키카마타(칠레) — 구리 매장량이 많아 광업이 발달함","㉣ 아이슬란드 — 화산 분출을 볼 수 있는 지역을 관광지로 활용함","㉤ 바나우에(필리핀) — 산비탈을 따라 만든 계단식 논"],"numbered":false,"title":"교과서 16~17쪽 산지를 이용하는 사람들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L02_basic#6','soc',6,2,'u1','L02','tb_g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',2,'mc','auto','필리핀 바나우에 사람들이 산비탈을 따라 계단식 논을 만든 까닭은 무엇인가요?',ARRAY['SO6-2-u1-X20','SO6-2-u1-X04','SO6-2-u1-X02']::text[],true,'{"seq":6,"concept":"SO6-2-u1-C2","difficulty":2,"kind":"mc","stem":"필리핀 바나우에 사람들이 산비탈을 따라 계단식 논을 만든 까닭은 무엇인가요?","options":[{"t":"가파른 산지에서는 그대로 농사를 짓기 어렵기 때문이에요","correct":true},{"t":"산지에서는 어떤 농사도 지을 수 없기 때문이에요","mis":"SO6-2-u1-X20"},{"t":"평평한 땅이 너무 많이 남기 때문이에요","mis":"SO6-2-u1-X04"},{"t":"논두렁을 구경거리로 팔기 위해서예요","mis":"SO6-2-u1-X02"}],"explanation":["바나우에는 가파른 산지예요.","경사진 땅을 계단처럼 다듬었어요.","땅을 바꾸어 농사를 지었어요."],"asset":{"type":"passage","lines":["㉠ 파미르고원(타지키스탄) — 땅이 비교적 평탄하고 풀이 잘 자라 양을 키움","㉡ 알프스산맥(스위스) — 아름다운 지형 경관을 이용한 관광지가 발달함","㉢ 추키카마타(칠레) — 구리 매장량이 많아 광업이 발달함","㉣ 아이슬란드 — 화산 분출을 볼 수 있는 지역을 관광지로 활용함","㉤ 바나우에(필리핀) — 산비탈을 따라 만든 계단식 논"],"numbered":false,"title":"교과서 16~17쪽 산지를 이용하는 사람들"},"variant_rule":{"alt":[{"stem":"타지키스탄의 파미르고원에서 사람들이 양을 키울 수 있는 까닭은 무엇인가요?","options":[{"t":"땅이 비교적 평탄하고 풀이 잘 자라기 때문이에요","correct":true},{"t":"땅속에 구리가 많기 때문이에요","mis":"SO6-2-u1-X03"},{"t":"화산이 분출하는 모습을 볼 수 있기 때문이에요","mis":"SO6-2-u1-X03"},{"t":"산지에서는 가축을 기를 수 없기 때문이에요","mis":"SO6-2-u1-X04"}],"explanation":["사진 ㉠ 설명을 읽어요.","평탄하고 풀이 잘 자라요.","양에게 풀을 먹일 수 있어요."],"asset":{"type":"passage","lines":["㉠ 파미르고원(타지키스탄) — 땅이 비교적 평탄하고 풀이 잘 자라 양을 키움","㉡ 알프스산맥(스위스) — 아름다운 지형 경관을 이용한 관광지가 발달함","㉢ 추키카마타(칠레) — 구리 매장량이 많아 광업이 발달함","㉣ 아이슬란드 — 화산 분출을 볼 수 있는 지역을 관광지로 활용함","㉤ 바나우에(필리핀) — 산비탈을 따라 만든 계단식 논"],"numbered":false,"title":"교과서 16~17쪽 산지를 이용하는 사람들"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L02_basic#7','soc',6,2,'u1','L02','tb_g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',2,'mc','auto','교과서 15쪽 사진 가운데 「고원과 같이 비교적 넓고 평평한 곳」에 해당하는 산지는 무엇인가요?',ARRAY['SO6-2-u1-X04']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C2","difficulty":2,"kind":"mc","stem":"교과서 15쪽 사진 가운데 「고원과 같이 비교적 넓고 평평한 곳」에 해당하는 산지는 무엇인가요?","options":[{"t":"아비시니아고원","correct":true},{"t":"에베레스트산","mis":"SO6-2-u1-X04"},{"t":"파리나코타화산","mis":"SO6-2-u1-X04"},{"t":"히말라야산맥","mis":"SO6-2-u1-X04"}],"explanation":["사진 셋의 이름을 봐요.","「아프리카의 지붕」이라 불려요.","아비시니아고원이에요."],"asset":{"type":"passage","lines":["① 히말라야산맥(네팔) — 세계에서 가장 높은 에베레스트산(8,848 m)이 있음","② 아비시니아고원(에티오피아) — 아프리카에서 가장 큰 고원, 「아프리카의 지붕」","③ 파리나코타화산(칠레) — 칠레와 볼리비아의 국경, 안데스산맥에 속함"],"numbered":false,"title":"교과서 15쪽 산지 사진 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L02_basic#8','soc',6,2,'u1','L02','tb_g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',2,'mc','auto','화산 주변이 관광지로 유명한 곳이 많은 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X20','SO6-2-u1-X04','SO6-2-u1-X03']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C2","difficulty":2,"kind":"mc","stem":"화산 주변이 관광지로 유명한 곳이 많은 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"지형 경관이 독특하고 온천이 있기 때문이에요","correct":true},{"t":"화산 주변에는 사람이 살 수 없기 때문이에요","mis":"SO6-2-u1-X20"},{"t":"화산은 경사가 없어 평평하기 때문이에요","mis":"SO6-2-u1-X04"},{"t":"화산 주변은 모두 넓은 모래 언덕이기 때문이에요","mis":"SO6-2-u1-X03"}],"explanation":["교과서 17쪽 글을 읽어요.","화산 주변은 경관이 독특해요.","온천도 있어 관광객이 찾아와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L02_basic#9','soc',6,2,'u1','L02','tb_g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',2,'ox','auto','타지키스탄의 파미르고원은 땅이 비교적 평탄하고 풀이 잘 자라 양을 키워요.',ARRAY['SO6-2-u1-X04']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C2","difficulty":2,"kind":"ox","stem":"타지키스탄의 파미르고원은 땅이 비교적 평탄하고 풀이 잘 자라 양을 키워요.","answer":"O","reason_options":[{"t":"교과서 16쪽 사진처럼 평탄한 곳에서 풀을 먹여 가축을 기르기 때문에","correct":true},{"t":"산지는 모두 경사가 급해 가축을 기를 수 없기 때문에","mis":"SO6-2-u1-X04"}],"mis":"SO6-2-u1-X04","explanation":["사진 ㉠ 설명이에요.","평탄하고 풀이 잘 자라요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 파미르고원(타지키스탄) — 땅이 비교적 평탄하고 풀이 잘 자라 양을 키움","㉡ 알프스산맥(스위스) — 아름다운 지형 경관을 이용한 관광지가 발달함","㉢ 추키카마타(칠레) — 구리 매장량이 많아 광업이 발달함","㉣ 아이슬란드 — 화산 분출을 볼 수 있는 지역을 관광지로 활용함","㉤ 바나우에(필리핀) — 산비탈을 따라 만든 계단식 논"],"numbered":false,"title":"교과서 16~17쪽 산지를 이용하는 사람들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L02_basic#10','soc',6,2,'u1','L02','tb_g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',3,'error','auto','에베레스트산 이야기를 읽고 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.',ARRAY['SO6-2-u1-X07']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C2","difficulty":3,"kind":"error","stem":"에베레스트산 이야기를 읽고 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.","options":[{"t":"친구 다 — 「관광객이 많이 올수록 좋은 점만 생겨.」","correct":true,"mis_target":"SO6-2-u1-X07"},{"t":"친구 가 — 「네팔 주민들은 셰르파로 일하며 수입을 얻어.」","mis":"SO6-2-u1-X07"},{"t":"친구 나 — 「관광객이 버린 쓰레기로 산이 몸살을 앓고 있어.」","mis":"SO6-2-u1-X07"}],"explanation":["빛과 그림자를 함께 봐요.","수입이 생기지만 쓰레기 문제도 생겼어요.","친구 다는 한쪽만 봤어요."],"asset":{"type":"passage","lines":["「세계의 지붕」 히말라야산맥의 가장 높은 봉우리 에베레스트산에 오르려고","네팔을 찾는 관광객이 많아요.","네팔 주민들은 관광객에게 음식과 잠자리를 내주고,","등반길을 안내하고 짐을 들어 주는 셰르파로 일하며 수입을 얻어요.","그러나 관광객들이 버린 쓰레기로 에베레스트산은 몸살을 앓고 있어요.","네팔 정부는 관광객이 자기 쓰레기를 가지고 내려오게 하고,","쓰레기 처리 비용만큼 입산료를 받았다가 쓰레기를 가져오면 돌려줘요."],"title":"교과서 18쪽 에베레스트산의 빛과 그림자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L02_challenge#1','soc',6,2,'u1','L02','tb_g6_2_soc_u1_L02_challenge','lesson_challenge','SO6-2-u1-C2',2,'sa','auto','에베레스트산에서 관광객의 등반길을 안내하고 짐을 들어 주는 사람을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u1-C2","difficulty":2,"kind":"sa","stem":"에베레스트산에서 관광객의 등반길을 안내하고 짐을 들어 주는 사람을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["셰르파"],"explanation":["이야기 넷째 줄을 읽어요.","등반길 안내와 짐 나르기를 해요.","셰르파예요."],"asset":{"type":"passage","lines":["「세계의 지붕」 히말라야산맥의 가장 높은 봉우리 에베레스트산에 오르려고","네팔을 찾는 관광객이 많아요.","네팔 주민들은 관광객에게 음식과 잠자리를 내주고,","등반길을 안내하고 짐을 들어 주는 셰르파로 일하며 수입을 얻어요.","그러나 관광객들이 버린 쓰레기로 에베레스트산은 몸살을 앓고 있어요.","네팔 정부는 관광객이 자기 쓰레기를 가지고 내려오게 하고,","쓰레기 처리 비용만큼 입산료를 받았다가 쓰레기를 가져오면 돌려줘요."],"title":"교과서 18쪽 에베레스트산의 빛과 그림자"},"mis":"SO6-2-u1-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L02_challenge#2','soc',6,2,'u1','L02','tb_g6_2_soc_u1_L02_challenge','lesson_challenge','SO6-2-u1-C2',2,'mc','auto','네팔 정부가 에베레스트산의 쓰레기 문제를 줄이려고 한 노력으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X07']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C2","difficulty":2,"kind":"mc","stem":"네팔 정부가 에베레스트산의 쓰레기 문제를 줄이려고 한 노력으로 알맞은 것은 무엇인가요?","options":[{"t":"쓰레기 처리 비용만큼 입산료를 받았다가 쓰레기를 가져오면 돌려줘요","correct":true},{"t":"관광객이 쓰레기를 산에 두고 오게 해요","mis":"SO6-2-u1-X07"},{"t":"관광객을 모두 돌려보내고 주민도 일을 그만두게 해요","mis":"SO6-2-u1-X07"},{"t":"쓰레기를 치우지 않고 그대로 둬요","mis":"SO6-2-u1-X07"}],"explanation":["이야기 끝부분을 읽어요.","자기 쓰레기를 가지고 내려오게 해요.","입산료를 받았다가 돌려줘요."],"asset":{"type":"passage","lines":["「세계의 지붕」 히말라야산맥의 가장 높은 봉우리 에베레스트산에 오르려고","네팔을 찾는 관광객이 많아요.","네팔 주민들은 관광객에게 음식과 잠자리를 내주고,","등반길을 안내하고 짐을 들어 주는 셰르파로 일하며 수입을 얻어요.","그러나 관광객들이 버린 쓰레기로 에베레스트산은 몸살을 앓고 있어요.","네팔 정부는 관광객이 자기 쓰레기를 가지고 내려오게 하고,","쓰레기 처리 비용만큼 입산료를 받았다가 쓰레기를 가져오면 돌려줘요."],"title":"교과서 18쪽 에베레스트산의 빛과 그림자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L02_challenge#3','soc',6,2,'u1','L02','tb_g6_2_soc_u1_L02_challenge','lesson_challenge','SO6-2-u1-C2',3,'mc','auto','에베레스트산에서 관광객이 버린 쓰레기를 치우는 일이 특히 어려운 까닭은 무엇인가요?',ARRAY['SO6-2-u1-X04','SO6-2-u1-X02']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C2","difficulty":3,"kind":"mc","stem":"에베레스트산에서 관광객이 버린 쓰레기를 치우는 일이 특히 어려운 까닭은 무엇인가요?","options":[{"t":"해발 고도가 매우 높아 산소가 부족하고 날씨 변화가 심하기 때문이에요","correct":true},{"t":"해발 고도가 낮아 쓰레기가 바다로 흘러가기 때문이에요","mis":"SO6-2-u1-X04"},{"t":"산이 평평해서 쓰레기가 잘 보이지 않기 때문이에요","mis":"SO6-2-u1-X04"},{"t":"그 산에 오르는 사람이 아무도 없기 때문이에요","mis":"SO6-2-u1-X02"}],"explanation":["해발 고도를 떠올려요.","아주 높은 곳은 산소가 부족해요.","날씨도 자주 바뀌어 치우기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L02_challenge#4','soc',6,2,'u1','L02','tb_g6_2_soc_u1_L02_challenge','lesson_challenge','SO6-2-u1-C2',3,'mc','auto','친구와 묻고 답하기 활동에서 「칠레 파리나코타 화산 지역 사람들의 생활 모습은 어떨까요?」라는 질문에 알맞은 답은 무엇인가요?',ARRAY['SO6-2-u1-X20','SO6-2-u1-X04','SO6-2-u1-X03']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C2","difficulty":3,"kind":"mc","stem":"친구와 묻고 답하기 활동에서 「칠레 파리나코타 화산 지역 사람들의 생활 모습은 어떨까요?」라는 질문에 알맞은 답은 무엇인가요?","options":[{"t":"화산을 보러 온 관광객에게 여행을 안내하거나 물건을 팔아요","correct":true},{"t":"화산 근처에는 아무도 살지 않아요","mis":"SO6-2-u1-X20"},{"t":"산 정상에서 스키장만 운영해요","mis":"SO6-2-u1-X04"},{"t":"넓은 모래 언덕에서 보드를 타요","mis":"SO6-2-u1-X03"}],"explanation":["화산 지역의 경관을 떠올려요.","독특한 경관을 보러 관광객이 와요.","관광객을 상대로 일해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L02_challenge#5','soc',6,2,'u1','L02','tb_g6_2_soc_u1_L02_challenge','lesson_challenge','SO6-2-u1-C2',3,'ox','auto','모든 산은 정상이 뾰족하게 생겼어요.',ARRAY['SO6-2-u1-X04']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C2","difficulty":3,"kind":"ox","stem":"모든 산은 정상이 뾰족하게 생겼어요.","answer":"X","reason_options":[{"t":"산 정상이 움푹 파이거나 물이 고인 화산도 있고, 고원처럼 넓고 평평한 곳도 있기 때문에","correct":true},{"t":"산지는 모두 높고 뾰족하기 때문에","mis":"SO6-2-u1-X04"}],"mis":"SO6-2-u1-X04","explanation":["산지의 여러 모습을 떠올려요.","화산과 고원은 정상이 뾰족하지 않아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L02_challenge#6','soc',6,2,'u1','L02','tb_g6_2_soc_u1_L02_challenge','lesson_challenge','SO6-2-u1-C2',3,'mc','auto','산지의 모습과 그곳 사람들이 땅을 이용하는 방법을 바르게 짝지은 것은 무엇인가요?',ARRAY['SO6-2-u1-X04','SO6-2-u1-X03']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C2","difficulty":3,"kind":"mc","stem":"산지의 모습과 그곳 사람들이 땅을 이용하는 방법을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"경사가 가파른 곳 — 계단식 농사","correct":true},{"t":"비교적 평탄하고 풀이 잘 자라는 곳 — 계단식 논 만들기","mis":"SO6-2-u1-X04"},{"t":"지하자원이 풍부한 곳 — 스키장","mis":"SO6-2-u1-X03"},{"t":"아름다운 지형 경관 — 광업","mis":"SO6-2-u1-X03"}],"explanation":["교과서 16~17쪽 글을 읽어요.","가파른 곳은 계단식, 평탄한 곳은 가축이에요.","지하자원은 광업, 경관은 관광이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L02_challenge#7','soc',6,2,'u1','L02','tb_g6_2_soc_u1_L02_challenge','lesson_challenge','SO6-2-u1-C2',3,'error','auto','산지 지형의 생활 모습을 두고 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.',ARRAY['SO6-2-u1-X04','SO6-2-u1-X03']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C2","difficulty":3,"kind":"error","stem":"산지 지형의 생활 모습을 두고 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.","options":[{"t":"친구 나 — 「경사가 급한 산지는 관광지로 이용하지 못해.」","correct":true,"mis_target":"SO6-2-u1-X04"},{"t":"친구 가 — 「화산 주변에는 온천이 있어 관광객이 찾아와.」","mis":"SO6-2-u1-X04"},{"t":"친구 다 — 「지하자원이 풍부한 곳에서는 광업이 발달하기도 해.」","mis":"SO6-2-u1-X03"}],"explanation":["알프스산맥을 떠올려요.","아름다운 산지는 스키장, 휴양림이 돼요.","친구 나의 말이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L02_challenge#8','soc',6,2,'u1','L02','tb_g6_2_soc_u1_L02_challenge','lesson_challenge','SO6-2-u1-C2',4,'mc','auto','네팔 정부처럼 입산료를 받고 쓰레기를 가져오면 돌려주는 방법이 좋은 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X07']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C2","difficulty":4,"kind":"mc","stem":"네팔 정부처럼 입산료를 받고 쓰레기를 가져오면 돌려주는 방법이 좋은 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"관광으로 얻는 수입은 지키면서 산의 환경도 보호할 수 있기 때문이에요","correct":true},{"t":"관광객을 한 명도 받지 않게 되기 때문이에요","mis":"SO6-2-u1-X07"},{"t":"쓰레기가 더 쌓여도 상관없기 때문이에요","mis":"SO6-2-u1-X07"},{"t":"주민들이 관광 일을 그만두게 되기 때문이에요","mis":"SO6-2-u1-X07"}],"explanation":["관광의 좋은 점과 걱정을 함께 봐요.","관광객은 계속 올 수 있어요.","쓰레기는 되가져오니 환경도 지켜요."],"asset":{"type":"passage","lines":["「세계의 지붕」 히말라야산맥의 가장 높은 봉우리 에베레스트산에 오르려고","네팔을 찾는 관광객이 많아요.","네팔 주민들은 관광객에게 음식과 잠자리를 내주고,","등반길을 안내하고 짐을 들어 주는 셰르파로 일하며 수입을 얻어요.","그러나 관광객들이 버린 쓰레기로 에베레스트산은 몸살을 앓고 있어요.","네팔 정부는 관광객이 자기 쓰레기를 가지고 내려오게 하고,","쓰레기 처리 비용만큼 입산료를 받았다가 쓰레기를 가져오면 돌려줘요."],"title":"교과서 18쪽 에베레스트산의 빛과 그림자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L02_challenge#9','soc',6,2,'u1','L02','tb_g6_2_soc_u1_L02_challenge','lesson_challenge','SO6-2-u1-C2',4,'essay','teacher','에베레스트산에 관광객이 찾아오면서 생긴 좋은 점과 문제점을 하나씩 쓰고, 문제를 줄이기 위한 나의 생각을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u1-C2","difficulty":4,"kind":"essay","stem":"에베레스트산에 관광객이 찾아오면서 생긴 좋은 점과 문제점을 하나씩 쓰고, 문제를 줄이기 위한 나의 생각을 쓰세요.","answer_guide":{"answer":"예: 좋은 점 — 네팔 주민들이 관광객에게 음식과 잠자리를 내주거나 셰르파로 일하며 수입을 얻어요. 문제점 — 관광객이 버린 쓰레기로 산이 오염돼요. 내 생각 — 산에 오르는 모든 관광객이 자기 쓰레기를 되가져오겠다고 약속하게 하고, 쓰레기가 적게 나오는 등반 준비물을 안내하면 좋겠어요.","scoring_points":["좋은 점을 썼는가","문제점을 썼는가","두 면을 생각한 나의 의견을 썼는가"]},"explanation":["빛과 그림자를 나눠요.","좋은 점과 문제점을 하나씩 써요.","문제를 줄일 방법을 생각해요."],"asset":{"type":"passage","lines":["「세계의 지붕」 히말라야산맥의 가장 높은 봉우리 에베레스트산에 오르려고","네팔을 찾는 관광객이 많아요.","네팔 주민들은 관광객에게 음식과 잠자리를 내주고,","등반길을 안내하고 짐을 들어 주는 셰르파로 일하며 수입을 얻어요.","그러나 관광객들이 버린 쓰레기로 에베레스트산은 몸살을 앓고 있어요.","네팔 정부는 관광객이 자기 쓰레기를 가지고 내려오게 하고,","쓰레기 처리 비용만큼 입산료를 받았다가 쓰레기를 가져오면 돌려줘요."],"title":"교과서 18쪽 에베레스트산의 빛과 그림자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L02_challenge#10','soc',6,2,'u1','L02','tb_g6_2_soc_u1_L02_challenge','lesson_challenge','SO6-2-u1-C2',4,'essay','teacher','산지 지형의 특징 하나를 쓰고, 사람들이 그 특징을 이겨 내거나 이용하며 살아가는 모습을 교과서 16~17쪽의 예와 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u1-C2","difficulty":4,"kind":"essay","stem":"산지 지형의 특징 하나를 쓰고, 사람들이 그 특징을 이겨 내거나 이용하며 살아가는 모습을 교과서 16~17쪽의 예와 함께 쓰세요.","answer_guide":{"answer":"예: 산지는 해발 고도가 높고 대체로 경사가 급해요. 필리핀 바나우에 사람들은 가파른 산비탈을 계단처럼 다듬어 논을 만들고 농사를 지어요. 또 스위스 알프스산맥처럼 아름다운 경관을 관광지로 이용하기도 해요.","scoring_points":["산지 지형의 특징을 썼는가","특징을 이겨 내거나 이용하는 모습을 썼는가","교과서의 알맞은 예를 들었는가"]},"explanation":["산지의 특징을 떠올려요.","사람들이 땅을 어떻게 이용했나 찾아요.","교과서 예와 이어 써요."],"asset":{"type":"passage","lines":["㉠ 파미르고원(타지키스탄) — 땅이 비교적 평탄하고 풀이 잘 자라 양을 키움","㉡ 알프스산맥(스위스) — 아름다운 지형 경관을 이용한 관광지가 발달함","㉢ 추키카마타(칠레) — 구리 매장량이 많아 광업이 발달함","㉣ 아이슬란드 — 화산 분출을 볼 수 있는 지역을 관광지로 활용함","㉤ 바나우에(필리핀) — 산비탈을 따라 만든 계단식 논"],"numbered":false,"title":"교과서 16~17쪽 산지를 이용하는 사람들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L03_basic#1','soc',6,2,'u1','L03','tb_g6_2_soc_u1_L03_basic','lesson_basic','SO6-2-u1-C3',1,'blank','auto','「세계에는 계곡, 평야, 폭포 등 다양한 (    ) 지형 경관이 있습니다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C3","difficulty":1,"kind":"blank","stem":"「세계에는 계곡, 평야, 폭포 등 다양한 (    ) 지형 경관이 있습니다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"하천","correct":true},{"t":"산지","mis":"SO6-2-u1-X03"},{"t":"해안","mis":"SO6-2-u1-X03"},{"t":"사막","mis":"SO6-2-u1-X03"}],"explanation":["꼭 기억해요 첫 문장이에요.","강을 따라 나타나는 경관이에요.","하천이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L03_basic#2','soc',6,2,'u1','L03','tb_g6_2_soc_u1_L03_basic','lesson_basic','SO6-2-u1-C3',1,'sa','auto','타이 짜오프라야강처럼 강을 따라 배 위에서 물건을 사고파는 곳을 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u1-C3","difficulty":1,"kind":"sa","stem":"타이 짜오프라야강처럼 강을 따라 배 위에서 물건을 사고파는 곳을 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["수상 시장","수상시장"],"explanation":["교과서 21쪽 짜오프라야강 사진이에요.","배 위에서 물건을 사고팔아요.","수상 시장이에요."],"mis":"SO6-2-u1-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L03_basic#3','soc',6,2,'u1','L03','tb_g6_2_soc_u1_L03_basic','lesson_basic','SO6-2-u1-C3',1,'mc','auto','「많은 물이 절벽 아래로 큰 소리를 내며 떨어지고 있어.」라는 설명에 맞는 하천 지형은 무엇인가요?',ARRAY['SO6-2-u1-X03']::text[],true,'{"seq":3,"concept":"SO6-2-u1-C3","difficulty":1,"kind":"mc","stem":"「많은 물이 절벽 아래로 큰 소리를 내며 떨어지고 있어.」라는 설명에 맞는 하천 지형은 무엇인가요?","options":[{"t":"빅토리아 폭포","correct":true},{"t":"아마존강","mis":"SO6-2-u1-X03"},{"t":"나일강 평야","mis":"SO6-2-u1-X03"},{"t":"호스슈 벤드 계곡","mis":"SO6-2-u1-X03"}],"explanation":["설명 속 장면을 떠올려요.","물이 절벽 아래로 떨어져요.","빅토리아 폭포예요."],"asset":{"type":"passage","lines":["㉠ 아마존강(브라질)","㉡ 나일강 평야(이집트)","㉢ 호스슈 벤드 계곡(미국)","㉣ 빅토리아 폭포(잠비아, 짐바브웨) — 현지에서는 「모시 오아 툰야」 폭포"],"numbered":false,"title":"교과서 19쪽 하천 지형 넷"},"variant_rule":{"alt":[{"stem":"「깊은 계곡 사이로 강물이 말발굽 모양으로 흐르고 있어.」라는 설명에 맞는 하천 지형은 무엇인가요?","options":[{"t":"호스슈 벤드 계곡","correct":true},{"t":"빅토리아 폭포","mis":"SO6-2-u1-X03"},{"t":"아마존강","mis":"SO6-2-u1-X03"},{"t":"나일강 평야","mis":"SO6-2-u1-X03"}],"explanation":["설명 속 장면을 떠올려요.","강물이 말발굽 모양으로 굽어 흘러요.","호스슈 벤드 계곡이에요."],"asset":{"type":"passage","lines":["㉠ 아마존강(브라질)","㉡ 나일강 평야(이집트)","㉢ 호스슈 벤드 계곡(미국)","㉣ 빅토리아 폭포(잠비아, 짐바브웨) — 현지에서는 「모시 오아 툰야」 폭포"],"numbered":false,"title":"교과서 19쪽 하천 지형 넷"}},{"stem":"「강 옆으로 매우 넓은 농경지가 보여.」라는 설명에 맞는 하천 지형은 무엇인가요?","options":[{"t":"나일강 평야","correct":true},{"t":"호스슈 벤드 계곡","mis":"SO6-2-u1-X03"},{"t":"빅토리아 폭포","mis":"SO6-2-u1-X03"},{"t":"아마존강","mis":"SO6-2-u1-X03"}],"explanation":["설명 속 장면을 떠올려요.","강 옆에 넓은 농경지가 있어요.","이집트의 나일강 평야예요."],"asset":{"type":"passage","lines":["㉠ 아마존강(브라질)","㉡ 나일강 평야(이집트)","㉢ 호스슈 벤드 계곡(미국)","㉣ 빅토리아 폭포(잠비아, 짐바브웨) — 현지에서는 「모시 오아 툰야」 폭포"],"numbered":false,"title":"교과서 19쪽 하천 지형 넷"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L03_basic#4','soc',6,2,'u1','L03','tb_g6_2_soc_u1_L03_basic','lesson_basic','SO6-2-u1-C3',1,'mc','auto','노르웨이 사람들이 풍부한 물을 이용하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X05']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C3","difficulty":1,"kind":"mc","stem":"노르웨이 사람들이 풍부한 물을 이용하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"수력 발전으로 전기의 대부분을 만들어요","correct":true},{"t":"배 위에서 물건을 사고팔아요","mis":"SO6-2-u1-X05"},{"t":"강에 통나무를 띄워 옮겨요","mis":"SO6-2-u1-X05"},{"t":"대형 농기계로 넓은 평야에서 농사지어요","mis":"SO6-2-u1-X05"}],"explanation":["사진 ㉢ 설명을 읽어요.","흐르는 물의 힘을 써요.","수력 발전으로 전기를 만들어요."],"asset":{"type":"passage","lines":["㉠ 콩고강(콩고 민주 공화국) — 독특한 도구를 만들어 물고기를 잡음","㉡ 일리노이강(미국) 주변 넓은 평야 — 대형 농기계나 비행기로 농사","㉢ 노르웨이 — 전기의 대부분을 수력 발전으로 생산함","㉣ 이구아수 폭포(브라질과 아르헨티나 사이) — 웅장한 경관을 보러 관광객이 옴","㉤ 짜오프라야강(타이) — 수상 시장에서 배 위에서 물건을 사고팖","㉥ 프레이저강(캐나다) — 강에 통나무를 띄워 옮김"],"numbered":false,"title":"교과서 20~21쪽 하천을 이용하는 사람들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L03_basic#5','soc',6,2,'u1','L03','tb_g6_2_soc_u1_L03_basic','lesson_basic','SO6-2-u1-C3',2,'match','auto','교과서 20~21쪽의 하천과 사람들이 하천을 이용하는 모습을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u1-C3","difficulty":2,"kind":"match","stem":"교과서 20~21쪽의 하천과 사람들이 하천을 이용하는 모습을 이으세요.","pairs":[{"l":"콩고강","r":"독특한 도구로 물고기 잡기"},{"l":"일리노이강 주변 평야","r":"대형 농기계와 비행기로 농사"},{"l":"이구아수 폭포","r":"웅장한 경관을 보러 오는 관광"},{"l":"짜오프라야강","r":"배 위에서 물건을 사고파는 시장"}],"mis":"SO6-2-u1-X05","explanation":["사진 설명을 하나씩 읽어요.","강은 물고기와 넓은 평야를 줘요.","폭포는 관광, 강길은 시장이 돼요."],"asset":{"type":"passage","lines":["㉠ 콩고강(콩고 민주 공화국) — 독특한 도구를 만들어 물고기를 잡음","㉡ 일리노이강(미국) 주변 넓은 평야 — 대형 농기계나 비행기로 농사","㉢ 노르웨이 — 전기의 대부분을 수력 발전으로 생산함","㉣ 이구아수 폭포(브라질과 아르헨티나 사이) — 웅장한 경관을 보러 관광객이 옴","㉤ 짜오프라야강(타이) — 수상 시장에서 배 위에서 물건을 사고팖","㉥ 프레이저강(캐나다) — 강에 통나무를 띄워 옮김"],"numbered":false,"title":"교과서 20~21쪽 하천을 이용하는 사람들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L03_basic#6','soc',6,2,'u1','L03','tb_g6_2_soc_u1_L03_basic','lesson_basic','SO6-2-u1-C3',2,'mc','auto','하천 주변에 넓은 평야가 발달하는 까닭은 무엇인가요?',ARRAY['SO6-2-u1-X03','SO6-2-u1-X06','SO6-2-u1-X05']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C3","difficulty":2,"kind":"mc","stem":"하천 주변에 넓은 평야가 발달하는 까닭은 무엇인가요?","options":[{"t":"하천이 운반한 여러 가지 퇴적물이 하천 주변에 쌓이기 때문이에요","correct":true},{"t":"하천 주변의 산이 모두 무너지기 때문이에요","mis":"SO6-2-u1-X03"},{"t":"사람들이 바다를 메워 만들기 때문이에요","mis":"SO6-2-u1-X06"},{"t":"하천에는 물이 흐르지 않기 때문이에요","mis":"SO6-2-u1-X05"}],"explanation":["강물이 흙과 모래를 날라요.","날라 온 것이 강 주변에 쌓여요.","그래서 넓은 평야가 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L03_basic#7','soc',6,2,'u1','L03','tb_g6_2_soc_u1_L03_basic','lesson_basic','SO6-2-u1-C3',2,'mc','auto','세계에서 유명한 폭포 셋을 바르게 모은 것은 무엇인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C3","difficulty":2,"kind":"mc","stem":"세계에서 유명한 폭포 셋을 바르게 모은 것은 무엇인가요?","options":[{"t":"이구아수 폭포, 나이아가라 폭포, 빅토리아 폭포","correct":true},{"t":"이구아수 폭포, 아마존강, 빅토리아 폭포","mis":"SO6-2-u1-X03"},{"t":"나이아가라 폭포, 바나우에, 이구아수 폭포","mis":"SO6-2-u1-X03"},{"t":"빅토리아 폭포, 울루루, 나이아가라 폭포","mis":"SO6-2-u1-X03"}],"explanation":["교과서 21쪽 물음을 떠올려요.","폭포 이름을 셋 찾아요.","이구아수, 나이아가라, 빅토리아예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L03_basic#8','soc',6,2,'u1','L03','tb_g6_2_soc_u1_L03_basic','lesson_basic','SO6-2-u1-C3',2,'ox','auto','캐나다 프레이저강에서는 강에 통나무를 띄워 작은 배로 많은 양의 통나무를 옮겨요.',ARRAY['SO6-2-u1-X05']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C3","difficulty":2,"kind":"ox","stem":"캐나다 프레이저강에서는 강에 통나무를 띄워 작은 배로 많은 양의 통나무를 옮겨요.","answer":"O","reason_options":[{"t":"하천을 이용하면 크고 무거운 물건도 적은 힘으로 쉽게 나를 수 있기 때문에","correct":true},{"t":"강물은 물건을 옮기는 데 쓸 수 없기 때문에","mis":"SO6-2-u1-X05"}],"mis":"SO6-2-u1-X05","explanation":["친구와 활동 사진이에요.","물에 띄우면 무거운 것도 쉽게 옮겨요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 콩고강(콩고 민주 공화국) — 독특한 도구를 만들어 물고기를 잡음","㉡ 일리노이강(미국) 주변 넓은 평야 — 대형 농기계나 비행기로 농사","㉢ 노르웨이 — 전기의 대부분을 수력 발전으로 생산함","㉣ 이구아수 폭포(브라질과 아르헨티나 사이) — 웅장한 경관을 보러 관광객이 옴","㉤ 짜오프라야강(타이) — 수상 시장에서 배 위에서 물건을 사고팖","㉥ 프레이저강(캐나다) — 강에 통나무를 띄워 옮김"],"numbered":false,"title":"교과서 20~21쪽 하천을 이용하는 사람들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L03_basic#9','soc',6,2,'u1','L03','tb_g6_2_soc_u1_L03_basic','lesson_basic','SO6-2-u1-C3',2,'mc','auto','콩고강에 사는 사람들이 독특한 도구를 만들어 물고기를 잡는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X05','SO6-2-u1-X03']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C3","difficulty":2,"kind":"mc","stem":"콩고강에 사는 사람들이 독특한 도구를 만들어 물고기를 잡는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"강이 크고 넓어 수산 자원이 풍부하기 때문이에요","correct":true},{"t":"강물이 말라 물고기가 땅 위에 있기 때문이에요","mis":"SO6-2-u1-X05"},{"t":"강 주변이 모두 모래 언덕이기 때문이에요","mis":"SO6-2-u1-X03"},{"t":"물살이 빠른 강에는 물고기가 살지 않기 때문이에요","mis":"SO6-2-u1-X05"}],"explanation":["콩고강은 크고 넓어요.","물고기 같은 수산 자원이 많아요.","그래서 물고기를 잡으며 살아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L03_basic#10','soc',6,2,'u1','L03','tb_g6_2_soc_u1_L03_basic','lesson_basic','SO6-2-u1-C3',3,'error','auto','하천 지형에서 볼 수 있는 모습을 두고 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.',ARRAY['SO6-2-u1-X05']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C3","difficulty":3,"kind":"error","stem":"하천 지형에서 볼 수 있는 모습을 두고 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.","options":[{"t":"친구 다 — 「하천은 물살이 빨라서 어업이 이루어질 수 없어.」","correct":true,"mis_target":"SO6-2-u1-X05"},{"t":"친구 가 — 「물을 이용해 전기를 만들기도 해.」","mis":"SO6-2-u1-X05"},{"t":"친구 나 — 「강을 따라 시장이 생기기도 해.」","mis":"SO6-2-u1-X05"}],"explanation":["콩고강을 떠올려요.","물살이 빠른 곳에서도 도구를 만들어 물고기를 잡아요.","친구 다의 말이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L03_challenge#1','soc',6,2,'u1','L03','tb_g6_2_soc_u1_L03_challenge','lesson_challenge','SO6-2-u1-C3',2,'sa','auto','미국 일리노이강 주변의 넓은 평야에서 대형 농기계와 함께 농사에 쓰는 탈것은 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u1-C3","difficulty":2,"kind":"sa","stem":"미국 일리노이강 주변의 넓은 평야에서 대형 농기계와 함께 농사에 쓰는 탈것은 무엇인가요? 세 글자로 쓰세요.","answer":["비행기"],"explanation":["사진 ㉡ 설명을 읽어요.","하늘에서 농약을 뿌려요.","비행기예요."],"asset":{"type":"passage","lines":["㉠ 콩고강(콩고 민주 공화국) — 독특한 도구를 만들어 물고기를 잡음","㉡ 일리노이강(미국) 주변 넓은 평야 — 대형 농기계나 비행기로 농사","㉢ 노르웨이 — 전기의 대부분을 수력 발전으로 생산함","㉣ 이구아수 폭포(브라질과 아르헨티나 사이) — 웅장한 경관을 보러 관광객이 옴","㉤ 짜오프라야강(타이) — 수상 시장에서 배 위에서 물건을 사고팖","㉥ 프레이저강(캐나다) — 강에 통나무를 띄워 옮김"],"numbered":false,"title":"교과서 20~21쪽 하천을 이용하는 사람들"},"mis":"SO6-2-u1-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L03_challenge#2','soc',6,2,'u1','L03','tb_g6_2_soc_u1_L03_challenge','lesson_challenge','SO6-2-u1-C3',2,'mc','auto','타이 짜오프라야강에 수상 시장이 발달한 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X05','SO6-2-u1-X03']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C3","difficulty":2,"kind":"mc","stem":"타이 짜오프라야강에 수상 시장이 발달한 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"하천을 따라 배로 물건을 실어 나르기 편리하기 때문이에요","correct":true},{"t":"강물이 얼어 그 위를 걸어 다닐 수 있기 때문이에요","mis":"SO6-2-u1-X05"},{"t":"강 주변에 시장을 세울 땅이 아주 넓기 때문이에요","mis":"SO6-2-u1-X05"},{"t":"바다와 육지가 만나는 곳이기 때문이에요","mis":"SO6-2-u1-X03"}],"explanation":["수상 시장은 배 위의 시장이에요.","강이 길이 되어요.","배로 물건을 나르기 편리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L03_challenge#3','soc',6,2,'u1','L03','tb_g6_2_soc_u1_L03_challenge','lesson_challenge','SO6-2-u1-C3',3,'mc','auto','이구아수 폭포에 해마다 세계 곳곳에서 관광객이 찾아오는 까닭은 무엇인가요?',ARRAY['SO6-2-u1-X05','SO6-2-u1-X03']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C3","difficulty":3,"kind":"mc","stem":"이구아수 폭포에 해마다 세계 곳곳에서 관광객이 찾아오는 까닭은 무엇인가요?","options":[{"t":"규모가 크고 지형 경관이 아름답기 때문이에요","correct":true},{"t":"물이 흐르지 않는 마른 폭포이기 때문이에요","mis":"SO6-2-u1-X05"},{"t":"폭포 주변에 구리 광산이 있기 때문이에요","mis":"SO6-2-u1-X03"},{"t":"폭포에서 소금을 만들 수 있기 때문이에요","mis":"SO6-2-u1-X03"}],"explanation":["사진 ㉣ 설명을 읽어요.","웅장한 경관이 있어요.","그것을 보러 관광객이 와요."],"asset":{"type":"passage","lines":["㉠ 콩고강(콩고 민주 공화국) — 독특한 도구를 만들어 물고기를 잡음","㉡ 일리노이강(미국) 주변 넓은 평야 — 대형 농기계나 비행기로 농사","㉢ 노르웨이 — 전기의 대부분을 수력 발전으로 생산함","㉣ 이구아수 폭포(브라질과 아르헨티나 사이) — 웅장한 경관을 보러 관광객이 옴","㉤ 짜오프라야강(타이) — 수상 시장에서 배 위에서 물건을 사고팖","㉥ 프레이저강(캐나다) — 강에 통나무를 띄워 옮김"],"numbered":false,"title":"교과서 20~21쪽 하천을 이용하는 사람들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L03_challenge#4','soc',6,2,'u1','L03','tb_g6_2_soc_u1_L03_challenge','lesson_challenge','SO6-2-u1-C3',3,'ox','auto','노르웨이는 강이 많고 물의 양이 풍부해 수력 발전에 유리해요.',ARRAY['SO6-2-u1-X05']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C3","difficulty":3,"kind":"ox","stem":"노르웨이는 강이 많고 물의 양이 풍부해 수력 발전에 유리해요.","answer":"O","reason_options":[{"t":"교과서 20쪽처럼 노르웨이는 전기의 대부분을 수력 발전으로 생산하기 때문에","correct":true},{"t":"수력 발전은 물이 적은 곳에서만 할 수 있기 때문에","mis":"SO6-2-u1-X05"}],"mis":"SO6-2-u1-X05","explanation":["수력 발전은 물의 힘을 써요.","물이 많을수록 유리해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L03_challenge#5','soc',6,2,'u1','L03','tb_g6_2_soc_u1_L03_challenge','lesson_challenge','SO6-2-u1-C3',3,'mc','auto','여행 기획자가 하는 일로 알맞지 않은 것은 무엇인가요?',ARRAY['SO6-2-u1-X17']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C3","difficulty":3,"kind":"mc","stem":"여행 기획자가 하는 일로 알맞지 않은 것은 무엇인가요?","options":[{"t":"여행지를 가 보지 않고 이름만 보고 여행 상품을 만들어요","correct":true},{"t":"유명한 관광지나 잘 알려지지 않은 장소를 찾아 자료를 모아요","mis":"SO6-2-u1-X17"},{"t":"실제로 방문하여 여행 상품을 개발해요","mis":"SO6-2-u1-X17"},{"t":"건축 여행, 철도 여행 같은 특별한 상품을 만들어요","mis":"SO6-2-u1-X17"}],"explanation":["별별 직업 글을 읽어요.","여행 기획자는 실제로 방문해 봐요.","이름만 보고 만들지 않아요."],"asset":{"type":"passage","lines":["하는 일 — 유명한 관광지나 잘 알려지지 않은 장소를 찾아 자료를 모으고,","　실제로 방문하여 여행 상품을 개발해요(건축 여행, 철도 여행 등).","필요한 것 — 여행을 좋아하고 새로운 것에 관심을 두며 모험을 즐기는 마음,","　여러 사람과 함께 일하므로 원만한 대인 관계 능력"],"numbered":false,"title":"교과서 22쪽 별별 직업 — 여행 기획자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L03_challenge#6','soc',6,2,'u1','L03','tb_g6_2_soc_u1_L03_challenge','lesson_challenge','SO6-2-u1-C3',3,'mc','auto','생활 일기 예시를 쓴 아이가 사는 곳의 생활 모습으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X05']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C3","difficulty":3,"kind":"mc","stem":"생활 일기 예시를 쓴 아이가 사는 곳의 생활 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"물살이 거센 강에 통발을 설치해 물고기를 잡아요","correct":true},{"t":"넓은 평야에서 비행기로 농약을 뿌려요","mis":"SO6-2-u1-X05"},{"t":"폭포를 보러 온 관광객에게 표를 팔아요","mis":"SO6-2-u1-X05"},{"t":"흐르는 물의 힘으로 전기를 만들어요","mis":"SO6-2-u1-X05"}],"explanation":["일기 속 장면을 찾아요.","급류에 통발을 설치했어요.","강에서 물고기를 잡아요."],"asset":{"type":"passage","lines":["오늘은 날씨가 맑아 강으로 물고기를 잡으러 갔다.","어제 비가 내려서인지 강물이 무척 불어나 있었다.","물고기 잡는 일은 항상 위험해서 아버지는 늘 조심하라고 하신다.","미리 설치해 둔 통발 속 물고기를 잡으려고 어른들은 급류로 들어가셨다.","나도 통발을 들어 물고기를 건졌다."],"title":"활동지 예시 — 콩고강 마을 아이의 생활 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L03_challenge#7','soc',6,2,'u1','L03','tb_g6_2_soc_u1_L03_challenge','lesson_challenge','SO6-2-u1-C3',3,'error','auto','교과서 19쪽 하천 지형을 보고 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C3","difficulty":3,"kind":"error","stem":"교과서 19쪽 하천 지형을 보고 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.","options":[{"t":"친구 나 — 「나일강 주변에는 울창한 숲만 있고 농경지는 없어.」","correct":true,"mis_target":"SO6-2-u1-X03"},{"t":"친구 가 — 「아마존강은 울창한 숲 사이로 구불구불 흘러.」","mis":"SO6-2-u1-X03"},{"t":"친구 다 — 「호스슈 벤드 계곡에서는 강물이 말발굽 모양으로 흘러.」","mis":"SO6-2-u1-X03"}],"explanation":["나일강 평야를 떠올려요.","강 옆으로 매우 넓은 농경지가 보여요.","친구 나가 바꿔 말했어요."],"asset":{"type":"passage","lines":["㉠ 아마존강(브라질)","㉡ 나일강 평야(이집트)","㉢ 호스슈 벤드 계곡(미국)","㉣ 빅토리아 폭포(잠비아, 짐바브웨) — 현지에서는 「모시 오아 툰야」 폭포"],"numbered":false,"title":"교과서 19쪽 하천 지형 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L03_challenge#8','soc',6,2,'u1','L03','tb_g6_2_soc_u1_L03_challenge','lesson_challenge','SO6-2-u1-C3',4,'mc','auto','하천을 이용하는 생활 모습과 그 까닭을 바르게 이은 것은 무엇인가요?',ARRAY['SO6-2-u1-X05']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C3","difficulty":4,"kind":"mc","stem":"하천을 이용하는 생활 모습과 그 까닭을 바르게 이은 것은 무엇인가요?","options":[{"t":"일리노이강 주변에서 비행기로 농사를 지어요 — 하천 주변에 넓은 평야가 있기 때문이에요","correct":true},{"t":"프레이저강에서 통나무를 옮겨요 — 하천에는 물이 거의 없기 때문이에요","mis":"SO6-2-u1-X05"},{"t":"노르웨이에서 수력 발전을 해요 — 강이 적고 물이 부족하기 때문이에요","mis":"SO6-2-u1-X05"},{"t":"짜오프라야강에서 수상 시장이 열려요 — 강에는 배가 다닐 수 없기 때문이에요","mis":"SO6-2-u1-X05"}],"explanation":["생활 모습마다 까닭을 따져요.","넓은 평야가 있어 큰 규모로 농사지어요.","나머지는 까닭이 거꾸로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L03_challenge#9','soc',6,2,'u1','L03','tb_g6_2_soc_u1_L03_challenge','lesson_challenge','SO6-2-u1-C3',4,'essay','teacher','하천 지형에 사는 사람이 되어 하루 생활 일기를 써 보세요. 어느 하천인지 밝히고, 그 하천을 이용하는 모습이 드러나게 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u1-C3","difficulty":4,"kind":"essay","stem":"하천 지형에 사는 사람이 되어 하루 생활 일기를 써 보세요. 어느 하천인지 밝히고, 그 하천을 이용하는 모습이 드러나게 쓰세요.","answer_guide":{"answer":"예: 나는 타이 짜오프라야강 옆에 살아요. 아침 일찍 엄마와 배에 과일을 싣고 수상 시장으로 갔어요. 배 위에서 손님에게 과일을 팔았어요. 강이 길이 되어 무거운 물건도 쉽게 옮길 수 있어 좋아요.","scoring_points":["하천 이름을 밝혔는가","하천을 이용하는 생활 모습을 썼는가","하천 지형과 생활이 어울리는가"]},"explanation":["하천 하나를 골라요.","그곳 사람들의 하루를 떠올려요.","하천을 이용하는 모습을 넣어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L03_challenge#10','soc',6,2,'u1','L03','tb_g6_2_soc_u1_L03_challenge','lesson_challenge','SO6-2-u1-C3',4,'essay','teacher','여행 기획자가 되어 교과서 19~21쪽의 하천 가운데 한 곳으로 가는 여행 상품을 만들어 보세요. 여행지, 볼거리나 할 거리, 이 상품을 만든 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u1-C3","difficulty":4,"kind":"essay","stem":"여행 기획자가 되어 교과서 19~21쪽의 하천 가운데 한 곳으로 가는 여행 상품을 만들어 보세요. 여행지, 볼거리나 할 거리, 이 상품을 만든 까닭을 쓰세요.","answer_guide":{"answer":"예: 여행지 — 브라질과 아르헨티나 사이의 이구아수 폭포. 할 거리 — 폭포 가까이에서 웅장한 물줄기를 보고 사진을 찍어요. 까닭 — 규모가 크고 지형 경관이 아름다워 많은 사람이 감동할 것 같아서예요.","scoring_points":["여행지를 정했는가","그 하천 지형에 맞는 볼거리를 썼는가","상품을 만든 까닭을 썼는가"]},"explanation":["하천 한 곳을 골라요.","그곳의 경관에 맞는 할 거리를 정해요.","까닭을 덧붙여요."],"asset":{"type":"passage","lines":["하는 일 — 유명한 관광지나 잘 알려지지 않은 장소를 찾아 자료를 모으고,","　실제로 방문하여 여행 상품을 개발해요(건축 여행, 철도 여행 등).","필요한 것 — 여행을 좋아하고 새로운 것에 관심을 두며 모험을 즐기는 마음,","　여러 사람과 함께 일하므로 원만한 대인 관계 능력"],"numbered":false,"title":"교과서 22쪽 별별 직업 — 여행 기획자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L04_basic#1','soc',6,2,'u1','L04','tb_g6_2_soc_u1_L04_basic','lesson_basic','SO6-2-u1-C4',1,'sa','auto','「바다와 육지가 만나는 (    )에는 다양한 지형이 나타납니다.」 빈칸에 알맞은 말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u1-C4","difficulty":1,"kind":"sa","stem":"「바다와 육지가 만나는 (    )에는 다양한 지형이 나타납니다.」 빈칸에 알맞은 말을 두 글자로 쓰세요.","answer":["해안"],"explanation":["꼭 기억해요 첫 문장이에요.","바다와 육지가 만나는 곳이에요.","해안이에요."],"mis":"SO6-2-u1-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L04_basic#2','soc',6,2,'u1','L04','tb_g6_2_soc_u1_L04_basic','lesson_basic','SO6-2-u1-C4',1,'ox','auto','「배가 드나들기에 유리한 해안에는 염전이 발달합니다.」는 바른 문장이에요.',ARRAY['SO6-2-u1-X06']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C4","difficulty":1,"kind":"ox","stem":"「배가 드나들기에 유리한 해안에는 염전이 발달합니다.」는 바른 문장이에요.","answer":"X","reason_options":[{"t":"배가 드나들기에 유리한 해안에는 항구가 발달하고, 염전은 갯벌이 넓게 펼쳐진 해안에 발달하기 때문에","correct":true},{"t":"배와 소금은 늘 함께 다니기 때문에","mis":"SO6-2-u1-X06"}],"mis":"SO6-2-u1-X06","explanation":["꼭 기억해요 둘째 문장이에요.","배가 드나들기 좋은 곳은 항구예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L04_basic#3','soc',6,2,'u1','L04','tb_g6_2_soc_u1_L04_basic','lesson_basic','SO6-2-u1-C4',1,'blank','auto','물고기나 조개 등을 인공적으로 기르는 일을 (    )(이)라고 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-2-u1-X06']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C4","difficulty":1,"kind":"blank","stem":"물고기나 조개 등을 인공적으로 기르는 일을 (    )(이)라고 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"양식업","correct":true},{"t":"광업","mis":"SO6-2-u1-X06"},{"t":"관광업","mis":"SO6-2-u1-X06"},{"t":"어업","mis":"SO6-2-u1-X06"}],"explanation":["교과서 24쪽 낱말 풀이예요.","잡는 것이 아니라 길러요.","양식업이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L04_basic#4','soc',6,2,'u1','L04','tb_g6_2_soc_u1_L04_basic','lesson_basic','SO6-2-u1-C4',1,'mc','auto','교과서 23쪽 포트 캠벨 국립 공원에서 볼 수 있는 해안 지형 경관은 무엇인가요?',ARRAY['SO6-2-u1-X06','SO6-2-u1-X03']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C4","difficulty":1,"kind":"mc","stem":"교과서 23쪽 포트 캠벨 국립 공원에서 볼 수 있는 해안 지형 경관은 무엇인가요?","options":[{"t":"거대한 절벽과 돌기둥","correct":true},{"t":"넓은 갯벌","mis":"SO6-2-u1-X06"},{"t":"강물이 말발굽 모양으로 흐르는 계곡","mis":"SO6-2-u1-X03"},{"t":"산비탈의 계단식 논","mis":"SO6-2-u1-X03"}],"explanation":["사진 ③을 봐요.","오스트레일리아의 해안이에요.","거대한 절벽과 돌기둥이에요."],"asset":{"type":"passage","lines":["① 펀디만 갯벌(캐나다)","② 마케나 모래사장(미국)","③ 포트 캠벨 국립 공원(오스트레일리아) — 거대한 절벽과 돌기둥","세계의 유명한 갯벌 — 우리나라 서·남해안, 미국 동부 연안,","　캐나다 동부 연안, 브라질 아마존강 유역, 유럽 북해 연안"],"numbered":false,"title":"교과서 23쪽 해안 지형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L04_basic#5','soc',6,2,'u1','L04','tb_g6_2_soc_u1_L04_basic','lesson_basic','SO6-2-u1-C4',2,'match','auto','교과서 24쪽의 나라와 해안을 이용하는 모습을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u1-C4","difficulty":2,"kind":"match","stem":"교과서 24쪽의 나라와 해안을 이용하는 모습을 이으세요.","pairs":[{"l":"스리랑카","r":"배 없이 장대로 물고기 잡기"},{"l":"네덜란드","r":"세계 여러 나라의 배가 오가는 항구"},{"l":"프랑스 게랑드","r":"갯벌을 이용한 질 좋은 소금 만들기"},{"l":"멕시코","r":"아름다운 모래사장의 관광객"}],"mis":"SO6-2-u1-X06","explanation":["사진 설명을 하나씩 읽어요.","장대 낚시와 항구가 있어요.","갯벌은 소금, 모래사장은 관광이에요."],"asset":{"type":"passage","lines":["① 스리랑카 — 사람들이 배 없이 장대를 이용해 물고기를 잡음","② 네덜란드 — 해안에 발달한 항구에 세계 여러 나라의 배가 오감","③ 프랑스 게랑드 — 주민들이 갯벌을 이용해 질 좋은 소금을 만듦","④ 멕시코 — 해변의 아름다운 모래사장에 많은 관광객이 찾아옴"],"numbered":false,"title":"교과서 24쪽 해안을 이용하는 사람들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L04_basic#6','soc',6,2,'u1','L04','tb_g6_2_soc_u1_L04_basic','lesson_basic','SO6-2-u1-C4',2,'mc','auto','프랑스 게랑드 주민들이 갯벌에 염전을 만든 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X06','SO6-2-u1-X03']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C4","difficulty":2,"kind":"mc","stem":"프랑스 게랑드 주민들이 갯벌에 염전을 만든 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"드넓은 갯벌을 이용해 염전을 만들기 좋기 때문이에요","correct":true},{"t":"배가 드나들기에 가장 유리한 곳이기 때문이에요","mis":"SO6-2-u1-X06"},{"t":"높은 산이 많아 소금이 잘 마르기 때문이에요","mis":"SO6-2-u1-X03"},{"t":"강물이 빠르게 흘러 소금이 생기기 때문이에요","mis":"SO6-2-u1-X03"}],"explanation":["게랑드에는 갯벌이 넓어요.","갯벌이 넓게 펼쳐진 해안에 염전이 발달해요.","질 좋은 소금을 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L04_basic#7','soc',6,2,'u1','L04','tb_g6_2_soc_u1_L04_basic','lesson_basic','SO6-2-u1-C4',2,'mc','auto','네덜란드에 항구가 발달한 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X06']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C4","difficulty":2,"kind":"mc","stem":"네덜란드에 항구가 발달한 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"해안에 있어 배가 드나들기 좋기 때문이에요","correct":true},{"t":"갯벌이 넓어 소금을 만들기 좋기 때문이에요","mis":"SO6-2-u1-X06"},{"t":"모래사장이 아름다워 관광객이 많기 때문이에요","mis":"SO6-2-u1-X06"},{"t":"파도가 높고 거칠어 배를 쓸 수 없기 때문이에요","mis":"SO6-2-u1-X06"}],"explanation":["항구는 배가 드나드는 곳이에요.","네덜란드 해안은 배가 드나들기 좋아요.","세계 여러 나라의 배가 오가요."],"asset":{"type":"passage","lines":["① 스리랑카 — 사람들이 배 없이 장대를 이용해 물고기를 잡음","② 네덜란드 — 해안에 발달한 항구에 세계 여러 나라의 배가 오감","③ 프랑스 게랑드 — 주민들이 갯벌을 이용해 질 좋은 소금을 만듦","④ 멕시코 — 해변의 아름다운 모래사장에 많은 관광객이 찾아옴"],"numbered":false,"title":"교과서 24쪽 해안을 이용하는 사람들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L04_basic#8','soc',6,2,'u1','L04','tb_g6_2_soc_u1_L04_basic','lesson_basic','SO6-2-u1-C4',2,'ox','auto','스리랑카 사람들이 배 없이 장대를 이용해 물고기를 잡는 것은 파도가 높고 거칠기 때문이에요.',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C4","difficulty":2,"kind":"ox","stem":"스리랑카 사람들이 배 없이 장대를 이용해 물고기를 잡는 것은 파도가 높고 거칠기 때문이에요.","answer":"O","reason_options":[{"t":"파도가 높고 거친 바다에서 배 대신 장대 위에 앉아 물고기를 잡았기 때문에","correct":true},{"t":"스리랑카에는 바다가 없기 때문에","mis":"SO6-2-u1-X03"}],"mis":"SO6-2-u1-X03","explanation":["사진 ① 설명을 떠올려요.","파도가 높고 거칠어요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 스리랑카 — 사람들이 배 없이 장대를 이용해 물고기를 잡음","② 네덜란드 — 해안에 발달한 항구에 세계 여러 나라의 배가 오감","③ 프랑스 게랑드 — 주민들이 갯벌을 이용해 질 좋은 소금을 만듦","④ 멕시코 — 해변의 아름다운 모래사장에 많은 관광객이 찾아옴"],"numbered":false,"title":"교과서 24쪽 해안을 이용하는 사람들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L04_basic#9','soc',6,2,'u1','L04','tb_g6_2_soc_u1_L04_basic','lesson_basic','SO6-2-u1-C4',2,'mc','auto','교과서 23쪽에서 세계의 유명한 갯벌로 들지 않은 곳은 어디인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C4","difficulty":2,"kind":"mc","stem":"교과서 23쪽에서 세계의 유명한 갯벌로 들지 않은 곳은 어디인가요?","options":[{"t":"스위스 알프스산맥","correct":true},{"t":"우리나라 서·남해안","mis":"SO6-2-u1-X03"},{"t":"유럽 북해 연안","mis":"SO6-2-u1-X03"},{"t":"브라질 아마존강 유역","mis":"SO6-2-u1-X03"}],"explanation":["유명한 갯벌 목록을 읽어요.","갯벌은 바닷가에 있어요.","알프스산맥은 산지예요."],"asset":{"type":"passage","lines":["① 펀디만 갯벌(캐나다)","② 마케나 모래사장(미국)","③ 포트 캠벨 국립 공원(오스트레일리아) — 거대한 절벽과 돌기둥","세계의 유명한 갯벌 — 우리나라 서·남해안, 미국 동부 연안,","　캐나다 동부 연안, 브라질 아마존강 유역, 유럽 북해 연안"],"numbered":false,"title":"교과서 23쪽 해안 지형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L04_basic#10','soc',6,2,'u1','L04','tb_g6_2_soc_u1_L04_basic','lesson_basic','SO6-2-u1-C4',3,'error','auto','해안 지형의 생활 모습을 두고 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.',ARRAY['SO6-2-u1-X06']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C4","difficulty":3,"kind":"error","stem":"해안 지형의 생활 모습을 두고 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.","options":[{"t":"친구 나 — 「해안에서는 스키장을 만들어 관광객을 맞이해.」","correct":true,"mis_target":"SO6-2-u1-X06"},{"t":"친구 가 — 「해안 지역 주민들은 어업이나 양식업을 하며 살아가.」","mis":"SO6-2-u1-X06"},{"t":"친구 다 — 「경관이 아름다운 해안에는 관광지가 생겨.」","mis":"SO6-2-u1-X06"}],"explanation":["해안의 이용을 떠올려요.","스키장은 산지 지형에서 볼 수 있어요.","친구 나의 말이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L04_challenge#1','soc',6,2,'u1','L04','tb_g6_2_soc_u1_L04_challenge','lesson_challenge','SO6-2-u1-C4',2,'sa','auto','「기관이나 시설을 없애거나 기능을 정지하는 것」을 뜻하는 낱말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u1-C4","difficulty":2,"kind":"sa","stem":"「기관이나 시설을 없애거나 기능을 정지하는 것」을 뜻하는 낱말을 두 글자로 쓰세요.","answer":["폐쇄"],"explanation":["신문 기사의 낱말 풀이예요.","섬을 6개월 동안 닫았어요.","폐쇄예요."],"asset":{"type":"passage","lines":["필리핀의 보라카이섬은 해마다 관광객 2백만 명 이상이 찾고,","관광 수입은 한 해에 약 10억 달러에 이른다.","그러나 관광객이 버린 쓰레기로 섬이 뒤덮이고 오염된 물이 바다로 흘러들었다.","필리핀 정부는 환경을 보호하려고 섬을 6개월 동안 폐쇄하기로 했다.","하지만 주민 대부분이 관광 산업에서 일해 경제적 어려움이 걱정되었다.","정부는 자연환경을 지키면서 주민의 생계도 이어 갈 방법을 찾겠다고 했다."],"title":"교과서 25쪽 신문 기사"},"mis":"SO6-2-u1-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L04_challenge#2','soc',6,2,'u1','L04','tb_g6_2_soc_u1_L04_challenge','lesson_challenge','SO6-2-u1-C4',2,'mc','auto','신문 기사에서 필리핀 정부가 보라카이섬을 6개월 동안 폐쇄하기로 한 까닭은 무엇인가요?',ARRAY['SO6-2-u1-X07']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C4","difficulty":2,"kind":"mc","stem":"신문 기사에서 필리핀 정부가 보라카이섬을 6개월 동안 폐쇄하기로 한 까닭은 무엇인가요?","options":[{"t":"관광객이 버린 쓰레기와 오염된 물로 환경 오염이 심각해졌기 때문이에요","correct":true},{"t":"관광객이 한 명도 찾아오지 않았기 때문이에요","mis":"SO6-2-u1-X07"},{"t":"주민들이 모두 섬을 떠났기 때문이에요","mis":"SO6-2-u1-X07"},{"t":"관광 수입이 너무 적었기 때문이에요","mis":"SO6-2-u1-X07"}],"explanation":["기사 셋째 줄을 읽어요.","쓰레기로 섬이 뒤덮였어요.","환경을 보호하려고 폐쇄했어요."],"asset":{"type":"passage","lines":["필리핀의 보라카이섬은 해마다 관광객 2백만 명 이상이 찾고,","관광 수입은 한 해에 약 10억 달러에 이른다.","그러나 관광객이 버린 쓰레기로 섬이 뒤덮이고 오염된 물이 바다로 흘러들었다.","필리핀 정부는 환경을 보호하려고 섬을 6개월 동안 폐쇄하기로 했다.","하지만 주민 대부분이 관광 산업에서 일해 경제적 어려움이 걱정되었다.","정부는 자연환경을 지키면서 주민의 생계도 이어 갈 방법을 찾겠다고 했다."],"title":"교과서 25쪽 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L04_challenge#3','soc',6,2,'u1','L04','tb_g6_2_soc_u1_L04_challenge','lesson_challenge','SO6-2-u1-C4',3,'mc','auto','보라카이섬에서 관광 산업이 주민들에게 준 긍정적 영향과 부정적 영향을 바르게 짝지은 것은 무엇인가요?',ARRAY['SO6-2-u1-X07']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C4","difficulty":3,"kind":"mc","stem":"보라카이섬에서 관광 산업이 주민들에게 준 긍정적 영향과 부정적 영향을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"긍정적 — 일자리가 생기고 소득이 늘어남 · 부정적 — 쓰레기와 환경 오염","correct":true},{"t":"긍정적 — 쓰레기가 줄어듦 · 부정적 — 일자리가 생김","mis":"SO6-2-u1-X07"},{"t":"긍정적 — 환경 오염 · 부정적 — 소득이 늘어남","mis":"SO6-2-u1-X07"},{"t":"긍정적 — 바다가 깨끗해짐 · 부정적 — 관광객이 줄어듦","mis":"SO6-2-u1-X07"}],"explanation":["좋은 점과 걱정을 나눠요.","일자리와 소득은 좋은 점이에요.","쓰레기와 오염은 걱정이에요."],"asset":{"type":"passage","lines":["필리핀의 보라카이섬은 해마다 관광객 2백만 명 이상이 찾고,","관광 수입은 한 해에 약 10억 달러에 이른다.","그러나 관광객이 버린 쓰레기로 섬이 뒤덮이고 오염된 물이 바다로 흘러들었다.","필리핀 정부는 환경을 보호하려고 섬을 6개월 동안 폐쇄하기로 했다.","하지만 주민 대부분이 관광 산업에서 일해 경제적 어려움이 걱정되었다.","정부는 자연환경을 지키면서 주민의 생계도 이어 갈 방법을 찾겠다고 했다."],"title":"교과서 25쪽 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L04_challenge#4','soc',6,2,'u1','L04','tb_g6_2_soc_u1_L04_challenge','lesson_challenge','SO6-2-u1-C4',3,'mc','auto','보라카이섬을 폐쇄하면 걱정되는 일로 기사에 나온 것은 무엇인가요?',ARRAY['SO6-2-u1-X07']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C4","difficulty":3,"kind":"mc","stem":"보라카이섬을 폐쇄하면 걱정되는 일로 기사에 나온 것은 무엇인가요?","options":[{"t":"관광 산업에서 일하는 주민들이 경제적 어려움을 겪는 것","correct":true},{"t":"섬의 쓰레기가 더 늘어나는 것","mis":"SO6-2-u1-X07"},{"t":"바닷물이 더 깨끗해지는 것","mis":"SO6-2-u1-X07"},{"t":"관광객이 더 많이 찾아오는 것","mis":"SO6-2-u1-X07"}],"explanation":["기사 다섯째 줄을 읽어요.","주민 대부분이 관광 산업에서 일해요.","돈을 벌기 어려워질까 걱정했어요."],"asset":{"type":"passage","lines":["필리핀의 보라카이섬은 해마다 관광객 2백만 명 이상이 찾고,","관광 수입은 한 해에 약 10억 달러에 이른다.","그러나 관광객이 버린 쓰레기로 섬이 뒤덮이고 오염된 물이 바다로 흘러들었다.","필리핀 정부는 환경을 보호하려고 섬을 6개월 동안 폐쇄하기로 했다.","하지만 주민 대부분이 관광 산업에서 일해 경제적 어려움이 걱정되었다.","정부는 자연환경을 지키면서 주민의 생계도 이어 갈 방법을 찾겠다고 했다."],"title":"교과서 25쪽 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L04_challenge#5','soc',6,2,'u1','L04','tb_g6_2_soc_u1_L04_challenge','lesson_challenge','SO6-2-u1-C4',3,'ox','auto','보라카이섬 기사처럼 관광 산업에는 좋은 점과 걱정되는 점이 함께 있어 균형 있게 살펴봐야 해요.',ARRAY['SO6-2-u1-X07']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C4","difficulty":3,"kind":"ox","stem":"보라카이섬 기사처럼 관광 산업에는 좋은 점과 걱정되는 점이 함께 있어 균형 있게 살펴봐야 해요.","answer":"O","reason_options":[{"t":"관광으로 소득이 늘지만 환경이 오염되기도 하기 때문에","correct":true},{"t":"관광 산업에는 좋은 점만 있기 때문에","mis":"SO6-2-u1-X07"}],"mis":"SO6-2-u1-X07","explanation":["관광의 두 면을 떠올려요.","소득과 오염이 함께 생겨요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L04_challenge#6','soc',6,2,'u1','L04','tb_g6_2_soc_u1_L04_challenge','lesson_challenge','SO6-2-u1-C4',3,'mc','auto','해안의 갯벌을 염전 말고 어떻게 이용할 수 있을지 알맞게 짐작한 것은 무엇인가요?',ARRAY['SO6-2-u1-X06','SO6-2-u1-X20']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C4","difficulty":3,"kind":"mc","stem":"해안의 갯벌을 염전 말고 어떻게 이용할 수 있을지 알맞게 짐작한 것은 무엇인가요?","options":[{"t":"물고기나 조개를 기르는 양식업에 활용해요","correct":true},{"t":"갯벌 위에 큰 배가 드나드는 항구를 만들어요","mis":"SO6-2-u1-X06"},{"t":"갯벌에 스키장을 만들어요","mis":"SO6-2-u1-X06"},{"t":"갯벌을 메워 산비탈 계단식 논으로 바꿔요","mis":"SO6-2-u1-X20"}],"explanation":["갯벌은 바닷물이 드나들어요.","조개 같은 생물이 살기 좋아요.","양식업이나 관광지로 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L04_challenge#7','soc',6,2,'u1','L04','tb_g6_2_soc_u1_L04_challenge','lesson_challenge','SO6-2-u1-C4',3,'error','auto','보라카이섬 폐쇄를 두고 친구들이 의견을 말했어요. 의견과 까닭이 어울리지 않는 친구를 고르세요.',ARRAY['SO6-2-u1-X07']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C4","difficulty":3,"kind":"error","stem":"보라카이섬 폐쇄를 두고 친구들이 의견을 말했어요. 의견과 까닭이 어울리지 않는 친구를 고르세요.","options":[{"t":"친구 다 — 「폐쇄에 반대해. 섬의 자연환경이 더 오염되어도 되기 때문이야.」","correct":true,"mis_target":"SO6-2-u1-X07"},{"t":"친구 가 — 「폐쇄에 찬성해. 아름다운 자연환경을 보호하는 것이 중요하기 때문이야.」","mis":"SO6-2-u1-X07"},{"t":"친구 나 — 「폐쇄에 반대해. 관광 일을 하는 주민들의 생계가 어려워지기 때문이야.」","mis":"SO6-2-u1-X07"}],"explanation":["의견에는 알맞은 까닭이 있어야 해요.","오염되어도 된다는 것은 까닭이 될 수 없어요.","친구 다가 어울리지 않아요."],"asset":{"type":"passage","lines":["필리핀의 보라카이섬은 해마다 관광객 2백만 명 이상이 찾고,","관광 수입은 한 해에 약 10억 달러에 이른다.","그러나 관광객이 버린 쓰레기로 섬이 뒤덮이고 오염된 물이 바다로 흘러들었다.","필리핀 정부는 환경을 보호하려고 섬을 6개월 동안 폐쇄하기로 했다.","하지만 주민 대부분이 관광 산업에서 일해 경제적 어려움이 걱정되었다.","정부는 자연환경을 지키면서 주민의 생계도 이어 갈 방법을 찾겠다고 했다."],"title":"교과서 25쪽 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L04_challenge#8','soc',6,2,'u1','L04','tb_g6_2_soc_u1_L04_challenge','lesson_challenge','SO6-2-u1-C4',4,'mc','auto','관광지의 아름다운 자연환경을 지키면서 주민의 생계도 이어 가려는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X07']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C4","difficulty":4,"kind":"mc","stem":"관광지의 아름다운 자연환경을 지키면서 주민의 생계도 이어 가려는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"관광객 수를 제한하고 쓰레기를 버리지 않게 하면서 관광을 이어 가요","correct":true},{"t":"관광객을 마음껏 받고 쓰레기는 바다에 버려요","mis":"SO6-2-u1-X07"},{"t":"섬을 영원히 닫고 주민이 모두 떠나게 해요","mis":"SO6-2-u1-X07"},{"t":"해안을 모두 개발해 큰 건물만 세워요","mis":"SO6-2-u1-X07"}],"explanation":["환경과 생계를 함께 생각해요.","관광객 수를 줄이고 쓰레기를 막아요.","관광은 이어 가요."],"asset":{"type":"passage","lines":["필리핀의 보라카이섬은 해마다 관광객 2백만 명 이상이 찾고,","관광 수입은 한 해에 약 10억 달러에 이른다.","그러나 관광객이 버린 쓰레기로 섬이 뒤덮이고 오염된 물이 바다로 흘러들었다.","필리핀 정부는 환경을 보호하려고 섬을 6개월 동안 폐쇄하기로 했다.","하지만 주민 대부분이 관광 산업에서 일해 경제적 어려움이 걱정되었다.","정부는 자연환경을 지키면서 주민의 생계도 이어 갈 방법을 찾겠다고 했다."],"title":"교과서 25쪽 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L04_challenge#9','soc',6,2,'u1','L04','tb_g6_2_soc_u1_L04_challenge','lesson_challenge','SO6-2-u1-C4',4,'essay','teacher','보라카이섬 폐쇄에 대한 나의 의견(찬성 또는 반대)과 그렇게 생각한 까닭을 쓰고, 다른 의견을 가진 사람의 걱정도 함께 생각해 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u1-C4","difficulty":4,"kind":"essay","stem":"보라카이섬 폐쇄에 대한 나의 의견(찬성 또는 반대)과 그렇게 생각한 까닭을 쓰고, 다른 의견을 가진 사람의 걱정도 함께 생각해 쓰세요.","answer_guide":{"answer":"예: 나는 폐쇄에 찬성해요. 아름다운 자연환경을 보호해야 앞으로도 관광객이 찾아올 수 있기 때문이에요. 하지만 관광 일을 하는 주민들은 그동안 돈을 벌지 못해 어려움을 겪을 수 있으므로, 폐쇄 기간에 주민의 생계를 도울 방법도 함께 찾아야 해요.","scoring_points":["찬성이나 반대 의견을 밝혔는가","의견에 알맞은 까닭을 썼는가","다른 의견의 걱정도 생각했는가"]},"explanation":["의견을 정해요.","알맞은 까닭을 써요.","다른 쪽의 걱정도 살펴요."],"asset":{"type":"passage","lines":["필리핀의 보라카이섬은 해마다 관광객 2백만 명 이상이 찾고,","관광 수입은 한 해에 약 10억 달러에 이른다.","그러나 관광객이 버린 쓰레기로 섬이 뒤덮이고 오염된 물이 바다로 흘러들었다.","필리핀 정부는 환경을 보호하려고 섬을 6개월 동안 폐쇄하기로 했다.","하지만 주민 대부분이 관광 산업에서 일해 경제적 어려움이 걱정되었다.","정부는 자연환경을 지키면서 주민의 생계도 이어 갈 방법을 찾겠다고 했다."],"title":"교과서 25쪽 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L04_challenge#10','soc',6,2,'u1','L04','tb_g6_2_soc_u1_L04_challenge','lesson_challenge','SO6-2-u1-C4',4,'essay','teacher','활동지의 해안 지형 세 곳 가운데 가 보고 싶은 곳을 골라 까닭을 쓰고, 그곳에 사는 사람들의 생활 모습을 예상해 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u1-C4","difficulty":4,"kind":"essay","stem":"활동지의 해안 지형 세 곳 가운데 가 보고 싶은 곳을 골라 까닭을 쓰고, 그곳에 사는 사람들의 생활 모습을 예상해 쓰세요.","answer_guide":{"answer":"예: 인도네시아 코모도섬 모래사장에 가 보고 싶어요. 모래가 분홍색이라 직접 만져 보고 싶기 때문이에요. 분홍색 모래사장을 보러 오는 관광객에게 숙박이나 음식을 제공하는 관광 산업에서 일하는 사람이 많을 것 같아요.","scoring_points":["가 보고 싶은 곳과 까닭을 썼는가","해안 지형의 특징을 살렸는가","지형에 어울리는 생활 모습을 예상했는가"]},"explanation":["세 곳을 견줘요.","가 보고 싶은 까닭을 써요.","경관에 맞는 생활을 짐작해요."],"asset":{"type":"passage","lines":["① 포르투갈 마리냐 해변","② 인도네시아 코모도섬 모래사장 — 모래가 분홍색이에요","③ 미국 조지아주 동부 해안의 갯벌"],"numbered":false,"title":"활동지 — 가 보고 싶은 해안 지형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L06_basic#1','soc',6,2,'u1','L06','tb_g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',1,'mc','auto','교과서 30쪽 사진전에서 나라마다 전통 의상이 다른 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X08','SO6-2-u1-X02']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C5","difficulty":1,"kind":"mc","stem":"교과서 30쪽 사진전에서 나라마다 전통 의상이 다른 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"나라마다 기후가 다르기 때문이에요","correct":true},{"t":"사람들이 날마다 옷을 바꿔 입기 때문이에요","mis":"SO6-2-u1-X08"},{"t":"모든 나라의 날씨가 똑같기 때문이에요","mis":"SO6-2-u1-X02"},{"t":"전통 의상은 기후와 아무 관계가 없기 때문이에요","mis":"SO6-2-u1-X02"}],"explanation":["사진전 속 옷의 모양과 재료를 견줘요.","나라마다 덥고 추운 정도가 달라요.","기후가 옷차림에 영향을 줘요."],"asset":{"type":"passage","lines":["세계의 전통 의상 사진전 — 페루, 사우디아라비아, 캐나다 사람들의 전통 의상","옷의 모양과 재료가 나라마다 서로 달라요."],"title":"교과서 30쪽 생각을 열어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L06_basic#2','soc',6,2,'u1','L06','tb_g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',1,'ox','auto','세계의 기후는 주로 기온과 강수량을 기준으로 구분해요.',ARRAY['SO6-2-u1-X10']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C5","difficulty":1,"kind":"ox","stem":"세계의 기후는 주로 기온과 강수량을 기준으로 구분해요.","answer":"O","reason_options":[{"t":"교과서 33쪽에서 세계의 기후를 주로 기온과 강수량으로 구분한다고 했기 때문에","correct":true},{"t":"기후는 산의 높이 하나로만 구분하기 때문에","mis":"SO6-2-u1-X10"}],"mis":"SO6-2-u1-X10","explanation":["꼭 기억해요 첫 문장이에요.","기온과 강수량이 기준이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L06_basic#3','soc',6,2,'u1','L06','tb_g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',1,'sa','auto','「지구는 둥글기 때문에 (    )에 따라 햇볕을 받는 양이 다릅니다.」 빈칸에 알맞은 말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u1-C5","difficulty":1,"kind":"sa","stem":"「지구는 둥글기 때문에 (    )에 따라 햇볕을 받는 양이 다릅니다.」 빈칸에 알맞은 말을 두 글자로 쓰세요.","answer":["위도"],"explanation":["교과서 31쪽 첫 글이에요.","적도에서 얼마나 떨어졌는지 나타내요.","위도예요."],"mis":"SO6-2-u1-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L06_basic#4','soc',6,2,'u1','L06','tb_g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',1,'mc','auto','세계의 기후 분포도에서 적도 부근에 주로 분포하는 기후는 무엇인가요?',ARRAY['SO6-2-u1-X10','SO6-2-u1-X14']::text[],true,'{"seq":4,"concept":"SO6-2-u1-C5","difficulty":1,"kind":"mc","stem":"세계의 기후 분포도에서 적도 부근에 주로 분포하는 기후는 무엇인가요?","options":[{"t":"열대 기후","correct":true},{"t":"한대 기후","mis":"SO6-2-u1-X10"},{"t":"냉대 기후","mis":"SO6-2-u1-X10"},{"t":"고산 기후","mis":"SO6-2-u1-X14"}],"explanation":["적도 부근은 햇볕을 많이 받아요.","기온이 높은 기후가 나타나요.","열대 기후예요."],"variant_rule":{"alt":[{"stem":"세계의 기후 분포도에서 극지방에 주로 분포하는 기후는 무엇인가요?","options":[{"t":"한대 기후","correct":true},{"t":"열대 기후","mis":"SO6-2-u1-X10"},{"t":"건조 기후","mis":"SO6-2-u1-X10"},{"t":"온대 기후","mis":"SO6-2-u1-X10"}],"explanation":["극지방은 햇볕을 적게 받아요.","기온이 매우 낮아요.","한대 기후예요."]},{"stem":"세계의 기후 분포도에서 남반구보다 북반구에 주로 분포하는 기후는 무엇인가요?","options":[{"t":"냉대 기후","correct":true},{"t":"열대 기후","mis":"SO6-2-u1-X10"},{"t":"건조 기후","mis":"SO6-2-u1-X10"},{"t":"고산 기후","mis":"SO6-2-u1-X14"}],"explanation":["지도 속 말풍선을 떠올려요.","북반구에 주로 분포해요.","냉대 기후예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L06_basic#5','soc',6,2,'u1','L06','tb_g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',2,'mc','auto','세 도시의 연평균 기온을 보고 지도의 ㉢(적도와 30° 사이)에 있는 도시를 고르세요.',ARRAY['SO6-2-u1-X09','SO6-2-u1-X15']::text[],true,'{"seq":5,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"mc","stem":"세 도시의 연평균 기온을 보고 지도의 ㉢(적도와 30° 사이)에 있는 도시를 고르세요.","options":[{"t":"아부자","correct":true},{"t":"리옹","mis":"SO6-2-u1-X09"},{"t":"키루나","mis":"SO6-2-u1-X09"},{"t":"세 도시 모두","mis":"SO6-2-u1-X15"}],"explanation":["적도에 가까울수록 햇볕을 많이 받아요.","연평균 기온이 가장 높은 도시를 찾아요.","26.6℃인 아부자예요."],"asset":{"type":"passage","lines":["리옹 — 연평균 기온 11.9℃","키루나 — 연평균 기온 -0.5℃","아부자 — 연평균 기온 26.6℃","지도의 ㉠은 위도 60°선 위쪽, ㉡은 30°와 60° 사이, ㉢은 적도(0°)와 30° 사이에 있어요."],"title":"교과서 31쪽 세 도시의 위치 찾기"},"variant_rule":{"alt":[{"stem":"세 도시의 연평균 기온을 보고 지도의 ㉠(위도 60°선 위쪽)에 있는 도시를 고르세요.","options":[{"t":"키루나","correct":true},{"t":"아부자","mis":"SO6-2-u1-X09"},{"t":"리옹","mis":"SO6-2-u1-X09"},{"t":"세 도시 모두","mis":"SO6-2-u1-X15"}],"explanation":["극지방에 가까울수록 햇볕을 적게 받아요.","연평균 기온이 가장 낮은 도시를 찾아요.","-0.5℃인 키루나예요."],"asset":{"type":"passage","lines":["리옹 — 연평균 기온 11.9℃","키루나 — 연평균 기온 -0.5℃","아부자 — 연평균 기온 26.6℃","지도의 ㉠은 위도 60°선 위쪽, ㉡은 30°와 60° 사이, ㉢은 적도(0°)와 30° 사이에 있어요."],"title":"교과서 31쪽 세 도시의 위치 찾기"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L06_basic#6','soc',6,2,'u1','L06','tb_g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',2,'mc','auto','적도 지방에서 극지방으로 가면서 나타나는 기후를 차례대로 놓은 것은 무엇인가요?',ARRAY['SO6-2-u1-X10']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"mc","stem":"적도 지방에서 극지방으로 가면서 나타나는 기후를 차례대로 놓은 것은 무엇인가요?","options":[{"t":"열대 → 건조 → 온대 → 냉대 → 한대","correct":true},{"t":"열대 → 온대 → 건조 → 한대 → 냉대","mis":"SO6-2-u1-X10"},{"t":"한대 → 냉대 → 온대 → 건조 → 열대","mis":"SO6-2-u1-X10"},{"t":"건조 → 열대 → 냉대 → 온대 → 한대","mis":"SO6-2-u1-X10"}],"explanation":["적도에서 출발해요.","열대 다음은 건조, 그다음 온대예요.","냉대를 지나 한대에 닿아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L06_basic#7','soc',6,2,'u1','L06','tb_g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',2,'ox','auto','위도가 같은 지역은 언제나 똑같은 기후가 나타나요.',ARRAY['SO6-2-u1-X09']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"ox","stem":"위도가 같은 지역은 언제나 똑같은 기후가 나타나요.","answer":"X","reason_options":[{"t":"위도가 같아도 위치, 지형, 해발 고도에 따라 기후가 다르게 나타나기 때문에","correct":true},{"t":"기후는 위도 하나로만 정해지기 때문에","mis":"SO6-2-u1-X09"}],"mis":"SO6-2-u1-X09","explanation":["교과서 32쪽 글을 읽어요.","위치, 지형, 해발 고도도 기후를 바꿔요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L06_basic#8','soc',6,2,'u1','L06','tb_g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',2,'mc','auto','우리나라에 나타나는 기후를 바르게 고른 것은 무엇인가요?',ARRAY['SO6-2-u1-X10','SO6-2-u1-X14','SO6-2-u1-X09']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"mc","stem":"우리나라에 나타나는 기후를 바르게 고른 것은 무엇인가요?","options":[{"t":"온대 기후와 냉대 기후","correct":true},{"t":"열대 기후와 건조 기후","mis":"SO6-2-u1-X10"},{"t":"한대 기후와 고산 기후","mis":"SO6-2-u1-X14"},{"t":"고산 기후만","mis":"SO6-2-u1-X09"}],"explanation":["지도 속 말풍선을 떠올려요.","우리나라는 중위도에 있어요.","온대 기후와 냉대 기후가 나타나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L06_basic#9','soc',6,2,'u1','L06','tb_g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',2,'blank','auto','한 지역에서 여러 해에 걸쳐 반복적으로 나타나는 대기의 평균적인 상태를 (    )(이)라고 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-2-u1-X08','SO6-2-u1-X09','SO6-2-u1-X10']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"blank","stem":"한 지역에서 여러 해에 걸쳐 반복적으로 나타나는 대기의 평균적인 상태를 (    )(이)라고 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"기후","correct":true},{"t":"날씨","mis":"SO6-2-u1-X08"},{"t":"위도","mis":"SO6-2-u1-X09"},{"t":"강수량","mis":"SO6-2-u1-X10"}],"explanation":["하루의 모습은 날씨예요.","여러 해의 평균 상태를 봐요.","기후예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L06_basic#10','soc',6,2,'u1','L06','tb_g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',3,'error','auto','세계의 기후 분포도를 보고 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.',ARRAY['SO6-2-u1-X10','SO6-2-u1-X14']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C5","difficulty":3,"kind":"error","stem":"세계의 기후 분포도를 보고 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.","options":[{"t":"친구 다 — 「냉대 기후는 남반구에 주로 분포해.」","correct":true,"mis_target":"SO6-2-u1-X10"},{"t":"친구 가 — 「매우 높은 산지에서는 고산 기후가 나타나.」","mis":"SO6-2-u1-X14"},{"t":"친구 나 — 「한대 기후가 주로 분포하는 곳은 극지방이야.」","mis":"SO6-2-u1-X10"}],"explanation":["지도 속 말을 다시 읽어요.","냉대 기후는 북반구에 주로 분포해요.","친구 다의 말이 알맞지 않아요."],"asset":{"type":"passage","lines":["① 북반구에 주로 분포하는 기후는 냉대 기후예요.","② 우리나라에서는 온대 기후와 냉대 기후가 나타나요.","③ 한대 기후가 주로 분포하는 곳은 극지방이에요.","④ 적도 부근에 주로 분포하는 기후는 열대 기후예요."],"numbered":false,"title":"교과서 32~33쪽 세계의 기후 분포도 속 말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L06_challenge#1','soc',6,2,'u1','L06','tb_g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',2,'mc','auto','우리나라에서 해발 고도가 높은 곳의 기후를 바르게 말한 것은 무엇인가요?',ARRAY['SO6-2-u1-X09','SO6-2-u1-X14']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"mc","stem":"우리나라에서 해발 고도가 높은 곳의 기후를 바르게 말한 것은 무엇인가요?","options":[{"t":"고산 기후는 나타나지 않지만 평지와는 다른 서늘한 기후가 나타나요","correct":true},{"t":"우리나라 높은 산에서는 열대 기후가 나타나요","mis":"SO6-2-u1-X09"},{"t":"높은 곳도 평지와 기온이 똑같아요","mis":"SO6-2-u1-X09"},{"t":"우리나라 높은 산은 모두 고산 기후예요","mis":"SO6-2-u1-X14"}],"explanation":["교과서 33쪽 물음을 떠올려요.","우리나라에는 고산 기후가 없어요.","높은 곳은 평지보다 서늘해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L06_challenge#2','soc',6,2,'u1','L06','tb_g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',2,'mc','auto','저위도, 중위도, 고위도 가운데 연평균 기온이 가장 낮은 곳과 그 까닭을 바르게 말한 것은 무엇인가요?',ARRAY['SO6-2-u1-X09']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"mc","stem":"저위도, 중위도, 고위도 가운데 연평균 기온이 가장 낮은 곳과 그 까닭을 바르게 말한 것은 무엇인가요?","options":[{"t":"고위도 — 햇볕을 가장 적게 받기 때문이에요","correct":true},{"t":"저위도 — 햇볕을 가장 많이 받기 때문이에요","mis":"SO6-2-u1-X09"},{"t":"중위도 — 바다와 가장 멀기 때문이에요","mis":"SO6-2-u1-X09"},{"t":"고위도 — 햇볕을 가장 많이 받기 때문이에요","mis":"SO6-2-u1-X09"}],"explanation":["위도에 따라 햇볕의 양이 달라요.","고위도는 햇볕을 가장 적게 받아요.","그래서 기온이 가장 낮아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L06_challenge#3','soc',6,2,'u1','L06','tb_g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',3,'mc','auto','리옹, 키루나, 아부자의 기후를 짐작한 것으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X09','SO6-2-u1-X15']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C5","difficulty":3,"kind":"mc","stem":"리옹, 키루나, 아부자의 기후를 짐작한 것으로 알맞은 것은 무엇인가요?","options":[{"t":"키루나는 겨울이 길고 추울 것 같아요","correct":true},{"t":"아부자는 겨울이 길고 몹시 추울 것 같아요","mis":"SO6-2-u1-X09"},{"t":"리옹은 일 년 내내 매우 더울 것 같아요","mis":"SO6-2-u1-X09"},{"t":"세 도시는 기후가 모두 같을 것 같아요","mis":"SO6-2-u1-X15"}],"explanation":["연평균 기온을 견줘요.","키루나는 -0.5℃로 가장 낮아요.","겨울이 길고 추울 것 같아요."],"asset":{"type":"passage","lines":["리옹 — 연평균 기온 11.9℃","키루나 — 연평균 기온 -0.5℃","아부자 — 연평균 기온 26.6℃","지도의 ㉠은 위도 60°선 위쪽, ㉡은 30°와 60° 사이, ㉢은 적도(0°)와 30° 사이에 있어요."],"title":"교과서 31쪽 세 도시의 위치 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L06_challenge#4','soc',6,2,'u1','L06','tb_g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',3,'ox','auto','세계의 기후 분포는 적도를 기준으로 남쪽과 북쪽이 비슷한 모습으로 나타나요.',ARRAY['SO6-2-u1-X10']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C5","difficulty":3,"kind":"ox","stem":"세계의 기후 분포는 적도를 기준으로 남쪽과 북쪽이 비슷한 모습으로 나타나요.","answer":"O","reason_options":[{"t":"적도 부근에 열대 기후가 있고 양쪽 극지방으로 갈수록 한대 기후 쪽으로 차례로 바뀌기 때문에","correct":true},{"t":"남반구에는 기후가 하나만 나타나기 때문에","mis":"SO6-2-u1-X10"}],"mis":"SO6-2-u1-X10","explanation":["적도를 가운데에 두고 지도를 봐요.","위아래로 기후가 차례로 바뀌어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L06_challenge#5','soc',6,2,'u1','L06','tb_g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',3,'mc','auto','세계의 기후 분포도에서 찾은 나라를 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X19','SO6-2-u1-X15']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C5","difficulty":3,"kind":"mc","stem":"세계의 기후 분포도에서 찾은 나라를 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"러시아처럼 한 나라에 여러 기후가 나타나는 곳도 있어요","correct":true},{"t":"한 나라에는 언제나 한 가지 기후만 나타나요","mis":"SO6-2-u1-X19"},{"t":"미국에는 온대 기후만 나타나요","mis":"SO6-2-u1-X19"},{"t":"칠레에는 고산 기후가 나타나지 않아요","mis":"SO6-2-u1-X15"}],"explanation":["나라 이름이 두 번 나오는 것을 찾아요.","러시아는 냉대와 한대에 모두 있어요.","한 나라에도 여러 기후가 나타나요."],"asset":{"type":"passage","lines":["열대 — 탄자니아, 말레이시아, 타이, 브라질","건조 — 사우디아라비아, 몽골, 오스트레일리아, 이집트","온대 — 영국, 프랑스, 중국, 인도, 미국","냉대 — 핀란드, 러시아, 미국, 캐나다","한대 — 러시아, 노르웨이, 아이슬란드, 캐나다, 칠레","고산 — 칠레, 콜롬비아, 에콰도르, 에티오피아"],"title":"세계의 기후 분포도에서 찾은 나라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L06_challenge#6','soc',6,2,'u1','L06','tb_g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',3,'error','auto','기후에 대해 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.',ARRAY['SO6-2-u1-X08']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C5","difficulty":3,"kind":"error","stem":"기후에 대해 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.","options":[{"t":"친구 가 — 「오늘 비가 많이 왔으니 우리 지역의 기후는 비가 많은 기후야.」","correct":true,"mis_target":"SO6-2-u1-X08"},{"t":"친구 나 — 「기후는 여러 해에 걸쳐 반복되는 대기의 평균 상태야.」","mis":"SO6-2-u1-X08"},{"t":"친구 다 — 「기후는 지역마다 다양하게 나타나.」","mis":"SO6-2-u1-X08"}],"explanation":["하루의 비는 날씨예요.","기후는 여러 해의 평균이에요.","친구 가가 날씨와 기후를 섞었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L06_challenge#7','soc',6,2,'u1','L06','tb_g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',3,'mc','auto','활동지 지도의 ㉥처럼 매우 높은 산지에 나타나는 기후는 무엇인가요?',ARRAY['SO6-2-u1-X14','SO6-2-u1-X09','SO6-2-u1-X10']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C5","difficulty":3,"kind":"mc","stem":"활동지 지도의 ㉥처럼 매우 높은 산지에 나타나는 기후는 무엇인가요?","options":[{"t":"고산 기후","correct":true},{"t":"한대 기후","mis":"SO6-2-u1-X14"},{"t":"열대 기후","mis":"SO6-2-u1-X09"},{"t":"건조 기후","mis":"SO6-2-u1-X10"}],"explanation":["높은 산지를 떠올려요.","해발 고도가 매우 높아요.","고산 기후예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L06_challenge#8','soc',6,2,'u1','L06','tb_g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',4,'mc','auto','콜롬비아의 높은 산지에서 사람들이 모두 긴 옷을 입고 생활하는 모습을 텔레비전에서 본 친구가 있어요. 이 모습으로 짐작할 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X09','SO6-2-u1-X02','SO6-2-u1-X10']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C5","difficulty":4,"kind":"mc","stem":"콜롬비아의 높은 산지에서 사람들이 모두 긴 옷을 입고 생활하는 모습을 텔레비전에서 본 친구가 있어요. 이 모습으로 짐작할 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"적도 가까이에 있어도 해발 고도가 높으면 서늘한 기후가 나타나요","correct":true},{"t":"적도 가까이에 있는 곳은 어디나 무척 더워요","mis":"SO6-2-u1-X09"},{"t":"긴 옷은 기후와 아무 관계가 없어요","mis":"SO6-2-u1-X02"},{"t":"콜롬비아는 극지방에 있어요","mis":"SO6-2-u1-X10"}],"explanation":["콜롬비아는 적도 가까이에 있어요.","그런데도 높은 산지에서 긴 옷을 입어요.","해발 고도가 높아 서늘하기 때문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L06_challenge#9','soc',6,2,'u1','L06','tb_g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',4,'essay','teacher','지역에 따라 기후가 다르게 나타나는 까닭을 위도와 함께 다른 요인도 들어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u1-C5","difficulty":4,"kind":"essay","stem":"지역에 따라 기후가 다르게 나타나는 까닭을 위도와 함께 다른 요인도 들어 쓰세요.","answer_guide":{"answer":"예: 지구는 둥글기 때문에 위도에 따라 햇볕을 받는 양이 달라 적도 지방에서 극지방으로 갈수록 기온이 낮아져요. 또 같은 위도라도 위치, 지형, 해발 고도에 따라 기온과 강수량이 달라 기후가 다르게 나타나요.","scoring_points":["위도와 햇볕의 양을 이어 썼는가","위치·지형·해발 고도 가운데 하나 이상을 들었는가","기온이나 강수량이 달라진다는 점을 썼는가"]},"explanation":["위도부터 떠올려요.","다른 요인을 더 찾아요.","기온과 강수량이 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L06_challenge#10','soc',6,2,'u1','L06','tb_g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',4,'essay','teacher','세계의 기후 분포를 살펴보고 기후 분포의 특징을 세 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u1-C5","difficulty":4,"kind":"essay","stem":"세계의 기후 분포를 살펴보고 기후 분포의 특징을 세 가지 쓰세요.","answer_guide":{"answer":"예: ① 적도 지방에서 극지방으로 가면서 열대, 건조, 온대, 냉대, 한대 기후가 차례대로 나타나요. ② 냉대 기후는 남반구보다 북반구에서 주로 나타나요. ③ 매우 높은 산지에서는 고산 기후가 나타나요.","scoring_points":["기후의 차례를 바르게 썼는가","분포의 특징을 세 가지 썼는가","특징이 지도와 맞는가"]},"explanation":["지도를 적도부터 훑어요.","차례와 치우침을 찾아요.","높은 산지도 살펴요."],"asset":{"type":"passage","lines":["① 북반구에 주로 분포하는 기후는 냉대 기후예요.","② 우리나라에서는 온대 기후와 냉대 기후가 나타나요.","③ 한대 기후가 주로 분포하는 곳은 극지방이에요.","④ 적도 부근에 주로 분포하는 기후는 열대 기후예요."],"numbered":false,"title":"교과서 32~33쪽 세계의 기후 분포도 속 말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L07_basic#1','soc',6,2,'u1','L07','tb_g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C6',1,'mc','auto','열대 기후가 주로 나타나는 곳은 어디인가요?',ARRAY['SO6-2-u1-X10','SO6-2-u1-X14']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C6","difficulty":1,"kind":"mc","stem":"열대 기후가 주로 나타나는 곳은 어디인가요?","options":[{"t":"적도 주변의 저위도 지역","correct":true},{"t":"남극과 북극 주변의 고위도 지역","mis":"SO6-2-u1-X10"},{"t":"북반구의 중위도와 고위도 지역","mis":"SO6-2-u1-X10"},{"t":"해발 고도가 매우 높은 산지","mis":"SO6-2-u1-X14"}],"explanation":["교과서 34쪽 첫 글을 읽어요.","적도 주변이에요.","저위도 지역이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L07_basic#2','soc',6,2,'u1','L07','tb_g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C6',1,'sa','auto','「열대 기후 지역은 일 년 내내 비가 많이 내려 (    )을/를 이루는 곳도 있습니다.」 빈칸에 알맞은 말을 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u1-C6","difficulty":1,"kind":"sa","stem":"「열대 기후 지역은 일 년 내내 비가 많이 내려 (    )을/를 이루는 곳도 있습니다.」 빈칸에 알맞은 말을 네 글자로 쓰세요.","answer":["열대 우림","열대우림"],"explanation":["꼭 기억해요 첫 문장이에요.","비가 많아 숲이 빽빽해요.","열대 우림이에요."],"mis":"SO6-2-u1-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L07_basic#3','soc',6,2,'u1','L07','tb_g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C7',1,'ox','auto','「건조 기후는 저위도와 중위도 지역의 강수량이 많은 곳에 나타납니다.」는 바른 문장이에요.',ARRAY['SO6-2-u1-X11']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C7","difficulty":1,"kind":"ox","stem":"「건조 기후는 저위도와 중위도 지역의 강수량이 많은 곳에 나타납니다.」는 바른 문장이에요.","answer":"X","reason_options":[{"t":"건조 기후는 연중 강수량이 적은 곳에 주로 나타나기 때문에","correct":true},{"t":"건조한 곳일수록 비가 많이 오기 때문에","mis":"SO6-2-u1-X11"}],"mis":"SO6-2-u1-X11","explanation":["꼭 기억해요 둘째 문장이에요.","건조 기후는 비가 적어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L07_basic#4','soc',6,2,'u1','L07','tb_g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C7',1,'blank','auto','물과 풀이 있는 곳을 찾아 이동하며 가축을 기르는 일을 (    )(이)라고 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-2-u1-X12']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C7","difficulty":1,"kind":"blank","stem":"물과 풀이 있는 곳을 찾아 이동하며 가축을 기르는 일을 (    )(이)라고 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"유목","correct":true},{"t":"화전 농업","mis":"SO6-2-u1-X12"},{"t":"양식업","mis":"SO6-2-u1-X12"},{"t":"광업","mis":"SO6-2-u1-X12"}],"explanation":["교과서 36쪽 낱말 풀이예요.","가축과 함께 옮겨 다녀요.","유목이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L07_basic#5','soc',6,2,'u1','L07','tb_g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C6',2,'mc','auto','열대 기후 지역의 집 모습과 그렇게 짓는 까닭을 바르게 짝지은 것은 무엇인가요?',ARRAY['SO6-2-u1-X12']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C6","difficulty":2,"kind":"mc","stem":"열대 기후 지역의 집 모습과 그렇게 짓는 까닭을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"기둥을 세워 바닥을 땅에서 띄우고 창을 크게 — 바람이 잘 통하게 하려고","correct":true},{"t":"벽을 두껍게 하고 창문을 작게 — 바람이 잘 통하게 하려고","mis":"SO6-2-u1-X12"},{"t":"가축 가죽으로 옮길 수 있게 — 한곳에 오래 살려고","mis":"SO6-2-u1-X12"},{"t":"흙벽돌로 창문을 작게 — 비를 많이 받으려고","mis":"SO6-2-u1-X12"}],"explanation":["열대 기후는 덥고 비가 많아요.","바람이 잘 통해야 해요.","바닥을 띄우고 창을 크게 만들어요."],"asset":{"type":"passage","lines":["전통 농업 — 화전 농업으로 카사바, 얌, 옥수수 등을 재배","오늘날 — 천연고무, 카카오, 바나나, 커피 등을 대규모로 재배","관광 — 사파리 관광, 전통 부족 생활 체험 등 생태 관광 산업","집 — 바람이 잘 통하도록 창을 크게, 기둥을 세워 바닥을 땅에서 띄움","옷 — 얇고 바람이 잘 통하는 옷"],"title":"교과서 35쪽 열대 기후 지역의 생활"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L07_basic#6','soc',6,2,'u1','L07','tb_g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C6',2,'mc','auto','쿠알라룸푸르와 므완자의 기후 그래프에서 찾을 수 있는 공통점은 무엇인가요?',ARRAY['SO6-2-u1-X15','SO6-2-u1-X11','SO6-2-u1-X21']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C6","difficulty":2,"kind":"mc","stem":"쿠알라룸푸르와 므완자의 기후 그래프에서 찾을 수 있는 공통점은 무엇인가요?","options":[{"t":"두 도시 모두 일 년 내내 기온이 높고 기온의 변화가 거의 없어요","correct":true},{"t":"두 도시 모두 일 년 내내 비가 많이 내려요","mis":"SO6-2-u1-X15"},{"t":"두 도시 모두 겨울이 길고 몹시 추워요","mis":"SO6-2-u1-X11"},{"t":"두 도시 모두 막대가 기온을 나타내요","mis":"SO6-2-u1-X21"}],"explanation":["선(기온)을 먼저 봐요.","두 도시 모두 선이 높고 평평해요.","기온이 높고 변화가 거의 없어요."],"asset":{"type":"passage","lines":["쿠알라룸푸르(말레이시아) — 선(기온)이 일 년 내내 높고 거의 평평함,","　막대(강수량)가 열두 달 모두 높음 — 주변에 열대 우림","므완자(탄자니아) — 선(기온)이 일 년 내내 높고 거의 평평함,","　막대(강수량)가 높은 달과 낮은 달이 번갈아 나타남 — 주변에 초원","기후 그래프에서 막대는 강수량을, 선은 기온을 나타내요."],"numbered":false,"title":"교과서 34쪽 열대 기후 두 도시의 기후 그래프"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L07_basic#7','soc',6,2,'u1','L07','tb_g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C7',2,'mc','auto','사막 지역 사람들이 온몸을 감싸는 옷을 입는 까닭은 무엇인가요?',ARRAY['SO6-2-u1-X12']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C7","difficulty":2,"kind":"mc","stem":"사막 지역 사람들이 온몸을 감싸는 옷을 입는 까닭은 무엇인가요?","options":[{"t":"강한 햇볕과 모래바람을 막으려고","correct":true},{"t":"바람이 잘 통하게 하려고","mis":"SO6-2-u1-X12"},{"t":"추운 겨울을 이겨 내려고","mis":"SO6-2-u1-X12"},{"t":"물속에서 일하기 편하려고","mis":"SO6-2-u1-X12"}],"explanation":["사막의 햇볕은 강해요.","모래바람도 불어요.","온몸을 감싸 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L07_basic#8','soc',6,2,'u1','L07','tb_g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C7',2,'ox','auto','건조 기후 지역에서는 어디에서도 농사를 지을 수 없어요.',ARRAY['SO6-2-u1-X18']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C7","difficulty":2,"kind":"ox","stem":"건조 기후 지역에서는 어디에서도 농사를 지을 수 없어요.","answer":"X","reason_options":[{"t":"오아시스나 강 주변에서는 밀이나 대추야자를 재배하기 때문에","correct":true},{"t":"비가 적은 곳에서는 식물이 하나도 자라지 않기 때문에","mis":"SO6-2-u1-X18"}],"mis":"SO6-2-u1-X18","explanation":["교과서 36쪽 사진을 떠올려요.","오아시스나 강 주변에서 농사를 지어요.","그래서 X예요."],"asset":{"type":"passage","lines":["분포 — 저위도와 중위도에서 연중 강수량이 적은 곳","특징 — 낮과 밤의 기온 차이가 큼, 사막 또는 초원이 넓게 나타남","사막 — 온몸을 감싸는 옷, 벽이 두껍고 창문이 작은 흙벽돌 집","초원 — 유목 생활, 가축의 털이나 가죽으로 만든 이동식 가옥,","　가축의 젖으로 만든 유제품이나 고기를 먹음","오아시스나 강 주변 — 밀이나 대추야자를 재배"],"numbered":false,"title":"교과서 36쪽 건조 기후"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L07_basic#9','soc',6,2,'u1','L07','tb_g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C6',2,'mc','auto','열대 기후 지역에서 전통적으로 해 온 농사 방법으로, 나무와 풀을 태우고 남은 재를 거름 삼아 농사짓는 방식은 무엇인가요?',ARRAY['SO6-2-u1-X12','SO6-2-u1-X15']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C6","difficulty":2,"kind":"mc","stem":"열대 기후 지역에서 전통적으로 해 온 농사 방법으로, 나무와 풀을 태우고 남은 재를 거름 삼아 농사짓는 방식은 무엇인가요?","options":[{"t":"화전 농업","correct":true},{"t":"계단식 농사","mis":"SO6-2-u1-X12"},{"t":"유목","mis":"SO6-2-u1-X12"},{"t":"대규모 커피 재배","mis":"SO6-2-u1-X15"}],"explanation":["교과서 35쪽 낱말 풀이예요.","태우고 남은 재를 거름으로 써요.","화전 농업이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L07_basic#10','soc',6,2,'u1','L07','tb_g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C7',3,'error','auto','열대 기후와 건조 기후를 두고 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.',ARRAY['SO6-2-u1-X11','SO6-2-u1-X15']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C7","difficulty":3,"kind":"error","stem":"열대 기후와 건조 기후를 두고 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.","options":[{"t":"친구 나 — 「건조 기후 지역은 낮과 밤의 기온 차이가 거의 없어.」","correct":true,"mis_target":"SO6-2-u1-X11"},{"t":"친구 가 — 「건조 기후 지역은 강수량이 매우 적어 사막이 넓게 나타나는 곳도 있어.」","mis":"SO6-2-u1-X11"},{"t":"친구 다 — 「열대 기후 지역에는 건기와 우기가 번갈아 나타나는 곳도 있어.」","mis":"SO6-2-u1-X15"}],"explanation":["건조 기후의 특징을 떠올려요.","낮과 밤의 기온 차이가 커요.","친구 나의 말이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L07_challenge#1','soc',6,2,'u1','L07','tb_g6_2_soc_u1_L07_challenge','lesson_challenge','SO6-2-u1-C6',2,'mc','auto','신문 기사에서 타이 음식에 다양한 향신료를 사용하는 까닭은 무엇인가요?',ARRAY['SO6-2-u1-X12','SO6-2-u1-X11']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C6","difficulty":2,"kind":"mc","stem":"신문 기사에서 타이 음식에 다양한 향신료를 사용하는 까닭은 무엇인가요?","options":[{"t":"음식이 쉽게 상하지 않도록 하려고","correct":true},{"t":"음식을 얼려 오래 보관하려고","mis":"SO6-2-u1-X12"},{"t":"비가 적게 오는 날씨에 물을 아끼려고","mis":"SO6-2-u1-X11"},{"t":"추운 날씨에 몸을 따뜻하게 하려고","mis":"SO6-2-u1-X12"}],"explanation":["기사 첫 문장을 읽어요.","음식이 쉽게 상하지 않도록 해요.","그래서 향신료를 많이 써요."],"asset":{"type":"passage","lines":["열대 기후가 나타나는 타이에서는 음식이 쉽게 상하지 않도록","다양한 향신료를 써서 맵고 새콤한 맛이 나는 음식이 발달했다.","대표 전통 음식 똠얌꿍에는 레몬그라스, 라임잎, 고추, 고수, 생강이 들어간다.","레몬그라스와 라임잎의 상큼한 맛은 더운 날씨에 입맛을 돋우고,","고추의 매운맛은 땀을 흘리게 해 체온을 낮춰 준다."],"title":"교과서 35쪽 신문 기사 — 매콤새콤한 타이 음식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L07_challenge#2','soc',6,2,'u1','L07','tb_g6_2_soc_u1_L07_challenge','lesson_challenge','SO6-2-u1-C6',2,'sa','auto','일 년 중 비가 적게 내리는 시기를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"SO6-2-u1-C6","difficulty":2,"kind":"sa","stem":"일 년 중 비가 적게 내리는 시기를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["건기"],"explanation":["교과서 34쪽 낱말 풀이예요.","비가 적은 시기예요.","건기예요."],"mis":"SO6-2-u1-X11","variant_rule":{"alt":[{"stem":"일 년 중 비가 많이 내리는 시기를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["우기"],"explanation":["교과서 34쪽 낱말 풀이예요.","비가 많은 시기예요.","우기예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L07_challenge#3','soc',6,2,'u1','L07','tb_g6_2_soc_u1_L07_challenge','lesson_challenge','SO6-2-u1-C6',3,'mc','auto','열대 기후 지역에서 음식이 쉽게 상하는 까닭을 기후 특성과 이어 말한 것은 무엇인가요?',ARRAY['SO6-2-u1-X11']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C6","difficulty":3,"kind":"mc","stem":"열대 기후 지역에서 음식이 쉽게 상하는 까닭을 기후 특성과 이어 말한 것은 무엇인가요?","options":[{"t":"덥고 습하기 때문이에요","correct":true},{"t":"춥고 건조하기 때문이에요","mis":"SO6-2-u1-X11"},{"t":"낮과 밤의 기온 차이가 크기 때문이에요","mis":"SO6-2-u1-X11"},{"t":"일 년 내내 눈이 오기 때문이에요","mis":"SO6-2-u1-X11"}],"explanation":["열대 기후를 떠올려요.","일 년 내내 덥고 비가 많아요.","덥고 습하면 음식이 쉽게 상해요."],"asset":{"type":"passage","lines":["열대 기후가 나타나는 타이에서는 음식이 쉽게 상하지 않도록","다양한 향신료를 써서 맵고 새콤한 맛이 나는 음식이 발달했다.","대표 전통 음식 똠얌꿍에는 레몬그라스, 라임잎, 고추, 고수, 생강이 들어간다.","레몬그라스와 라임잎의 상큼한 맛은 더운 날씨에 입맛을 돋우고,","고추의 매운맛은 땀을 흘리게 해 체온을 낮춰 준다."],"title":"교과서 35쪽 신문 기사 — 매콤새콤한 타이 음식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L07_challenge#4','soc',6,2,'u1','L07','tb_g6_2_soc_u1_L07_challenge','lesson_challenge','SO6-2-u1-C6',3,'mc','auto','므완자 주변에 초원이 넓게 펼쳐진 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X15','SO6-2-u1-X11','SO6-2-u1-X21']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C6","difficulty":3,"kind":"mc","stem":"므완자 주변에 초원이 넓게 펼쳐진 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"건기와 우기가 번갈아 나타나기 때문이에요","correct":true},{"t":"일 년 내내 비가 많이 내리기 때문이에요","mis":"SO6-2-u1-X15"},{"t":"일 년 내내 기온이 매우 낮기 때문이에요","mis":"SO6-2-u1-X11"},{"t":"강수량을 나타내는 선이 일 년 내내 평평하기 때문이에요","mis":"SO6-2-u1-X21"}],"explanation":["므완자의 막대를 봐요.","비가 많은 달과 적은 달이 번갈아 나타나요.","그래서 초원이 펼쳐져요."],"asset":{"type":"passage","lines":["쿠알라룸푸르(말레이시아) — 선(기온)이 일 년 내내 높고 거의 평평함,","　막대(강수량)가 열두 달 모두 높음 — 주변에 열대 우림","므완자(탄자니아) — 선(기온)이 일 년 내내 높고 거의 평평함,","　막대(강수량)가 높은 달과 낮은 달이 번갈아 나타남 — 주변에 초원","기후 그래프에서 막대는 강수량을, 선은 기온을 나타내요."],"numbered":false,"title":"교과서 34쪽 열대 기후 두 도시의 기후 그래프"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L07_challenge#5','soc',6,2,'u1','L07','tb_g6_2_soc_u1_L07_challenge','lesson_challenge','SO6-2-u1-C6',3,'ox','auto','기후 그래프에서 막대는 기온을, 선은 강수량을 나타내요.',ARRAY['SO6-2-u1-X21']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C6","difficulty":3,"kind":"ox","stem":"기후 그래프에서 막대는 기온을, 선은 강수량을 나타내요.","answer":"X","reason_options":[{"t":"교과서 34쪽처럼 막대는 강수량을, 선은 기온을 나타내기 때문에","correct":true},{"t":"막대가 높을수록 더운 날씨이기 때문에","mis":"SO6-2-u1-X21"}],"mis":"SO6-2-u1-X21","explanation":["그래프 옆 말풍선을 떠올려요.","막대는 강수량, 선은 기온이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L07_challenge#6','soc',6,2,'u1','L07','tb_g6_2_soc_u1_L07_challenge','lesson_challenge','SO6-2-u1-C7',3,'mc','auto','초원 지역의 유목민이 가축의 털이나 가죽으로 만든 이동식 가옥에서 생활하는 까닭은 무엇인가요?',ARRAY['SO6-2-u1-X12']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C7","difficulty":3,"kind":"mc","stem":"초원 지역의 유목민이 가축의 털이나 가죽으로 만든 이동식 가옥에서 생활하는 까닭은 무엇인가요?","options":[{"t":"물과 풀이 있는 곳을 찾아 자주 옮겨 다니기 때문이에요","correct":true},{"t":"한곳에 오래 머물러 농사를 짓기 때문이에요","mis":"SO6-2-u1-X12"},{"t":"바람이 잘 통하게 하려고 바닥을 띄우기 때문이에요","mis":"SO6-2-u1-X12"},{"t":"흙이 많아 흙벽돌을 만들기 쉽기 때문이에요","mis":"SO6-2-u1-X12"}],"explanation":["유목의 뜻을 떠올려요.","가축과 함께 옮겨 다녀요.","옮기기 쉬운 집이 필요해요."],"asset":{"type":"passage","lines":["분포 — 저위도와 중위도에서 연중 강수량이 적은 곳","특징 — 낮과 밤의 기온 차이가 큼, 사막 또는 초원이 넓게 나타남","사막 — 온몸을 감싸는 옷, 벽이 두껍고 창문이 작은 흙벽돌 집","초원 — 유목 생활, 가축의 털이나 가죽으로 만든 이동식 가옥,","　가축의 젖으로 만든 유제품이나 고기를 먹음","오아시스나 강 주변 — 밀이나 대추야자를 재배"],"numbered":false,"title":"교과서 36쪽 건조 기후"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L07_challenge#7','soc',6,2,'u1','L07','tb_g6_2_soc_u1_L07_challenge','lesson_challenge','SO6-2-u1-C7',3,'error','auto','건조 기후 지역 사람들의 생활을 두고 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.',ARRAY['SO6-2-u1-X12','SO6-2-u1-X18']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C7","difficulty":3,"kind":"error","stem":"건조 기후 지역 사람들의 생활을 두고 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.","options":[{"t":"친구 다 — 「사막 지역의 집은 바람이 잘 통하도록 창을 크게 만들어.」","correct":true,"mis_target":"SO6-2-u1-X12"},{"t":"친구 가 — 「오아시스나 강 주변에서는 대추야자를 길러.」","mis":"SO6-2-u1-X18"},{"t":"친구 나 — 「유목민은 가축의 젖으로 만든 유제품이나 고기를 먹어.」","mis":"SO6-2-u1-X12"}],"explanation":["사막의 집을 떠올려요.","벽이 두껍고 창문이 작은 흙벽돌 집이에요.","친구 다는 열대 기후의 집과 헷갈렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L07_challenge#8','soc',6,2,'u1','L07','tb_g6_2_soc_u1_L07_challenge','lesson_challenge','SO6-2-u1-C7',4,'mc','auto','활동지 예시에서 모로코의 가옥을 흙으로 짓고, 벽을 두껍게 하고 창문을 아주 작게 만든 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X12','SO6-2-u1-X11','SO6-2-u1-X13']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C7","difficulty":4,"kind":"mc","stem":"활동지 예시에서 모로코의 가옥을 흙으로 짓고, 벽을 두껍게 하고 창문을 아주 작게 만든 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"주변에서 흙을 구하기 쉽고, 사막의 모래바람과 열기를 막으려고","correct":true},{"t":"주변에 나무가 많고, 바람이 잘 통하게 하려고","mis":"SO6-2-u1-X12"},{"t":"비가 많이 와서 물이 집 안으로 들어오게 하려고","mis":"SO6-2-u1-X11"},{"t":"추운 겨울에 눈이 많이 쌓이지 않게 하려고","mis":"SO6-2-u1-X13"}],"explanation":["모로코는 건조 기후예요.","흙은 주변에서 구하기 쉬워요.","두꺼운 벽과 작은 창으로 열기를 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L07_challenge#9','soc',6,2,'u1','L07','tb_g6_2_soc_u1_L07_challenge','lesson_challenge','SO6-2-u1-C6',4,'essay','teacher','열대 기후 지역 사람들의 생활 모습 두 가지를 쓰고, 각각 열대 기후의 어떤 특징과 관계있는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u1-C6","difficulty":4,"kind":"essay","stem":"열대 기후 지역 사람들의 생활 모습 두 가지를 쓰고, 각각 열대 기후의 어떤 특징과 관계있는지 쓰세요.","answer_guide":{"answer":"예: 기둥을 세워 바닥을 땅에서 띄우고 창을 크게 만든 집을 지어요. 일 년 내내 덥고 습해서 바람이 잘 통하게 하려는 것이에요. 또 음식에 다양한 향신료를 써요. 덥고 습해 음식이 쉽게 상하기 때문이에요.","scoring_points":["생활 모습을 두 가지 썼는가","열대 기후의 특징을 바르게 썼는가","생활 모습과 기후 특징을 알맞게 이었는가"]},"explanation":["집, 옷, 음식을 떠올려요.","열대 기후의 특징을 찾아요.","둘을 이어 써요."],"asset":{"type":"passage","lines":["전통 농업 — 화전 농업으로 카사바, 얌, 옥수수 등을 재배","오늘날 — 천연고무, 카카오, 바나나, 커피 등을 대규모로 재배","관광 — 사파리 관광, 전통 부족 생활 체험 등 생태 관광 산업","집 — 바람이 잘 통하도록 창을 크게, 기둥을 세워 바닥을 땅에서 띄움","옷 — 얇고 바람이 잘 통하는 옷"],"title":"교과서 35쪽 열대 기후 지역의 생활"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L07_challenge#10','soc',6,2,'u1','L07','tb_g6_2_soc_u1_L07_challenge','lesson_challenge','SO6-2-u1-C7',4,'essay','teacher','건조 기후 지역 가운데 사막과 초원의 생활 모습을 집과 하는 일을 넣어 견주어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u1-C7","difficulty":4,"kind":"essay","stem":"건조 기후 지역 가운데 사막과 초원의 생활 모습을 집과 하는 일을 넣어 견주어 쓰세요.","answer_guide":{"answer":"예: 사막 지역 사람들은 벽이 두껍고 창문이 작은 흙벽돌 집에서 살고, 오아시스나 강 주변에서 밀이나 대추야자를 재배해요. 초원 지역 사람들은 물과 풀을 찾아 이동하며 가축을 기르는 유목 생활을 하고, 가축의 털이나 가죽으로 만든 이동식 가옥에서 살아요.","scoring_points":["사막의 집과 하는 일을 썼는가","초원의 집과 하는 일을 썼는가","두 곳을 견주어 썼는가"]},"explanation":["사막과 초원을 나눠요.","집과 하는 일을 하나씩 찾아요.","견주어 써요."],"asset":{"type":"passage","lines":["분포 — 저위도와 중위도에서 연중 강수량이 적은 곳","특징 — 낮과 밤의 기온 차이가 큼, 사막 또는 초원이 넓게 나타남","사막 — 온몸을 감싸는 옷, 벽이 두껍고 창문이 작은 흙벽돌 집","초원 — 유목 생활, 가축의 털이나 가죽으로 만든 이동식 가옥,","　가축의 젖으로 만든 유제품이나 고기를 먹음","오아시스나 강 주변 — 밀이나 대추야자를 재배"],"numbered":false,"title":"교과서 36쪽 건조 기후"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L08_basic#1','soc',6,2,'u1','L08','tb_g6_2_soc_u1_L08_basic','lesson_basic','SO6-2-u1-C8',1,'sa','auto','「온대 기후는 (    ) 지역에 주로 나타나며, 사계절이 비교적 뚜렷합니다.」 빈칸에 알맞은 말을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u1-C8","difficulty":1,"kind":"sa","stem":"「온대 기후는 (    ) 지역에 주로 나타나며, 사계절이 비교적 뚜렷합니다.」 빈칸에 알맞은 말을 세 글자로 쓰세요.","answer":["중위도"],"explanation":["꼭 기억해요 첫 문장이에요.","저위도와 고위도 사이예요.","중위도예요."],"mis":"SO6-2-u1-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L08_basic#2','soc',6,2,'u1','L08','tb_g6_2_soc_u1_L08_basic','lesson_basic','SO6-2-u1-C8',1,'ox','auto','「냉대 기후 지역은 겨울에 밀, 옥수수, 감자 등을 재배합니다.」는 바른 문장이에요.',ARRAY['SO6-2-u1-X13']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C8","difficulty":1,"kind":"ox","stem":"「냉대 기후 지역은 겨울에 밀, 옥수수, 감자 등을 재배합니다.」는 바른 문장이에요.","answer":"X","reason_options":[{"t":"냉대 기후 지역은 여름에 밀, 옥수수, 감자 등을 재배하고 춥고 긴 겨울에는 농사를 짓기 어렵기 때문에","correct":true},{"t":"냉대 기후는 겨울이 여름보다 따뜻하기 때문에","mis":"SO6-2-u1-X13"}],"mis":"SO6-2-u1-X13","explanation":["꼭 기억해요 둘째 문장이에요.","냉대 기후의 겨울은 몹시 추워요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L08_basic#3','soc',6,2,'u1','L08','tb_g6_2_soc_u1_L08_basic','lesson_basic','SO6-2-u1-C8',1,'mc','auto','젖소나 염소를 길러 우유, 치즈 등을 만드는 농업은 무엇인가요?',ARRAY['SO6-2-u1-X13','SO6-2-u1-X12']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C8","difficulty":1,"kind":"mc","stem":"젖소나 염소를 길러 우유, 치즈 등을 만드는 농업은 무엇인가요?","options":[{"t":"낙농업","correct":true},{"t":"양식업","mis":"SO6-2-u1-X13"},{"t":"화전 농업","mis":"SO6-2-u1-X12"},{"t":"광업","mis":"SO6-2-u1-X13"}],"explanation":["교과서 38쪽 낱말 풀이예요.","젖으로 우유와 치즈를 만들어요.","낙농업이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L08_basic#4','soc',6,2,'u1','L08','tb_g6_2_soc_u1_L08_basic','lesson_basic','SO6-2-u1-C8',1,'mc','auto','냉대 기후 지역에 넓게 발달한 숲으로, 목재와 펄프 생산에 쓰이는 것은 무엇인가요?',ARRAY['SO6-2-u1-X13','SO6-2-u1-X03']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C8","difficulty":1,"kind":"mc","stem":"냉대 기후 지역에 넓게 발달한 숲으로, 목재와 펄프 생산에 쓰이는 것은 무엇인가요?","options":[{"t":"침엽수림","correct":true},{"t":"열대 우림","mis":"SO6-2-u1-X13"},{"t":"초원","mis":"SO6-2-u1-X13"},{"t":"갯벌","mis":"SO6-2-u1-X03"}],"explanation":["교과서 39쪽 글을 읽어요.","잎이 가늘고 뾰족한 나무의 숲이에요.","침엽수림이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L08_basic#5','soc',6,2,'u1','L08','tb_g6_2_soc_u1_L08_basic','lesson_basic','SO6-2-u1-C8',2,'mc','auto','런던, 로마, 서울의 기후 그래프를 보고 도시별 강수량의 특징을 바르게 짝지은 것은 무엇인가요?',ARRAY['SO6-2-u1-X15','SO6-2-u1-X13']::text[],true,'{"seq":5,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"mc","stem":"런던, 로마, 서울의 기후 그래프를 보고 도시별 강수량의 특징을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"로마 — 여름보다 겨울에 강수량이 많아요","correct":true},{"t":"런던 — 강수량의 대부분이 여름에 집중돼요","mis":"SO6-2-u1-X15"},{"t":"서울 — 연중 강수량이 고르게 나타나요","mis":"SO6-2-u1-X15"},{"t":"로마 — 강수량의 대부분이 여름에 집중돼요","mis":"SO6-2-u1-X13"}],"explanation":["도시마다 막대를 견줘요.","로마는 겨울 막대가 더 높아요.","여름보다 겨울에 강수량이 많아요."],"asset":{"type":"passage","lines":["런던(영국) — 강수량 막대가 일 년 내내 비슷한 높이","로마(이탈리아) — 강수량 막대가 여름보다 겨울에 높음","서울(우리나라) — 강수량 막대가 여름에 아주 높음","세 도시 모두 — 기온 선이 여름철에 가장 높음"],"title":"교과서 37쪽 온대 기후 세 도시의 기후 그래프"},"variant_rule":{"alt":[{"stem":"런던, 로마, 서울 가운데 강수량의 대부분이 여름에 집중된 도시는 어디인가요?","options":[{"t":"서울","correct":true},{"t":"런던","mis":"SO6-2-u1-X15"},{"t":"로마","mis":"SO6-2-u1-X13"},{"t":"세 도시 모두","mis":"SO6-2-u1-X15"}],"explanation":["여름 막대가 아주 높은 도시를 찾아요.","서울은 여름에 비가 많이 와요.","서울이에요."],"asset":{"type":"passage","lines":["런던(영국) — 강수량 막대가 일 년 내내 비슷한 높이","로마(이탈리아) — 강수량 막대가 여름보다 겨울에 높음","서울(우리나라) — 강수량 막대가 여름에 아주 높음","세 도시 모두 — 기온 선이 여름철에 가장 높음"],"title":"교과서 37쪽 온대 기후 세 도시의 기후 그래프"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L08_basic#6','soc',6,2,'u1','L08','tb_g6_2_soc_u1_L08_basic','lesson_basic','SO6-2-u1-C8',2,'match','auto','온대 기후의 지역과 많이 하는 농업을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"match","stem":"온대 기후의 지역과 많이 하는 농업을 이으세요.","pairs":[{"l":"서부 유럽","r":"밀 재배와 낙농업"},{"l":"지중해 주변","r":"올리브와 포도 재배"},{"l":"우리나라를 비롯한 아시아","r":"벼농사"}],"mis":"SO6-2-u1-X13","explanation":["교과서 38쪽 글을 읽어요.","서부 유럽은 밀과 낙농업이에요.","지중해는 올리브·포도, 아시아는 벼농사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L08_basic#7','soc',6,2,'u1','L08','tb_g6_2_soc_u1_L08_basic','lesson_basic','SO6-2-u1-C8',2,'mc','auto','지중해 주변 지역에서 올리브와 포도를 많이 재배하는 까닭은 무엇인가요?',ARRAY['SO6-2-u1-X13','SO6-2-u1-X15']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"mc","stem":"지중해 주변 지역에서 올리브와 포도를 많이 재배하는 까닭은 무엇인가요?","options":[{"t":"올리브와 포도는 여름에 강수량이 적고 건조한 기후에서도 잘 견디기 때문이에요","correct":true},{"t":"지중해 주변은 여름에 비가 가장 많이 오기 때문이에요","mis":"SO6-2-u1-X13"},{"t":"올리브와 포도는 몹시 추운 겨울에만 자라기 때문이에요","mis":"SO6-2-u1-X13"},{"t":"지중해 주변은 일 년 내내 비가 고르기 때문이에요","mis":"SO6-2-u1-X15"}],"explanation":["지중해 주변의 여름을 떠올려요.","덥고 건조해요.","건조한 여름을 잘 견디는 작물을 길러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L08_basic#8','soc',6,2,'u1','L08','tb_g6_2_soc_u1_L08_basic','lesson_basic','SO6-2-u1-C8',2,'ox','auto','냉대 기후 지역에서는 주변에서 쉽게 구할 수 있는 통나무로 집을 지어요.',ARRAY['SO6-2-u1-X13']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"ox","stem":"냉대 기후 지역에서는 주변에서 쉽게 구할 수 있는 통나무로 집을 지어요.","answer":"O","reason_options":[{"t":"침엽수림이 넓게 발달해 나무를 구하기 쉽기 때문에","correct":true},{"t":"냉대 기후 지역에는 나무가 자라지 않기 때문에","mis":"SO6-2-u1-X13"}],"mis":"SO6-2-u1-X13","explanation":["교과서 39쪽 그림이에요.","나무가 많아요.","그래서 O예요."],"asset":{"type":"passage","lines":["분포 — 북반구의 중위도와 고위도 지역","특징 — 사계절이 있지만 겨울이 여름보다 길고 몹시 추우며 눈이 많이 내림","농업 — 여름에는 밀, 옥수수, 감자 등을 재배, 겨울에는 농사가 어려움","숲 — 침엽수림이 넓게 발달하여 목재와 펄프 생산이 활발함","집과 옷 — 통나무집, 두꺼운 털옷과 털모자"],"title":"교과서 39쪽 냉대 기후"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L08_basic#9','soc',6,2,'u1','L08','tb_g6_2_soc_u1_L08_basic','lesson_basic','SO6-2-u1-C8',2,'mc','auto','냉대 기후의 특징으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X13','SO6-2-u1-X14']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"mc","stem":"냉대 기후의 특징으로 알맞은 것은 무엇인가요?","options":[{"t":"사계절이 있지만 겨울이 여름보다 길고 몹시 추우며 눈이 많이 내려요","correct":true},{"t":"일 년 내내 기온이 높고 기온 변화가 거의 없어요","mis":"SO6-2-u1-X13"},{"t":"여름이 서늘하고 겨울이 따뜻하며 강수량이 고르게 나타나요","mis":"SO6-2-u1-X13"},{"t":"일 년 내내 서늘하고 낮과 밤의 기온 차이가 커요","mis":"SO6-2-u1-X14"}],"explanation":["교과서 39쪽 첫 글을 읽어요.","사계절이 있어요.","겨울이 길고 몹시 추워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L08_basic#10','soc',6,2,'u1','L08','tb_g6_2_soc_u1_L08_basic','lesson_basic','SO6-2-u1-C8',3,'error','auto','교과서 38쪽 사진을 두고 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.',ARRAY['SO6-2-u1-X13']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C8","difficulty":3,"kind":"error","stem":"교과서 38쪽 사진을 두고 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.","options":[{"t":"친구 나 — 「영국의 목장은 여름에 강수량이 집중하는 지역의 모습이야.」","correct":true,"mis_target":"SO6-2-u1-X13"},{"t":"친구 가 — 「에스파냐의 올리브 농장은 여름이 건조한 지역의 모습이야.」","mis":"SO6-2-u1-X13"},{"t":"친구 다 — 「중국의 벼농사는 여름에 강수량이 집중하는 지역의 모습이야.」","mis":"SO6-2-u1-X13"}],"explanation":["사진을 강수량 특징으로 나눠요.","영국 목장은 연중 강수량이 고른 지역이에요.","친구 나가 바꿔 말했어요."],"asset":{"type":"passage","lines":["㉠ 밀을 재배하는 농장(프랑스)","㉡ 가축을 기르는 목장(영국)","㉢ 올리브를 재배하는 농장(에스파냐)","㉣ 여름에 관광객이 즐겨 찾는 지중해 연안(이탈리아)","㉤ 벼를 재배하는 평야(중국)","㉥ 가을에 열리는 단풍 축제(일본)"],"numbered":false,"title":"교과서 38쪽 온대 기후 지역 사진 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L08_challenge#1','soc',6,2,'u1','L08','tb_g6_2_soc_u1_L08_challenge','lesson_challenge','SO6-2-u1-C8',2,'mc','auto','런던, 로마, 서울 세 도시의 계절별 기온 변화에서 찾을 수 있는 공통점은 무엇인가요?',ARRAY['SO6-2-u1-X11','SO6-2-u1-X13','SO6-2-u1-X21']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"mc","stem":"런던, 로마, 서울 세 도시의 계절별 기온 변화에서 찾을 수 있는 공통점은 무엇인가요?","options":[{"t":"일 년 가운데 여름철 기온이 가장 높아요","correct":true},{"t":"일 년 내내 기온이 똑같아요","mis":"SO6-2-u1-X11"},{"t":"겨울철 기온이 가장 높아요","mis":"SO6-2-u1-X13"},{"t":"강수량 막대가 기온을 나타내요","mis":"SO6-2-u1-X21"}],"explanation":["세 그래프의 선을 견줘요.","모두 여름에 선이 가장 높아요.","여름철 기온이 가장 높아요."],"asset":{"type":"passage","lines":["런던(영국) — 강수량 막대가 일 년 내내 비슷한 높이","로마(이탈리아) — 강수량 막대가 여름보다 겨울에 높음","서울(우리나라) — 강수량 막대가 여름에 아주 높음","세 도시 모두 — 기온 선이 여름철에 가장 높음"],"title":"교과서 37쪽 온대 기후 세 도시의 기후 그래프"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L08_challenge#2','soc',6,2,'u1','L08','tb_g6_2_soc_u1_L08_challenge','lesson_challenge','SO6-2-u1-C8',2,'mc','auto','교과서 39쪽 예시에서 냉대 기후 지역에 알맞은 관광 상품으로 든 것은 무엇인가요?',ARRAY['SO6-2-u1-X12']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"mc","stem":"교과서 39쪽 예시에서 냉대 기후 지역에 알맞은 관광 상품으로 든 것은 무엇인가요?","options":[{"t":"얼음 축제 체험","correct":true},{"t":"사막 모래 썰매 타기","mis":"SO6-2-u1-X12"},{"t":"열대 과일 따기","mis":"SO6-2-u1-X12"},{"t":"수상 시장 장보기","mis":"SO6-2-u1-X12"}],"explanation":["냉대 기후의 겨울을 떠올려요.","춥고 눈과 얼음이 많아요.","얼음 축제 체험이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L08_challenge#3','soc',6,2,'u1','L08','tb_g6_2_soc_u1_L08_challenge','lesson_challenge','SO6-2-u1-C8',3,'mc','auto','침엽수림에서 펄프 생산이 활발한 까닭과 펄프의 쓰임을 바르게 말한 것은 무엇인가요?',ARRAY['SO6-2-u1-X13','SO6-2-u1-X03']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C8","difficulty":3,"kind":"mc","stem":"침엽수림에서 펄프 생산이 활발한 까닭과 펄프의 쓰임을 바르게 말한 것은 무엇인가요?","options":[{"t":"침엽수는 나무가 부드러워 펄프를 만들기 좋고, 펄프는 종이의 원료예요","correct":true},{"t":"침엽수는 매우 단단해 펄프를 만들기 좋고, 펄프는 옷감의 원료예요","mis":"SO6-2-u1-X13"},{"t":"침엽수림은 겨울에 사라져 펄프를 만들 수 없어요","mis":"SO6-2-u1-X13"},{"t":"펄프는 바닷물에서 뽑아내는 소금이에요","mis":"SO6-2-u1-X03"}],"explanation":["그림 속 말풍선을 떠올려요.","침엽수는 부드러워요.","펄프는 종이의 원료예요."],"asset":{"type":"passage","lines":["분포 — 북반구의 중위도와 고위도 지역","특징 — 사계절이 있지만 겨울이 여름보다 길고 몹시 추우며 눈이 많이 내림","농업 — 여름에는 밀, 옥수수, 감자 등을 재배, 겨울에는 농사가 어려움","숲 — 침엽수림이 넓게 발달하여 목재와 펄프 생산이 활발함","집과 옷 — 통나무집, 두꺼운 털옷과 털모자"],"title":"교과서 39쪽 냉대 기후"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L08_challenge#4','soc',6,2,'u1','L08','tb_g6_2_soc_u1_L08_challenge','lesson_challenge','SO6-2-u1-C8',3,'mc','auto','「기후가 만든 독특한 문화」 가운데 핀란드 운전면허 시험에 영향을 준 기후 특징은 무엇인가요?',ARRAY['SO6-2-u1-X11','SO6-2-u1-X13']::text[],true,'{"seq":4,"concept":"SO6-2-u1-C8","difficulty":3,"kind":"mc","stem":"「기후가 만든 독특한 문화」 가운데 핀란드 운전면허 시험에 영향을 준 기후 특징은 무엇인가요?","options":[{"t":"겨울이 몹시 춥고 길며 눈이 많이 온다는 점","correct":true},{"t":"강수량이 매우 적고 기온이 높다는 점","mis":"SO6-2-u1-X11"},{"t":"흐리거나 비가 내리는 날이 많다는 점","mis":"SO6-2-u1-X13"},{"t":"일 년 내내 기온 변화가 거의 없다는 점","mis":"SO6-2-u1-X13"}],"explanation":["사례 ②를 읽어요.","일 년의 절반이 겨울이에요.","눈과 빙판 위 운전을 중요하게 다뤄요."],"asset":{"type":"passage","lines":["① 이집트 사람들은 「에이쉬」라는 빵을 즐겨 먹어요.","　빵은 국수나 죽보다 훨씬 적은 물로 만들고 오래 보관할 수 있어요.","② 일 년의 절반이 겨울인 핀란드는 운전면허 시험에서","　눈·빙판 위 운전과 야생 동물을 만났을 때의 대처를 중요하게 다뤄요.","③ 프랑스 파리 시민들은 흐리거나 비 오는 날이 많아 햇빛이 부족해,","　맑은 날에 공원 잔디밭이나 강변에서 일광욕을 즐겨요."],"numbered":false,"title":"교과서 40쪽 기후가 만든 독특한 문화"},"variant_rule":{"alt":[{"stem":"「기후가 만든 독특한 문화」 가운데 파리 시민들이 맑은 날 일광욕을 즐기는 데 영향을 준 기후 특징은 무엇인가요?","options":[{"t":"흐리거나 비가 내리는 날이 많다는 점","correct":true},{"t":"강수량이 매우 적고 기온이 높다는 점","mis":"SO6-2-u1-X11"},{"t":"겨울이 몹시 춥고 길며 눈이 많이 온다는 점","mis":"SO6-2-u1-X13"},{"t":"일 년 내내 기온 변화가 거의 없다는 점","mis":"SO6-2-u1-X13"}],"explanation":["사례 ③을 읽어요.","흐리거나 비 오는 날이 많아요.","햇빛이 부족해 맑은 날 해를 쬐어요."],"asset":{"type":"passage","lines":["① 이집트 사람들은 「에이쉬」라는 빵을 즐겨 먹어요.","　빵은 국수나 죽보다 훨씬 적은 물로 만들고 오래 보관할 수 있어요.","② 일 년의 절반이 겨울인 핀란드는 운전면허 시험에서","　눈·빙판 위 운전과 야생 동물을 만났을 때의 대처를 중요하게 다뤄요.","③ 프랑스 파리 시민들은 흐리거나 비 오는 날이 많아 햇빛이 부족해,","　맑은 날에 공원 잔디밭이나 강변에서 일광욕을 즐겨요."],"numbered":false,"title":"교과서 40쪽 기후가 만든 독특한 문화"}},{"stem":"「기후가 만든 독특한 문화」 가운데 이집트 사람들이 빵을 즐겨 먹는 데 영향을 준 기후 특징은 무엇인가요?","options":[{"t":"강수량이 매우 적어 물이 부족하다는 점","correct":true},{"t":"흐리거나 비가 내리는 날이 많다는 점","mis":"SO6-2-u1-X13"},{"t":"겨울이 몹시 춥고 길며 눈이 많이 온다는 점","mis":"SO6-2-u1-X13"},{"t":"일 년 내내 비가 많이 내린다는 점","mis":"SO6-2-u1-X11"}],"explanation":["사례 ①을 읽어요.","빵은 적은 물로 만들어요.","물이 부족한 건조 기후 때문이에요."],"asset":{"type":"passage","lines":["① 이집트 사람들은 「에이쉬」라는 빵을 즐겨 먹어요.","　빵은 국수나 죽보다 훨씬 적은 물로 만들고 오래 보관할 수 있어요.","② 일 년의 절반이 겨울인 핀란드는 운전면허 시험에서","　눈·빙판 위 운전과 야생 동물을 만났을 때의 대처를 중요하게 다뤄요.","③ 프랑스 파리 시민들은 흐리거나 비 오는 날이 많아 햇빛이 부족해,","　맑은 날에 공원 잔디밭이나 강변에서 일광욕을 즐겨요."],"numbered":false,"title":"교과서 40쪽 기후가 만든 독특한 문화"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L08_challenge#5','soc',6,2,'u1','L08','tb_g6_2_soc_u1_L08_challenge','lesson_challenge','SO6-2-u1-C8',3,'ox','auto','온대 기후 지역은 모두 여름에 비가 많이 내리고 겨울은 춥고 건조해요.',ARRAY['SO6-2-u1-X15']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C8","difficulty":3,"kind":"ox","stem":"온대 기후 지역은 모두 여름에 비가 많이 내리고 겨울은 춥고 건조해요.","answer":"X","reason_options":[{"t":"서부 유럽은 연중 강수량이 고르고, 지중해 주변은 여름이 건조하고 겨울에 강수량이 많듯 지역마다 다르기 때문에","correct":true},{"t":"온대 기후는 우리나라에만 나타나기 때문에","mis":"SO6-2-u1-X15"}],"mis":"SO6-2-u1-X15","explanation":["온대 기후의 세 모습을 떠올려요.","강수량 특징이 지역마다 달라요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L08_challenge#6','soc',6,2,'u1','L08','tb_g6_2_soc_u1_L08_challenge','lesson_challenge','SO6-2-u1-C8',3,'mc','auto','온대 기후에 적응하며 살아가는 사람들의 모습으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X12']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C8","difficulty":3,"kind":"mc","stem":"온대 기후에 적응하며 살아가는 사람들의 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"계절별로 옷을 달리 입어 더운 여름과 추운 겨울을 나요","correct":true},{"t":"일 년 내내 얇은 옷만 입어요","mis":"SO6-2-u1-X12"},{"t":"일 년 내내 두꺼운 털옷만 입어요","mis":"SO6-2-u1-X12"},{"t":"가축을 따라 늘 옮겨 다니며 살아요","mis":"SO6-2-u1-X12"}],"explanation":["온대 기후는 사계절이 뚜렷해요.","계절마다 기온이 달라요.","계절에 맞게 옷을 달리 입어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L08_challenge#7','soc',6,2,'u1','L08','tb_g6_2_soc_u1_L08_challenge','lesson_challenge','SO6-2-u1-C8',3,'error','auto','온대 기후와 냉대 기후를 두고 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.',ARRAY['SO6-2-u1-X10','SO6-2-u1-X13']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C8","difficulty":3,"kind":"error","stem":"온대 기후와 냉대 기후를 두고 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.","options":[{"t":"친구 다 — 「냉대 기후는 남반구의 중위도와 고위도에서 널리 나타나.」","correct":true,"mis_target":"SO6-2-u1-X10"},{"t":"친구 가 — 「냉대 기후도 온대 기후처럼 사계절이 있어.」","mis":"SO6-2-u1-X13"},{"t":"친구 나 — 「온대 기후 지역은 온화한 기후를 바탕으로 다양한 농업이 발달했어.」","mis":"SO6-2-u1-X13"}],"explanation":["냉대 기후의 분포를 떠올려요.","북반구의 중위도와 고위도에 널리 나타나요.","친구 다의 말이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L08_challenge#8','soc',6,2,'u1','L08','tb_g6_2_soc_u1_L08_challenge','lesson_challenge','SO6-2-u1-C8',4,'mc','auto','에스파냐의 「시에스타」처럼 한낮에 점심 식사 후 짧게 쉬는 문화가 생긴 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X13','SO6-2-u1-X02']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C8","difficulty":4,"kind":"mc","stem":"에스파냐의 「시에스타」처럼 한낮에 점심 식사 후 짧게 쉬는 문화가 생긴 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"한낮에 기온이 매우 높기 때문이에요","correct":true},{"t":"겨울이 길고 몹시 춥기 때문이에요","mis":"SO6-2-u1-X13"},{"t":"햇빛이 부족해 해를 쬐어야 하기 때문이에요","mis":"SO6-2-u1-X13"},{"t":"비가 일 년 내내 고르게 오기 때문이에요","mis":"SO6-2-u1-X02"}],"explanation":["에스파냐는 지중해 주변이에요.","여름 한낮이 몹시 더워요.","더운 때를 피해 쉬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L08_challenge#9','soc',6,2,'u1','L08','tb_g6_2_soc_u1_L08_challenge','lesson_challenge','SO6-2-u1-C8',4,'essay','teacher','냉대 기후의 특징을 쓰고, 그 특징을 살린 관광 상품을 하나 만들어 상품 이름과 내용을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u1-C8","difficulty":4,"kind":"essay","stem":"냉대 기후의 특징을 쓰고, 그 특징을 살린 관광 상품을 하나 만들어 상품 이름과 내용을 쓰세요.","answer_guide":{"answer":"예: 냉대 기후는 겨울이 여름보다 길고 몹시 추우며 눈이 많이 내리고, 침엽수림이 넓게 발달해요. 관광 상품 — 「눈 덮인 숲속 통나무집 여행」. 침엽수림 속 통나무집에서 지내며 얼음 축제를 체험하고, 펄프 생산 공장도 견학해요.","scoring_points":["냉대 기후의 특징을 바르게 썼는가","관광 상품에 그 특징을 살렸는가","상품 이름과 내용을 썼는가"]},"explanation":["냉대 기후를 떠올려요.","특징을 살릴 체험을 찾아요.","이름과 내용을 정해요."],"asset":{"type":"passage","lines":["분포 — 북반구의 중위도와 고위도 지역","특징 — 사계절이 있지만 겨울이 여름보다 길고 몹시 추우며 눈이 많이 내림","농업 — 여름에는 밀, 옥수수, 감자 등을 재배, 겨울에는 농사가 어려움","숲 — 침엽수림이 넓게 발달하여 목재와 펄프 생산이 활발함","집과 옷 — 통나무집, 두꺼운 털옷과 털모자"],"title":"교과서 39쪽 냉대 기후"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L08_challenge#10','soc',6,2,'u1','L08','tb_g6_2_soc_u1_L08_challenge','lesson_challenge','SO6-2-u1-C8',4,'essay','teacher','런던, 로마, 서울은 모두 온대 기후이지만 많이 하는 농업이 달라요. 세 곳의 강수량 특징과 농업을 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u1-C8","difficulty":4,"kind":"essay","stem":"런던, 로마, 서울은 모두 온대 기후이지만 많이 하는 농업이 달라요. 세 곳의 강수량 특징과 농업을 이어 쓰세요.","answer_guide":{"answer":"예: 런던이 있는 서부 유럽은 연중 강수량이 고르고 여름이 서늘해 밀을 재배하고 낙농업이 발달했어요. 로마가 있는 지중해 주변은 여름이 건조해 그 기후를 잘 견디는 올리브와 포도를 재배해요. 서울처럼 여름에 강수량이 집중되는 곳에서는 벼농사를 많이 지어요.","scoring_points":["세 곳의 강수량 특징을 썼는가","세 곳의 농업을 썼는가","강수량 특징과 농업을 알맞게 이었는가"]},"explanation":["세 그래프의 막대를 봐요.","비가 오는 때가 달라요.","그에 맞는 농업을 이어요."],"asset":{"type":"passage","lines":["런던(영국) — 강수량 막대가 일 년 내내 비슷한 높이","로마(이탈리아) — 강수량 막대가 여름보다 겨울에 높음","서울(우리나라) — 강수량 막대가 여름에 아주 높음","세 도시 모두 — 기온 선이 여름철에 가장 높음"],"title":"교과서 37쪽 온대 기후 세 도시의 기후 그래프"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L09_basic#1','soc',6,2,'u1','L09','tb_g6_2_soc_u1_L09_basic','lesson_basic','SO6-2-u1-C9',1,'sa','auto','「한대 기후는 남극과 북극 주변의 (    ) 지역에 주로 나타납니다.」 빈칸에 알맞은 말을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u1-C9","difficulty":1,"kind":"sa","stem":"「한대 기후는 남극과 북극 주변의 (    ) 지역에 주로 나타납니다.」 빈칸에 알맞은 말을 세 글자로 쓰세요.","answer":["고위도"],"explanation":["꼭 기억해요 첫 문장이에요.","극지방 가까이예요.","고위도예요."],"mis":"SO6-2-u1-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L09_basic#2','soc',6,2,'u1','L09','tb_g6_2_soc_u1_L09_basic','lesson_basic','SO6-2-u1-C9',1,'mc','auto','「고산 기후는 해발 고도가 (높은, 낮은) 지역에 나타나며, 적도 주변의 일부 고산 기후 지역은 일 년 내내 (무더운, 서늘한) 날씨가 이어집니다.」에서 알맞은 말을 차례로 고른 것은 무엇인가요?',ARRAY['SO6-2-u1-X14','SO6-2-u1-X09']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C9","difficulty":1,"kind":"mc","stem":"「고산 기후는 해발 고도가 (높은, 낮은) 지역에 나타나며, 적도 주변의 일부 고산 기후 지역은 일 년 내내 (무더운, 서늘한) 날씨가 이어집니다.」에서 알맞은 말을 차례로 고른 것은 무엇인가요?","options":[{"t":"높은 — 서늘한","correct":true},{"t":"낮은 — 서늘한","mis":"SO6-2-u1-X14"},{"t":"높은 — 무더운","mis":"SO6-2-u1-X09"},{"t":"낮은 — 무더운","mis":"SO6-2-u1-X14"}],"explanation":["꼭 기억해요 둘째 문장이에요.","고산은 높은 산이에요.","높을수록 기온이 낮아 서늘해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L09_basic#3','soc',6,2,'u1','L09','tb_g6_2_soc_u1_L09_basic','lesson_basic','SO6-2-u1-C9',1,'blank','auto','극지방의 하늘에서 여러 가지 색깔의 빛이 나타나는 현상을 (    )(이)라고 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-2-u1-X14','SO6-2-u1-X03']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C9","difficulty":1,"kind":"blank","stem":"극지방의 하늘에서 여러 가지 색깔의 빛이 나타나는 현상을 (    )(이)라고 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"오로라","correct":true},{"t":"빙하","mis":"SO6-2-u1-X14"},{"t":"무지개","mis":"SO6-2-u1-X14"},{"t":"화산","mis":"SO6-2-u1-X03"}],"explanation":["교과서 41쪽 낱말 풀이예요.","극지방 하늘에 빛이 나타나요.","오로라예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L09_basic#4','soc',6,2,'u1','L09','tb_g6_2_soc_u1_L09_basic','lesson_basic','SO6-2-u1-C9',1,'mc','auto','고산 기후 지역 사람들이 주로 기르는 동물은 무엇인가요?',ARRAY['SO6-2-u1-X14','SO6-2-u1-X12','SO6-2-u1-X13']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C9","difficulty":1,"kind":"mc","stem":"고산 기후 지역 사람들이 주로 기르는 동물은 무엇인가요?","options":[{"t":"알파카와 라마","correct":true},{"t":"순록","mis":"SO6-2-u1-X14"},{"t":"낙타","mis":"SO6-2-u1-X12"},{"t":"젖소","mis":"SO6-2-u1-X13"}],"explanation":["교과서 42쪽 사진을 떠올려요.","높은 산지에서 기르는 동물이에요.","알파카와 라마예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L09_basic#5','soc',6,2,'u1','L09','tb_g6_2_soc_u1_L09_basic','lesson_basic','SO6-2-u1-C9',2,'mc','auto','한대 기후 지역에서 순록을 기르며 유목 생활을 하는 곳의 모습으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X11','SO6-2-u1-X12','SO6-2-u1-X14']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C9","difficulty":2,"kind":"mc","stem":"한대 기후 지역에서 순록을 기르며 유목 생활을 하는 곳의 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"짧은 여름에 땅이 녹아 이끼와 같은 작은 풀이 자라는 곳","correct":true},{"t":"일 년 내내 기온이 높아 열대 우림을 이루는 곳","mis":"SO6-2-u1-X11"},{"t":"오아시스 주변에서 대추야자를 기르는 곳","mis":"SO6-2-u1-X12"},{"t":"적도 주변의 서늘한 높은 산지","mis":"SO6-2-u1-X14"}],"explanation":["교과서 41쪽 글을 읽어요.","짧은 여름에 땅이 녹아요.","이끼 같은 작은 풀이 자라는 곳이에요."],"asset":{"type":"passage","lines":["분포 — 남극과 북극 주변의 고위도 지역","특징 — 겨울이 길고 기온이 매우 낮아 일 년 내내 눈과 얼음으로 덮인 곳이 많음","먹거리 — 사냥하여 얻은 생선과 고기","유목 — 짧은 여름에 땅이 녹아 이끼 같은 작은 풀이 자라는 곳에서 순록을 기름","오늘날 — 지하자원 개발, 극지방 기후 환경 연구, 오로라·빙하 관광"],"title":"교과서 41쪽 한대 기후"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L09_basic#6','soc',6,2,'u1','L09','tb_g6_2_soc_u1_L09_basic','lesson_basic','SO6-2-u1-C9',2,'mc','auto','고산 기후 지역 사람들이 챙이 넓고 둥근 모자를 쓰는 까닭은 무엇인가요?',ARRAY['SO6-2-u1-X12']::text[],true,'{"seq":6,"concept":"SO6-2-u1-C9","difficulty":2,"kind":"mc","stem":"고산 기후 지역 사람들이 챙이 넓고 둥근 모자를 쓰는 까닭은 무엇인가요?","options":[{"t":"강한 햇빛을 막으려고","correct":true},{"t":"비를 많이 받으려고","mis":"SO6-2-u1-X12"},{"t":"모래바람을 막으려고","mis":"SO6-2-u1-X12"},{"t":"가축의 털을 모으려고","mis":"SO6-2-u1-X12"}],"explanation":["교과서 42쪽 글을 읽어요.","높은 산지는 햇빛이 강해요.","넓은 챙으로 햇빛을 막아요."],"variant_rule":{"alt":[{"stem":"고산 기후 지역 사람들이 옷을 여러 겹 입고 망토를 두르는 까닭은 무엇인가요?","options":[{"t":"낮과 밤의 기온 차이가 큰 기후에 적응하려고","correct":true},{"t":"일 년 내내 몹시 더워 땀을 막으려고","mis":"SO6-2-u1-X12"},{"t":"모래바람을 막으려고","mis":"SO6-2-u1-X12"},{"t":"비가 많이 와서 젖지 않으려고","mis":"SO6-2-u1-X12"}],"explanation":["교과서 42쪽 글을 읽어요.","낮과 밤의 기온 차이가 커요.","여러 겹 옷과 망토로 적응해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L09_basic#7','soc',6,2,'u1','L09','tb_g6_2_soc_u1_L09_basic','lesson_basic','SO6-2-u1-C9',2,'match','auto','기후와 그 기후 지역의 생활 모습을 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO6-2-u1-C9","difficulty":2,"kind":"match","stem":"기후와 그 기후 지역의 생활 모습을 이으세요.","pairs":[{"l":"한대 기후","r":"순록을 기르는 유목"},{"l":"고산 기후","r":"감자와 옥수수 재배"},{"l":"냉대 기후","r":"목재와 펄프 생산"},{"l":"건조 기후","r":"흙벽돌로 만든 집"}],"mis":"SO6-2-u1-X14","explanation":["기후마다 생활을 떠올려요.","한대는 순록, 고산은 감자와 옥수수예요.","냉대는 펄프, 건조는 흙벽돌 집이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L09_basic#8','soc',6,2,'u1','L09','tb_g6_2_soc_u1_L09_basic','lesson_basic','SO6-2-u1-C9',2,'ox','auto','고산 기후는 남극과 북극 주변에만 나타나요.',ARRAY['SO6-2-u1-X14']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C9","difficulty":2,"kind":"ox","stem":"고산 기후는 남극과 북극 주변에만 나타나요.","answer":"X","reason_options":[{"t":"고산 기후는 해발 고도가 높은 지역에 나타나 적도 주변에도 있기 때문에","correct":true},{"t":"추운 기후는 모두 극지방에만 있기 때문에","mis":"SO6-2-u1-X14"}],"mis":"SO6-2-u1-X14","explanation":["고산 도시를 떠올려요.","키토, 보고타처럼 적도 주변에도 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["보고타(콜롬비아) · 멕시코시티(멕시코) · 라파스(볼리비아)","쿠스코(페루) · 키토(에콰도르) · 아디스아바바(에티오피아)"],"title":"교과서 42쪽 고산 기후 지역에 발달한 도시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L09_basic#9','soc',6,2,'u1','L09','tb_g6_2_soc_u1_L09_basic','lesson_basic','SO6-2-u1-C9',2,'mc','auto','최근 한대 기후 지역에서 활발하게 이루어지는 일로 알맞지 않은 것은 무엇인가요?',ARRAY['SO6-2-u1-X14']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C9","difficulty":2,"kind":"mc","stem":"최근 한대 기후 지역에서 활발하게 이루어지는 일로 알맞지 않은 것은 무엇인가요?","options":[{"t":"넓은 평야에서 벼를 대규모로 재배해요","correct":true},{"t":"지하자원을 개발해요","mis":"SO6-2-u1-X14"},{"t":"극지방 기후 환경을 연구해요","mis":"SO6-2-u1-X14"},{"t":"오로라와 빙하 등을 이용한 관광 산업을 해요","mis":"SO6-2-u1-X14"}],"explanation":["교과서 41쪽 글을 읽어요.","기온이 낮아 농사를 짓기 어려워요.","벼 재배는 알맞지 않아요."],"asset":{"type":"passage","lines":["분포 — 남극과 북극 주변의 고위도 지역","특징 — 겨울이 길고 기온이 매우 낮아 일 년 내내 눈과 얼음으로 덮인 곳이 많음","먹거리 — 사냥하여 얻은 생선과 고기","유목 — 짧은 여름에 땅이 녹아 이끼 같은 작은 풀이 자라는 곳에서 순록을 기름","오늘날 — 지하자원 개발, 극지방 기후 환경 연구, 오로라·빙하 관광"],"title":"교과서 41쪽 한대 기후"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L09_basic#10','soc',6,2,'u1','L09','tb_g6_2_soc_u1_L09_basic','lesson_basic','SO6-2-u1-C9',3,'error','auto','한대 기후와 고산 기후를 두고 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.',ARRAY['SO6-2-u1-X14']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"error","stem":"한대 기후와 고산 기후를 두고 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.","options":[{"t":"친구 가 — 「적도 주변의 고산 기후 지역은 너무 추워서 사람이 거의 살지 않아.」","correct":true,"mis_target":"SO6-2-u1-X14"},{"t":"친구 나 — 「한대 기후 지역은 겨울이 길고 기온이 매우 낮아.」","mis":"SO6-2-u1-X14"},{"t":"친구 다 — 「고산 기후 지역 사람들은 알파카와 라마를 길러.」","mis":"SO6-2-u1-X14"}],"explanation":["교과서 42쪽 글을 읽어요.","일 년 내내 서늘해 사람이 많이 모여 살아요.","친구 가의 말이 알맞지 않아요."],"asset":{"type":"passage","lines":["분포 — 해발 고도가 높은 지역","적도 주변의 일부 고산 기후 지역 — 일 년 내내 서늘하여 사람이 많이 모여 삶","농업과 가축 — 감자, 옥수수 재배 · 알파카, 라마 기르기","옷 — 챙이 넓고 둥근 모자로 강한 햇빛을 막음,","　옷을 여러 겹 입고 망토를 둘러 낮과 밤의 큰 기온 차이에 적응"],"numbered":false,"title":"교과서 42쪽 고산 기후"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L09_challenge#1','soc',6,2,'u1','L09','tb_g6_2_soc_u1_L09_challenge','lesson_challenge','SO6-2-u1-C9',2,'mc','auto','교과서 42쪽에 나온 고산 기후 지역에 발달한 도시와 나라를 바르게 짝지은 것은 무엇인가요?',ARRAY['SO6-2-u1-X14']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C9","difficulty":2,"kind":"mc","stem":"교과서 42쪽에 나온 고산 기후 지역에 발달한 도시와 나라를 바르게 짝지은 것은 무엇인가요?","options":[{"t":"키토 — 에콰도르","correct":true},{"t":"보고타 — 멕시코","mis":"SO6-2-u1-X14"},{"t":"라파스 — 페루","mis":"SO6-2-u1-X14"},{"t":"쿠스코 — 콜롬비아","mis":"SO6-2-u1-X14"}],"explanation":["고산 도시 목록을 떠올려요.","키토는 에콰도르에 있어요.","나머지는 나라가 바뀌었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L09_challenge#2','soc',6,2,'u1','L09','tb_g6_2_soc_u1_L09_challenge','lesson_challenge','SO6-2-u1-C9',2,'sa','auto','극지방의 육지, 바다, 대기를 관측·분석하고 극지 동식물의 생태계를 연구하는 직업을 무엇이라고 하나요?','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u1-C9","difficulty":2,"kind":"sa","stem":"극지방의 육지, 바다, 대기를 관측·분석하고 극지 동식물의 생태계를 연구하는 직업을 무엇이라고 하나요?","answer":["극지 과학자","극지과학자"],"explanation":["교과서 43쪽 별별 직업이에요.","극지를 연구해요.","극지 과학자예요."],"asset":{"type":"passage","lines":["하는 일 — 극지방의 육지, 바다, 대기를 관측·분석하고,","　극지 동식물의 생태계 관리와 보전을 위한 연구를 해요.","필요한 것 — 환경과 지구의 미래에 관심을 두고 관련 책을 많이 읽기,","　극지 연구소의 보도 자료와 누리집 살펴보기","우리나라는 극지 연구를 위해 남극에 장보고 과학 기지를 세웠어요."],"numbered":false,"title":"교과서 43쪽 별별 직업 — 극지 과학자"},"mis":"SO6-2-u1-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L09_challenge#3','soc',6,2,'u1','L09','tb_g6_2_soc_u1_L09_challenge','lesson_challenge','SO6-2-u1-C9',3,'mc','auto','적도 주변의 일부 고산 기후 지역에 사람이 많이 모여 사는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X09','SO6-2-u1-X14','SO6-2-u1-X11']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"mc","stem":"적도 주변의 일부 고산 기후 지역에 사람이 많이 모여 사는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"적도 주변이지만 해발 고도가 높아 일 년 내내 서늘한 날씨가 이어지기 때문이에요","correct":true},{"t":"적도 주변은 어디나 무덥기 때문이에요","mis":"SO6-2-u1-X09"},{"t":"일 년 내내 눈과 얼음으로 덮여 있기 때문이에요","mis":"SO6-2-u1-X14"},{"t":"강수량이 매우 적어 사막이 넓기 때문이에요","mis":"SO6-2-u1-X11"}],"explanation":["적도 주변은 덥지만","높이 올라가면 기온이 낮아져요.","서늘해 살기 좋아요."],"asset":{"type":"passage","lines":["분포 — 해발 고도가 높은 지역","적도 주변의 일부 고산 기후 지역 — 일 년 내내 서늘하여 사람이 많이 모여 삶","농업과 가축 — 감자, 옥수수 재배 · 알파카, 라마 기르기","옷 — 챙이 넓고 둥근 모자로 강한 햇빛을 막음,","　옷을 여러 겹 입고 망토를 둘러 낮과 밤의 큰 기온 차이에 적응"],"numbered":false,"title":"교과서 42쪽 고산 기후"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L09_challenge#4','soc',6,2,'u1','L09','tb_g6_2_soc_u1_L09_challenge','lesson_challenge','SO6-2-u1-C9',3,'mc','auto','고산 기후 지역에서 집을 지을 때 창문을 작게 만드는 까닭은 무엇인가요?',ARRAY['SO6-2-u1-X12']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"mc","stem":"고산 기후 지역에서 집을 지을 때 창문을 작게 만드는 까닭은 무엇인가요?","options":[{"t":"강한 바람이 많이 불기 때문이에요","correct":true},{"t":"바람이 잘 통하게 하려고","mis":"SO6-2-u1-X12"},{"t":"땅의 습기를 피하려고","mis":"SO6-2-u1-X12"},{"t":"비가 많이 내려서예요","mis":"SO6-2-u1-X12"}],"explanation":["높은 산지를 떠올려요.","강한 바람이 많이 불어요.","창문을 작게 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L09_challenge#5','soc',6,2,'u1','L09','tb_g6_2_soc_u1_L09_challenge','lesson_challenge','SO6-2-u1-C9',3,'ox','auto','한대 기후 지역은 기온이 낮아 농사를 짓기 어렵기 때문에 사냥이나 고기잡이를 해 왔어요.',ARRAY['SO6-2-u1-X14']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"ox","stem":"한대 기후 지역은 기온이 낮아 농사를 짓기 어렵기 때문에 사냥이나 고기잡이를 해 왔어요.","answer":"O","reason_options":[{"t":"교과서 41쪽처럼 사냥하여 얻은 생선과 고기를 주로 먹기 때문에","correct":true},{"t":"한대 기후 지역은 일 년 내내 따뜻해 농사가 잘되기 때문에","mis":"SO6-2-u1-X14"}],"mis":"SO6-2-u1-X14","explanation":["한대 기후는 기온이 매우 낮아요.","농사가 어려워요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L09_challenge#6','soc',6,2,'u1','L09','tb_g6_2_soc_u1_L09_challenge','lesson_challenge','SO6-2-u1-C9',3,'mc','auto','교과서 41쪽 친구와 활동에서 한대 기후 지역에서 체험해 보고 싶은 것으로 알맞게 말한 것은 무엇인가요?',ARRAY['SO6-2-u1-X14']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"mc","stem":"교과서 41쪽 친구와 활동에서 한대 기후 지역에서 체험해 보고 싶은 것으로 알맞게 말한 것은 무엇인가요?","options":[{"t":"빙하 관광을 해 보고 싶어요","correct":true},{"t":"사막에서 모래 썰매를 타 보고 싶어요","mis":"SO6-2-u1-X14"},{"t":"열대 우림에서 사파리 관광을 해 보고 싶어요","mis":"SO6-2-u1-X14"},{"t":"지중해 해변에서 해수욕을 해 보고 싶어요","mis":"SO6-2-u1-X14"}],"explanation":["한대 기후 지역을 떠올려요.","눈과 얼음이 많아요.","빙하 관광이 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L09_challenge#7','soc',6,2,'u1','L09','tb_g6_2_soc_u1_L09_challenge','lesson_challenge','SO6-2-u1-C9',3,'error','auto','활동지 예시를 두고 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.',ARRAY['SO6-2-u1-X12','SO6-2-u1-X14']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"error","stem":"활동지 예시를 두고 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.","options":[{"t":"친구 나 — 「바닥을 띄운 집은 바람이 잘 통하게 해서 더위를 피하려는 거야.」","correct":true,"mis_target":"SO6-2-u1-X12"},{"t":"친구 가 — 「집의 열이 땅에 전해져 언 땅이 녹으면 건물이 무너질 수 있대.」","mis":"SO6-2-u1-X14"},{"t":"친구 다 — 「그래서 집의 바닥을 땅에서 띄운 집을 지어.」","mis":"SO6-2-u1-X14"}],"explanation":["예시의 기후를 확인해요.","한대 기후 지역은 땅이 얼어 있어요.","친구 나는 열대 기후의 집과 헷갈렸어요."],"asset":{"type":"passage","lines":["기후 — 한대 기후 · 나라 — 노르웨이","한대 기후 지역은 집의 열이 지면에 전달되어 얼어 있는 땅이 녹으면","건물이 무너질 위험이 있어요.","그래서 집의 바닥을 땅에서 띄운 고상 가옥을 지어요."],"title":"활동지 예시 — 한대 기후의 생활 모습 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L09_challenge#8','soc',6,2,'u1','L09','tb_g6_2_soc_u1_L09_challenge','lesson_challenge','SO6-2-u1-C9',4,'mc','auto','적도 근처의 낮은 마을과 같은 위도에 있는 높은 산지 도시를 견준 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X14','SO6-2-u1-X09']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C9","difficulty":4,"kind":"mc","stem":"적도 근처의 낮은 마을과 같은 위도에 있는 높은 산지 도시를 견준 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"높은 산지 도시가 더 서늘해요 — 해발 고도가 높을수록 기온이 낮아지기 때문이에요","correct":true},{"t":"낮은 마을이 더 서늘해요 — 낮은 곳일수록 기온이 낮기 때문이에요","mis":"SO6-2-u1-X14"},{"t":"두 곳의 기후가 똑같아요 — 위도가 같기 때문이에요","mis":"SO6-2-u1-X09"},{"t":"높은 산지 도시가 더 더워요 — 해에 더 가깝기 때문이에요","mis":"SO6-2-u1-X09"}],"explanation":["위도가 같아요.","해발 고도가 달라요.","높을수록 기온이 낮아 서늘해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L09_challenge#9','soc',6,2,'u1','L09','tb_g6_2_soc_u1_L09_challenge','lesson_challenge','SO6-2-u1-C9',4,'essay','teacher','고산 기후 지역 사람들의 옷차림을 쓰고, 그 옷차림이 고산 기후의 어떤 특징에 적응한 것인지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u1-C9","difficulty":4,"kind":"essay","stem":"고산 기후 지역 사람들의 옷차림을 쓰고, 그 옷차림이 고산 기후의 어떤 특징에 적응한 것인지 쓰세요.","answer_guide":{"answer":"예: 챙이 넓고 둥근 모자를 쓰고, 옷을 여러 겹 입고 망토를 둘러요. 모자는 강한 햇빛을 막고, 여러 겹 옷과 망토는 낮과 밤의 기온 차이가 큰 기후에 적응하려는 것이에요.","scoring_points":["모자와 옷차림을 썼는가","강한 햇빛·큰 기온 차이를 썼는가","옷차림과 특징을 알맞게 이었는가"]},"explanation":["옷차림을 떠올려요.","고산 기후의 특징을 찾아요.","둘을 이어 써요."],"asset":{"type":"passage","lines":["분포 — 해발 고도가 높은 지역","적도 주변의 일부 고산 기후 지역 — 일 년 내내 서늘하여 사람이 많이 모여 삶","농업과 가축 — 감자, 옥수수 재배 · 알파카, 라마 기르기","옷 — 챙이 넓고 둥근 모자로 강한 햇빛을 막음,","　옷을 여러 겹 입고 망토를 둘러 낮과 밤의 큰 기온 차이에 적응"],"numbered":false,"title":"교과서 42쪽 고산 기후"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L09_challenge#10','soc',6,2,'u1','L09','tb_g6_2_soc_u1_L09_challenge','lesson_challenge','SO6-2-u1-C9',4,'essay','teacher','극지 과학자가 된다면 연구하고 싶은 것을 쓰고, 극지 연구가 오늘날 더 중요해진 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u1-C9","difficulty":4,"kind":"essay","stem":"극지 과학자가 된다면 연구하고 싶은 것을 쓰고, 극지 연구가 오늘날 더 중요해진 까닭을 쓰세요.","answer_guide":{"answer":"예: 남극의 빙하와 날씨가 해마다 어떻게 달라지는지 연구하고 싶어요. 전 세계적인 기후변화와 관련하여 극지의 중요성이 커지고 있어, 극지를 대상으로 한 과학 연구가 더욱 중요해졌기 때문이에요.","scoring_points":["연구하고 싶은 것을 썼는가","극지 과학자가 하는 일과 어울리는가","극지 연구가 중요한 까닭을 썼는가"]},"explanation":["극지 과학자가 하는 일을 떠올려요.","연구하고 싶은 것을 정해요.","중요한 까닭을 덧붙여요."],"asset":{"type":"passage","lines":["하는 일 — 극지방의 육지, 바다, 대기를 관측·분석하고,","　극지 동식물의 생태계 관리와 보전을 위한 연구를 해요.","필요한 것 — 환경과 지구의 미래에 관심을 두고 관련 책을 많이 읽기,","　극지 연구소의 보도 자료와 누리집 살펴보기","우리나라는 극지 연구를 위해 남극에 장보고 과학 기지를 세웠어요."],"numbered":false,"title":"교과서 43쪽 별별 직업 — 극지 과학자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L10_basic#1','soc',6,2,'u1','L10','tb_g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',1,'blank','auto','디지털 영상 지도에 필요한 정보를 원하는 위치에 배치하는 것을 (    )(이)라고 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-2-u1-X17']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C10","difficulty":1,"kind":"blank","stem":"디지털 영상 지도에 필요한 정보를 원하는 위치에 배치하는 것을 (    )(이)라고 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"매핑","correct":true},{"t":"검색","mis":"SO6-2-u1-X17"},{"t":"공유","mis":"SO6-2-u1-X17"},{"t":"레이어","mis":"SO6-2-u1-X17"}],"explanation":["교과서 45쪽 낱말 풀이예요.","정보를 지도 위 자리에 놓아요.","매핑이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L10_basic#2','soc',6,2,'u1','L10','tb_g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',1,'sa','auto','「세계 여러 나라 사람들은 기후에 (    )하고, 이를 극복하면서 다양한 모습으로 살아갑니다.」 빈칸에 알맞은 말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u1-C10","difficulty":1,"kind":"sa","stem":"「세계 여러 나라 사람들은 기후에 (    )하고, 이를 극복하면서 다양한 모습으로 살아갑니다.」 빈칸에 알맞은 말을 두 글자로 쓰세요.","answer":["적응"],"explanation":["꼭 기억해요 문장이에요.","기후에 맞추어 살아가요.","적응이에요."],"mis":"SO6-2-u1-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L10_basic#3','soc',6,2,'u1','L10','tb_g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',1,'mc','auto','교과서 44쪽에서 기후와 생활 모습에 관해 더 알고 싶은 주제로 친구들이 말한 것이 아닌 것은 무엇인가요?',ARRAY['SO6-2-u1-X02']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C10","difficulty":1,"kind":"mc","stem":"교과서 44쪽에서 기후와 생활 모습에 관해 더 알고 싶은 주제로 친구들이 말한 것이 아닌 것은 무엇인가요?","options":[{"t":"우리 반 친구들의 장래 희망","correct":true},{"t":"기후와 축제","mis":"SO6-2-u1-X02"},{"t":"기후와 전통 의상","mis":"SO6-2-u1-X02"},{"t":"기후가 만든 독특한 문화","mis":"SO6-2-u1-X02"}],"explanation":["친구들의 말을 떠올려요.","모두 기후와 이어진 주제예요.","장래 희망은 기후와 관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L10_basic#4','soc',6,2,'u1','L10','tb_g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',1,'ox','auto','기후는 사람들의 의식주와 하는 일 등 생활 모습에 큰 영향을 줘요.',ARRAY['SO6-2-u1-X02']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C10","difficulty":1,"kind":"ox","stem":"기후는 사람들의 의식주와 하는 일 등 생활 모습에 큰 영향을 줘요.","answer":"O","reason_options":[{"t":"기후 지역마다 집, 옷, 음식, 하는 일이 다르게 나타났기 때문에","correct":true},{"t":"기후와 생활은 서로 관계가 없기 때문에","mis":"SO6-2-u1-X02"}],"mis":"SO6-2-u1-X02","explanation":["기후마다 생활을 떠올려요.","집, 옷, 음식이 달랐어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L10_basic#5','soc',6,2,'u1','L10','tb_g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',2,'mc','auto','타이 송끄란 축제에서 사람들이 서로에게 물을 뿌리는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X12','SO6-2-u1-X11']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"mc","stem":"타이 송끄란 축제에서 사람들이 서로에게 물을 뿌리는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"비가 많이 내려 농사가 잘되기를 빌고 무더위를 잠시나마 없애려고","correct":true},{"t":"추운 겨울을 이겨 내려고","mis":"SO6-2-u1-X12"},{"t":"모래바람을 막으려고","mis":"SO6-2-u1-X12"},{"t":"물이 부족해 아껴 쓰려고","mis":"SO6-2-u1-X11"}],"explanation":["조사한 내용을 읽어요.","가장 더운 시기에 열려요.","비와 시원함을 바라는 뜻이에요."],"asset":{"type":"passage","lines":["우리 모둠 주제 — 기후와 축제 · 내가 조사할 지역 — 아시아 지역","송끄란 축제는 열대 기후인 타이에서 일 년 중 가장 더운 시기에 열린다.","비가 많이 내려 농사가 잘되기를 빌고 무더위를 잠시나마 없앤다는 뜻으로","서로에게 물을 뿌린다."],"title":"활동지 예시 — 조사한 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L10_basic#6','soc',6,2,'u1','L10','tb_g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',2,'mc','auto','모둠 주제에 관한 여러 사례를 조사할 때 조사 지역을 나누는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X15','SO6-2-u1-X17']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"mc","stem":"모둠 주제에 관한 여러 사례를 조사할 때 조사 지역을 나누는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"대륙별이나 기후별로 지역을 나누어 맡아요","correct":true},{"t":"모두 같은 나라 하나만 조사해요","mis":"SO6-2-u1-X15"},{"t":"우리나라만 조사해요","mis":"SO6-2-u1-X15"},{"t":"조사 지역은 정하지 않고 아무 데나 찾아요","mis":"SO6-2-u1-X17"}],"explanation":["한 지역에만 몰리지 않게 해요.","대륙이나 기후로 나눠요.","여러 곳의 사례가 모여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L10_basic#7','soc',6,2,'u1','L10','tb_g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',2,'mc','auto','디지털 영상 지도로 매핑할 때의 차례로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X17']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"mc","stem":"디지털 영상 지도로 매핑할 때의 차례로 알맞은 것은 무엇인가요?","options":[{"t":"「레이어 추가」 → 조사한 나라 검색 후 「지도에 추가」 → 기호로 자료 입력","correct":true},{"t":"기호로 자료 입력 → 「레이어 추가」 → 조사한 나라 검색","mis":"SO6-2-u1-X17"},{"t":"조사한 나라 검색 → 기호로 자료 입력 → 「레이어 추가」","mis":"SO6-2-u1-X17"},{"t":"「지도에 추가」 → 「레이어 추가」 → 기호로 자료 입력","mis":"SO6-2-u1-X17"}],"explanation":["먼저 내 레이어를 만들어요.","나라를 찾아 지도에 더해요.","마지막에 자료를 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L10_basic#8','soc',6,2,'u1','L10','tb_g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',2,'ox','auto','교과서 47쪽 문장 ㉥ 「대추야자는 온대 기후 지역에서 주로 기르는 식물입니다.」는 옳은 설명이에요.',ARRAY['SO6-2-u1-X12']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"ox","stem":"교과서 47쪽 문장 ㉥ 「대추야자는 온대 기후 지역에서 주로 기르는 식물입니다.」는 옳은 설명이에요.","answer":"X","reason_options":[{"t":"대추야자는 건조 기후 지역의 오아시스나 강 주변에서 재배하기 때문에","correct":true},{"t":"대추야자는 추운 곳에서만 자라기 때문에","mis":"SO6-2-u1-X12"}],"mis":"SO6-2-u1-X12","explanation":["대추야자를 떠올려요.","건조 기후의 오아시스 주변에서 길러요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉠ 지구는 둥글기 때문에 위도에 따라 햇볕을 받는 양이 다릅니다.","㉡ 냉대 기후는 일 년 내내 기온이 높고 기온 변화가 거의 없습니다.","㉢ 온대 기후는 겨울이 여름보다 길고 몹시 추우며 눈이 많이 옵니다.","㉣ 고산 기후는 해발 고도가 높은 산지 지역에 나타납니다.","㉤ 한대 기후 지역에서는 순록을 기르며 유목 생활을 합니다.","㉥ 대추야자는 온대 기후 지역에서 주로 기르는 식물입니다."],"numbered":false,"title":"교과서 47쪽 재미있게 확인해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L10_basic#9','soc',6,2,'u1','L10','tb_g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',2,'mc','auto','교과서 47쪽 여섯 문장 가운데 옳은 설명을 모두 바르게 고른 것은 무엇인가요?',ARRAY['SO6-2-u1-X13','SO6-2-u1-X12']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"mc","stem":"교과서 47쪽 여섯 문장 가운데 옳은 설명을 모두 바르게 고른 것은 무엇인가요?","options":[{"t":"㉠, ㉣, ㉤","correct":true},{"t":"㉠, ㉡, ㉢","mis":"SO6-2-u1-X13"},{"t":"㉡, ㉣, ㉥","mis":"SO6-2-u1-X12"},{"t":"㉢, ㉤, ㉥","mis":"SO6-2-u1-X13"}],"explanation":["문장을 하나씩 따져요.","㉡은 열대, ㉢은 냉대의 특징이에요.","옳은 것은 ㉠, ㉣, ㉤이에요."],"asset":{"type":"passage","lines":["㉠ 지구는 둥글기 때문에 위도에 따라 햇볕을 받는 양이 다릅니다.","㉡ 냉대 기후는 일 년 내내 기온이 높고 기온 변화가 거의 없습니다.","㉢ 온대 기후는 겨울이 여름보다 길고 몹시 추우며 눈이 많이 옵니다.","㉣ 고산 기후는 해발 고도가 높은 산지 지역에 나타납니다.","㉤ 한대 기후 지역에서는 순록을 기르며 유목 생활을 합니다.","㉥ 대추야자는 온대 기후 지역에서 주로 기르는 식물입니다."],"numbered":false,"title":"교과서 47쪽 재미있게 확인해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L10_basic#10','soc',6,2,'u1','L10','tb_g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',3,'error','auto','디지털 영상 지도로 조사 내용을 나누며 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.',ARRAY['SO6-2-u1-X17']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C10","difficulty":3,"kind":"error","stem":"디지털 영상 지도로 조사 내용을 나누며 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.","options":[{"t":"친구 다 — 「지도는 혼자 볼 거니까 모둠 친구들과 공유하지 않아도 돼.」","correct":true,"mis_target":"SO6-2-u1-X17"},{"t":"친구 가 — 「조사한 정보를 지도 위에 놓으면 나라의 위치까지 한눈에 볼 수 있어.」","mis":"SO6-2-u1-X17"},{"t":"친구 나 — 「다른 모둠의 지도를 보고 더 알아보고 싶은 내용을 써 보자.」","mis":"SO6-2-u1-X17"}],"explanation":["매핑의 좋은 점을 떠올려요.","지도 주소를 공유해 함께 봐요.","친구 다의 말이 알맞지 않아요."],"asset":{"type":"passage","lines":["매핑 — 디지털 영상 지도에 필요한 정보를 원하는 위치에 배치하는 것","준비 ① 디지털 영상 지도 누리집 실행 ② 「지도 만들기」 ③ 제목·설명 쓰고 「공유」","매핑 ① 「레이어 추가」 ② 조사한 나라 검색 후 「지도에 추가」 ③ 기호로 자료 입력","마지막 — 모둠 지도 주소를 다른 모둠과 공유하고 더 알아보고 싶은 내용 쓰기"],"title":"교과서 45~46쪽 디지털 영상 지도로 매핑하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L10_challenge#1','soc',6,2,'u1','L10','tb_g6_2_soc_u1_L10_challenge','lesson_challenge','SO6-2-u1-C10',2,'mc','auto','상품 판매 계획을 세우는 차례로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X17']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"mc","stem":"상품 판매 계획을 세우는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"판매할 나라 정하기 → 지형과 기후 조사하기 → 상품 아이디어 이야기하기 → 글과 그림으로 나타내기","correct":true},{"t":"글과 그림으로 나타내기 → 판매할 나라 정하기 → 상품 아이디어 이야기하기 → 지형과 기후 조사하기","mis":"SO6-2-u1-X17"},{"t":"상품 아이디어 이야기하기 → 글과 그림으로 나타내기 → 지형과 기후 조사하기 → 판매할 나라 정하기","mis":"SO6-2-u1-X17"},{"t":"지형과 기후 조사하기 → 글과 그림으로 나타내기 → 판매할 나라 정하기 → 상품 아이디어 이야기하기","mis":"SO6-2-u1-X17"}],"explanation":["먼저 나라를 정해요.","그 나라의 자연환경을 조사해요.","아이디어를 나누고 글과 그림으로 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L10_challenge#2','soc',6,2,'u1','L10','tb_g6_2_soc_u1_L10_challenge','lesson_challenge','SO6-2-u1-C10',2,'sa','auto','브라질 상품 판매 계획에서 판매하려는 상품의 종류를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"sa","stem":"브라질 상품 판매 계획에서 판매하려는 상품의 종류를 쓰세요.","answer":["해충 퇴치기","해충퇴치기"],"explanation":["상품 칸을 읽어요.","해충이 가까이 오지 못하게 해요.","해충 퇴치기예요."],"asset":{"type":"passage","lines":["판매할 나라 — 브라질","특징(기후) — 일 년 내내 기온이 높고 기온 변화가 거의 없으며","　강수량이 많아 열대 우림이 펼쳐져 있어요.","판매 동기 — 이 지역에는 사람들에게 각종 전염병을 옮기는 해충이 많아요.","상품 — 해충 퇴치기","특징 — 목에 걸어 휴대하기 편리, 태양열로 자동 충전,","　인체에 해가 없는 초음파로 해충이 가까이 오지 못하게 함"],"numbered":false,"title":"상품 판매 계획 예시"},"mis":"SO6-2-u1-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L10_challenge#3','soc',6,2,'u1','L10','tb_g6_2_soc_u1_L10_challenge','lesson_challenge','SO6-2-u1-C10',3,'mc','auto','노르웨이를 조사한 예시를 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X19','SO6-2-u1-X01','SO6-2-u1-X16']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C10","difficulty":3,"kind":"mc","stem":"노르웨이를 조사한 예시를 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"한 나라 안에서도 지역에 따라 다양한 기후가 나타나요","correct":true},{"t":"한 나라에는 한 가지 기후만 나타나요","mis":"SO6-2-u1-X19"},{"t":"노르웨이에는 산지가 없어요","mis":"SO6-2-u1-X01"},{"t":"상품을 정할 때 지형과 기후는 조사할 필요가 없어요","mis":"SO6-2-u1-X16"}],"explanation":["기후 칸을 읽어요.","온대, 냉대, 한대 기후가 나타나요.","한 나라에도 여러 기후가 있어요."],"asset":{"type":"passage","lines":["선택한 나라 — 노르웨이","지형 — 송네 피오르, 스칸디나비아산맥","기후 — 온대 기후, 냉대 기후, 한대 기후","특징 — 해안과 산지 등 다양한 지형이 있고, 지역에 따라 다양한 기후가 나타나요."],"title":"교과서 48쪽 선택한 나라 조사 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L10_challenge#4','soc',6,2,'u1','L10','tb_g6_2_soc_u1_L10_challenge','lesson_challenge','SO6-2-u1-C10',3,'mc','auto','노르웨이 상품 판매 계획에서 방한용 안전 신발 바닥에 스파이크를 단 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X16']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C10","difficulty":3,"kind":"mc","stem":"노르웨이 상품 판매 계획에서 방한용 안전 신발 바닥에 스파이크를 단 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"겨울이 길고 눈이 많이 내려 얼음 위에서 미끄러지기 쉽기 때문이에요","correct":true},{"t":"일 년 내내 덥고 습해 발에 땀이 많이 나기 때문이에요","mis":"SO6-2-u1-X16"},{"t":"비가 거의 오지 않아 땅이 갈라지기 때문이에요","mis":"SO6-2-u1-X16"},{"t":"해충이 많아 물리기 쉽기 때문이에요","mis":"SO6-2-u1-X16"}],"explanation":["판매 동기를 읽어요.","냉대 기후는 겨울이 길고 눈이 많아요.","얼음 위에서도 미끄러지지 않게 했어요."],"asset":{"type":"passage","lines":["판매할 나라 — 노르웨이","특징(기후) — 냉대 기후가 나타나 겨울이 여름보다 길고 몹시 추우며 눈이 많이 와요.","판매 동기 — 겨울이 길고 눈이 많이 내려 이동할 때 불편해요.","상품 — 방한용 안전 신발","특징 — 바닥의 스파이크로 얼음 위에서도 미끄러지지 않음,","　스키를 붙여 눈에서 편리하게 이동, 태양열로 충전되는 열선으로 발을 따뜻하게"],"numbered":false,"title":"교과서 49쪽 상품 판매 계획 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L10_challenge#5','soc',6,2,'u1','L10','tb_g6_2_soc_u1_L10_challenge','lesson_challenge','SO6-2-u1-C10',3,'ox','auto','브라질 상품 판매 계획의 해충 퇴치기는 열대 우림이 펼쳐진 지역의 자연환경을 고려한 상품이에요.',ARRAY['SO6-2-u1-X16']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C10","difficulty":3,"kind":"ox","stem":"브라질 상품 판매 계획의 해충 퇴치기는 열대 우림이 펼쳐진 지역의 자연환경을 고려한 상품이에요.","answer":"O","reason_options":[{"t":"일 년 내내 기온이 높고 강수량이 많은 열대 우림 지역에 전염병을 옮기는 해충이 많아 이를 막으려는 상품이기 때문에","correct":true},{"t":"상품은 자연환경과 관계없이 어디서나 똑같이 쓰이기 때문에","mis":"SO6-2-u1-X16"}],"mis":"SO6-2-u1-X16","explanation":["판매 동기를 읽어요.","열대 우림 지역에는 해충이 많아요.","그래서 O예요."],"asset":{"type":"passage","lines":["판매할 나라 — 브라질","특징(기후) — 일 년 내내 기온이 높고 기온 변화가 거의 없으며","　강수량이 많아 열대 우림이 펼쳐져 있어요.","판매 동기 — 이 지역에는 사람들에게 각종 전염병을 옮기는 해충이 많아요.","상품 — 해충 퇴치기","특징 — 목에 걸어 휴대하기 편리, 태양열로 자동 충전,","　인체에 해가 없는 초음파로 해충이 가까이 오지 못하게 함"],"numbered":false,"title":"상품 판매 계획 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L10_challenge#6','soc',6,2,'u1','L10','tb_g6_2_soc_u1_L10_challenge','lesson_challenge','SO6-2-u1-C10',3,'mc','auto','친구들의 상품 아이디어 가운데 「물살이 빠른 하천」이라는 자연환경을 가장 잘 고려한 것은 무엇인가요?',ARRAY['SO6-2-u1-X16']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C10","difficulty":3,"kind":"mc","stem":"친구들의 상품 아이디어 가운데 「물살이 빠른 하천」이라는 자연환경을 가장 잘 고려한 것은 무엇인가요?","options":[{"t":"콩고강에서 물고기를 잡는 사람들을 위한 튼튼한 어망","correct":true},{"t":"셰르파를 위한 만능 등산 장비","mis":"SO6-2-u1-X16"},{"t":"냉대 기후 지역 사람들을 위한 다기능 신발","mis":"SO6-2-u1-X16"},{"t":"어느 나라에서나 똑같이 쓰는 평범한 연필","mis":"SO6-2-u1-X16"}],"explanation":["하천과 관계있는 아이디어를 찾아요.","콩고강은 물살이 빨라요.","튼튼한 어망이 필요해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"콩고강에서 물고기를 잡는 사람들에게 튼튼한 어망이 필요할 것 같아."},{"who":"친구 2","text":"네팔의 히말라야산맥을 오르는 셰르파를 위한 만능 등산 장비를 만들면 좋을 것 같아."},{"who":"친구 3","text":"노르웨이의 냉대 기후 지역에 사는 사람들이 사용할 수 있는 다기능 신발을 만들고 싶어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L10_challenge#7','soc',6,2,'u1','L10','tb_g6_2_soc_u1_L10_challenge','lesson_challenge','SO6-2-u1-C10',3,'error','auto','상품을 구상하며 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.',ARRAY['SO6-2-u1-X16']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C10","difficulty":3,"kind":"error","stem":"상품을 구상하며 친구들이 한 말 가운데 알맞지 않은 것을 고르세요.","options":[{"t":"친구 다 — 「실제로 만들 수 있는지는 생각하지 않아도 돼. 신기하기만 하면 돼.」","correct":true,"mis_target":"SO6-2-u1-X16"},{"t":"친구 가 — 「그 나라의 지형과 기후 특징을 먼저 조사하자.」","mis":"SO6-2-u1-X16"},{"t":"친구 나 — 「그곳 사람들이 겪는 불편을 판매 동기로 쓰자.」","mis":"SO6-2-u1-X16"}],"explanation":["좋은 상품 계획을 떠올려요.","실제로 만들 수 있는지도 생각해요.","친구 다의 말이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L10_challenge#8','soc',6,2,'u1','L10','tb_g6_2_soc_u1_L10_challenge','lesson_challenge','SO6-2-u1-C10',4,'mc','auto','사막에서 모래 썰매를 타고 흙벽돌집을 체험할 수 있는 나라에 상품을 판다면, 기후를 가장 잘 고려한 상품은 무엇인가요?',ARRAY['SO6-2-u1-X16','SO6-2-u1-X12']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C10","difficulty":4,"kind":"mc","stem":"사막에서 모래 썰매를 타고 흙벽돌집을 체험할 수 있는 나라에 상품을 판다면, 기후를 가장 잘 고려한 상품은 무엇인가요?","options":[{"t":"강한 햇볕과 모래바람을 막아 주는 가볍고 온몸을 감싸는 옷","correct":true},{"t":"얼음 위를 걷는 스파이크 신발","mis":"SO6-2-u1-X16"},{"t":"바닥을 띄운 열대 우림용 텐트","mis":"SO6-2-u1-X12"},{"t":"얼음 축제용 털모자","mis":"SO6-2-u1-X16"}],"explanation":["사막은 건조 기후예요.","햇볕이 강하고 모래바람이 불어요.","그것을 막아 주는 상품이 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L10_challenge#9','soc',6,2,'u1','L10','tb_g6_2_soc_u1_L10_challenge','lesson_challenge','SO6-2-u1-C10',4,'essay','teacher','세계 여러 나라 가운데 한 나라를 골라 상품 판매 계획을 세워 보세요. 판매할 나라, 지형이나 기후의 특징, 판매 동기, 상품의 종류와 특징을 차례로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u1-C10","difficulty":4,"kind":"essay","stem":"세계 여러 나라 가운데 한 나라를 골라 상품 판매 계획을 세워 보세요. 판매할 나라, 지형이나 기후의 특징, 판매 동기, 상품의 종류와 특징을 차례로 쓰세요.","answer_guide":{"answer":"예: 판매할 나라 — 에콰도르. 기후 특징 — 키토처럼 해발 고도가 높은 곳은 고산 기후가 나타나 일 년 내내 서늘하고 낮과 밤의 기온 차이가 커요. 판매 동기 — 낮에는 햇빛이 강하고 밤에는 추워 옷을 자주 갈아입어야 해서 불편해요. 상품 — 챙 넓은 모자가 달린 접이식 망토. 특징 — 낮에는 챙으로 햇빛을 막고, 밤에는 망토를 펼쳐 몸을 따뜻하게 감싸요.","scoring_points":["나라와 자연환경의 특징을 바르게 썼는가","자연환경에서 오는 불편을 판매 동기로 썼는가","상품의 특징에 자연환경을 고려했는가"]},"explanation":["나라를 정해요.","지형이나 기후 특징에서 불편을 찾아요.","불편을 덜어 줄 상품을 그려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_L10_challenge#10','soc',6,2,'u1','L10','tb_g6_2_soc_u1_L10_challenge','lesson_challenge','SO6-2-u1-C10',4,'essay','teacher','기후와 생활 모습에 관해 모둠에서 조사하고 싶은 주제를 하나 정하고, 조사할 내용과 조사한 정보를 친구들과 나눌 방법을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u1-C10","difficulty":4,"kind":"essay","stem":"기후와 생활 모습에 관해 모둠에서 조사하고 싶은 주제를 하나 정하고, 조사할 내용과 조사한 정보를 친구들과 나눌 방법을 쓰세요.","answer_guide":{"answer":"예: 주제 — 기후와 축제. 조사할 내용 — 기후와 관련 있는 세계 여러 나라의 축제(타이 송끄란 축제처럼 기후 때문에 생긴 축제). 나눌 방법 — 조사한 축제를 디지털 영상 지도에 매핑하고, 지도 주소를 다른 모둠과 공유해요.","scoring_points":["기후와 관계있는 주제를 정했는가","조사할 내용을 구체적으로 썼는가","매핑이나 공유 같은 나눌 방법을 썼는가"]},"explanation":["기후와 이어진 주제를 골라요.","조사할 내용을 정해요.","지도에 매핑해 나눠요."],"asset":{"type":"passage","lines":["매핑 — 디지털 영상 지도에 필요한 정보를 원하는 위치에 배치하는 것","준비 ① 디지털 영상 지도 누리집 실행 ② 「지도 만들기」 ③ 제목·설명 쓰고 「공유」","매핑 ① 「레이어 추가」 ② 조사한 나라 검색 후 「지도에 추가」 ③ 기호로 자료 입력","마지막 — 모둠 지도 주소를 다른 모둠과 공유하고 더 알아보고 싶은 내용 쓰기"],"title":"교과서 45~46쪽 디지털 영상 지도로 매핑하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_a#1','soc',6,2,'u1','','tb_g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C1',1,'sa','auto','「세계에는 산지, 하천, 해안 등 다양한 (    )이/가 있습니다. 우리는 세계의 다양한 지역에서 독특하고 아름다운 (    ) 경관을 볼 수 있습니다.」 빈칸에 공통으로 들어갈 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u1-C1","difficulty":1,"kind":"sa","stem":"「세계에는 산지, 하천, 해안 등 다양한 (    )이/가 있습니다. 우리는 세계의 다양한 지역에서 독특하고 아름다운 (    ) 경관을 볼 수 있습니다.」 빈칸에 공통으로 들어갈 알맞은 말을 쓰세요.","answer":["지형"],"explanation":["산지, 하천, 해안을 함께 부르는 말이에요.","땅의 모양을 뜻해요.","지형이에요."],"mis":"SO6-2-u1-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_a#2','soc',6,2,'u1','','tb_g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C2',1,'mc','auto','산지 지형의 특징을 알맞게 말한 사람을 모두 고른 것은 무엇인가요?',ARRAY['SO6-2-u1-X04']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C2","difficulty":1,"kind":"mc","stem":"산지 지형의 특징을 알맞게 말한 사람을 모두 고른 것은 무엇인가요?","options":[{"t":"영원, 승기","correct":true},{"t":"정원, 현수","mis":"SO6-2-u1-X04"},{"t":"서연, 영원","mis":"SO6-2-u1-X04"},{"t":"현수, 승기","mis":"SO6-2-u1-X04"}],"explanation":["산지는 해발 고도가 높고 대체로 경사가 급해요.","모든 산이 뾰족한 것은 아니에요.","영원과 승기가 알맞게 말했어요."],"asset":{"type":"speech","turns":[{"who":"정원","text":"해발 고도가 대체로 낮아."},{"who":"현수","text":"산지 지형은 대체로 경사가 완만해."},{"who":"서연","text":"모든 산은 정상이 뾰족하게 생겼어."},{"who":"영원","text":"고원처럼 비교적 넓고 평평한 곳도 있어."},{"who":"승기","text":"산 정상이 움푹 파이거나 물이 고여 있는 화산도 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_a#3','soc',6,2,'u1','','tb_g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C2',1,'mc','auto','산지 지형에서 볼 수 있는 생활 모습으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO6-2-u1-X04','SO6-2-u1-X20','SO6-2-u1-X02']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C2","difficulty":1,"kind":"mc","stem":"산지 지형에서 볼 수 있는 생활 모습으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"경사가 급해 관광지로 이용하지 못해요","correct":true},{"t":"화산 주변에는 온천이 발달해요","mis":"SO6-2-u1-X04"},{"t":"가파른 경사지를 이용해 계단식 농사를 지어요","mis":"SO6-2-u1-X20"},{"t":"지하자원이 풍부한 곳에서는 광업이 발달하기도 해요","mis":"SO6-2-u1-X02"},{"t":"비교적 평탄하고 풀이 잘 자라는 곳에서는 가축을 기르기도 해요","mis":"SO6-2-u1-X04"}],"explanation":["산지의 이용을 하나씩 떠올려요.","아름다운 산지는 스키장, 휴양림이 돼요.","관광지로 이용하지 못한다는 말이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_a#4','soc',6,2,'u1','','tb_g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C3',1,'sa','auto','「크고 작은 강, 거대한 폭포, 넓은 평야, 험준한 계곡」 — 이 지형 경관을 볼 수 있는 지형을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SO6-2-u1-C3","difficulty":1,"kind":"sa","stem":"「크고 작은 강, 거대한 폭포, 넓은 평야, 험준한 계곡」 — 이 지형 경관을 볼 수 있는 지형을 쓰세요.","answer":["하천 지형","하천"],"explanation":["강, 폭포, 평야, 계곡을 떠올려요.","모두 강을 따라 나타나요.","하천 지형이에요."],"mis":"SO6-2-u1-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_a#5','soc',6,2,'u1','','tb_g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C3',1,'mc','auto','세계의 하천 지형에서 볼 수 있는 모습으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO6-2-u1-X05','SO6-2-u1-X03']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C3","difficulty":1,"kind":"mc","stem":"세계의 하천 지형에서 볼 수 있는 모습으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"물살이 빨라 어업이 이루어질 수 없어요","correct":true},{"t":"물을 이용해 전기를 만들어요","mis":"SO6-2-u1-X05"},{"t":"강을 따라 시장이 형성되기도 해요","mis":"SO6-2-u1-X05"},{"t":"강, 폭포, 계곡, 평야 등의 지형을 볼 수 있어요","mis":"SO6-2-u1-X03"},{"t":"하천 주변의 넓은 평야에서는 비행기 등을 활용해 농사를 짓기도 해요","mis":"SO6-2-u1-X05"}],"explanation":["하천의 생활을 하나씩 떠올려요.","하천에서는 수산 자원으로 어업이 활발해요.","어업이 이루어질 수 없다는 말이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_a#6','soc',6,2,'u1','','tb_g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C4',1,'mc','auto','마케나 모래사장(미국)과 포트 캠벨 국립 공원(오스트레일리아)의 지형 경관을 볼 수 있는 지형은 무엇인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C4","difficulty":1,"kind":"mc","stem":"마케나 모래사장(미국)과 포트 캠벨 국립 공원(오스트레일리아)의 지형 경관을 볼 수 있는 지형은 무엇인가요?","options":[{"t":"해안 지형","correct":true},{"t":"하천 지형","mis":"SO6-2-u1-X03"},{"t":"산지 지형","mis":"SO6-2-u1-X03"},{"t":"사막 지형","mis":"SO6-2-u1-X03"},{"t":"빙하 지형","mis":"SO6-2-u1-X03"}],"explanation":["모래사장과 절벽, 돌기둥을 떠올려요.","바다와 육지가 만나는 곳이에요.","해안 지형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_a#7','soc',6,2,'u1','','tb_g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C4',1,'mc','auto','해안 지형에서 볼 수 있는 모습으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO6-2-u1-X06']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C4","difficulty":1,"kind":"mc","stem":"해안 지형에서 볼 수 있는 모습으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"스키장","correct":true},{"t":"항구","mis":"SO6-2-u1-X06"},{"t":"염전","mis":"SO6-2-u1-X06"},{"t":"양식장","mis":"SO6-2-u1-X06"},{"t":"해수욕장","mis":"SO6-2-u1-X06"}],"explanation":["해안의 이용을 떠올려요.","항구, 염전, 양식장, 해수욕장이 있어요.","스키장은 주로 산지 지형에서 볼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_a#8','soc',6,2,'u1','','tb_g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C1',1,'match','auto','세계의 지형과 각각의 지형에서 볼 수 있는 지형 경관을 바르게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u1-C1","difficulty":1,"kind":"match","stem":"세계의 지형과 각각의 지형에서 볼 수 있는 지형 경관을 바르게 이으세요.","pairs":[{"l":"산지","r":"화산"},{"l":"하천","r":"계곡"},{"l":"해안","r":"갯벌"}],"mis":"SO6-2-u1-X03","explanation":["지형마다 경관을 떠올려요.","산지에는 산맥·고원·화산이 있어요.","하천은 계곡, 해안은 갯벌이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_a#9','soc',6,2,'u1','','tb_g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C5',2,'sa','auto','「(    )과/와 기후 — 지구는 둥글기 때문에 (    )에 따라 햇볕을 받는 양이 다릅니다. 대체로 적도 지방에서 극지방으로 갈수록 기온은 점차 낮아집니다.」 빈칸에 공통으로 들어갈 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"sa","stem":"「(    )과/와 기후 — 지구는 둥글기 때문에 (    )에 따라 햇볕을 받는 양이 다릅니다. 대체로 적도 지방에서 극지방으로 갈수록 기온은 점차 낮아집니다.」 빈칸에 공통으로 들어갈 알맞은 말을 쓰세요.","answer":["위도"],"explanation":["햇볕을 받는 양이 달라지는 까닭이에요.","적도에서 극지방으로 갈수록 달라져요.","위도예요."],"mis":"SO6-2-u1-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_a#10','soc',6,2,'u1','','tb_g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C5',2,'sa','auto','세계의 기후 분포를 나타낸 지도처럼 세계의 기후를 구분하는 기준 두 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"sa","stem":"세계의 기후 분포를 나타낸 지도처럼 세계의 기후를 구분하는 기준 두 가지를 쓰세요.","answer":["기온, 강수량","기온과 강수량","강수량, 기온","강수량과 기온","기온,강수량"],"explanation":["기후를 나누는 기준이에요.","덥고 추운 정도와 비가 오는 양이에요.","기온과 강수량이에요."],"mis":"SO6-2-u1-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_a#11','soc',6,2,'u1','','tb_g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C6',2,'mc','auto','쿠알라룸푸르(말레이시아)의 기후 그래프는 선(기온)이 일 년 내내 높고 거의 평평하며 막대(강수량)가 열두 달 모두 높아요. 이 그래프가 나타나는 지역의 기호를 고르세요.',ARRAY['SO6-2-u1-X10','SO6-2-u1-X11','SO6-2-u1-X13','SO6-2-u1-X15']::text[],false,'{"seq":11,"concept":"SO6-2-u1-C6","difficulty":2,"kind":"mc","stem":"쿠알라룸푸르(말레이시아)의 기후 그래프는 선(기온)이 일 년 내내 높고 거의 평평하며 막대(강수량)가 열두 달 모두 높아요. 이 그래프가 나타나는 지역의 기호를 고르세요.","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"SO6-2-u1-X10"},{"t":"㉡","mis":"SO6-2-u1-X11"},{"t":"㉣","mis":"SO6-2-u1-X13"},{"t":"㉤","mis":"SO6-2-u1-X15"}],"explanation":["일 년 내내 덥고 비가 많아요.","열대 기후예요.","적도 부근 동남아시아의 ㉢이에요."],"asset":{"type":"passage","lines":["㉠ 유럽의 서쪽","㉡ 아프리카의 서쪽","㉢ 동남아시아의 적도 부근","㉣ 아시아의 북동쪽","㉤ 남아메리카의 동쪽"],"numbered":false,"title":"세계의 기후 분포도에 표시한 기호의 자리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_a#12','soc',6,2,'u1','','tb_g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C5',2,'mc','auto','세계의 기후를 적도 지방에서 극지방 순으로 알맞게 나열한 것은 무엇인가요?',ARRAY['SO6-2-u1-X10']::text[],false,'{"seq":12,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"mc","stem":"세계의 기후를 적도 지방에서 극지방 순으로 알맞게 나열한 것은 무엇인가요?","options":[{"t":"열대 – 건조 – 온대 – 냉대 – 한대","correct":true},{"t":"온대 – 열대 – 냉대 – 한대 – 건조","mis":"SO6-2-u1-X10"},{"t":"건조 – 냉대 – 한대 – 열대 – 온대","mis":"SO6-2-u1-X10"},{"t":"한대 – 냉대 – 온대 – 건조 – 열대","mis":"SO6-2-u1-X10"},{"t":"열대 – 온대 – 건조 – 한대 – 냉대","mis":"SO6-2-u1-X10"}],"explanation":["적도에서 출발해요.","열대, 건조, 온대 차례예요.","냉대를 지나 한대예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_a#13','soc',6,2,'u1','','tb_g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C7',2,'sa','auto','「1일 차 — 사막에서 모래 썰매 타기, 흙벽돌집 체험하기 · 2일 차 — 초원에서 캠핑하기, 양 먹이 주기」 여행 지역에 나타나는 기후를 쓰세요.','{}'::text[],false,'{"seq":13,"concept":"SO6-2-u1-C7","difficulty":2,"kind":"sa","stem":"「1일 차 — 사막에서 모래 썰매 타기, 흙벽돌집 체험하기 · 2일 차 — 초원에서 캠핑하기, 양 먹이 주기」 여행 지역에 나타나는 기후를 쓰세요.","answer":["건조 기후","건조"],"explanation":["사막과 초원이 나와요.","흙벽돌집도 있어요.","건조 기후예요."],"mis":"SO6-2-u1-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_a#14','soc',6,2,'u1','','tb_g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C8',2,'mc','auto','온대 기후 지역의 생활 모습으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X14','SO6-2-u1-X13','SO6-2-u1-X12']::text[],false,'{"seq":14,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"mc","stem":"온대 기후 지역의 생활 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"밀을 많이 재배하고 낙농업이 발달했어요","correct":true},{"t":"오로라와 빙하 등을 이용한 관광 산업이 발달했어요","mis":"SO6-2-u1-X14"},{"t":"화전 농업을 통해 카사바, 얌, 옥수수 등을 재배해요","mis":"SO6-2-u1-X13"},{"t":"침엽수림이 넓게 발달하여 목재와 펄프 생산이 활발해요","mis":"SO6-2-u1-X13"},{"t":"강한 햇볕과 모래바람을 막으려고 온몸을 감싸는 옷을 입어요","mis":"SO6-2-u1-X12"}],"explanation":["보기를 기후별로 나눠요.","오로라는 한대, 화전은 열대, 침엽수림은 냉대, 온몸 옷은 건조예요.","밀과 낙농업이 온대예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_a#15','soc',6,2,'u1','','tb_g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C8',2,'mc','auto','그림 속 모습을 볼 수 있는 기후는 무엇인가요?',ARRAY['SO6-2-u1-X13','SO6-2-u1-X12','SO6-2-u1-X14']::text[],false,'{"seq":15,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"mc","stem":"그림 속 모습을 볼 수 있는 기후는 무엇인가요?","options":[{"t":"냉대 기후","correct":true},{"t":"열대 기후","mis":"SO6-2-u1-X13"},{"t":"건조 기후","mis":"SO6-2-u1-X12"},{"t":"온대 기후","mis":"SO6-2-u1-X13"},{"t":"고산 기후","mis":"SO6-2-u1-X14"}],"explanation":["잎이 가늘고 뾰족한 나무는 침엽수예요.","통나무집과 눈도 있어요.","냉대 기후예요."],"asset":{"type":"passage","lines":["숲에서 잎이 가늘고 뾰족한 나무를 베어 통나무로 나르는 사람들","눈이 쌓인 땅 옆에 통나무로 지은 집"],"title":"그림 속 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_a#16','soc',6,2,'u1','','tb_g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C6',2,'sa','auto','상품 판매 계획을 보고, 이 상품을 판매하려는 지역에 나타나는 기후를 쓰세요.','{}'::text[],false,'{"seq":16,"concept":"SO6-2-u1-C6","difficulty":2,"kind":"sa","stem":"상품 판매 계획을 보고, 이 상품을 판매하려는 지역에 나타나는 기후를 쓰세요.","answer":["열대 기후","열대"],"explanation":["일 년 내내 기온이 높고 비가 많아요.","열대 우림이 펼쳐져 있어요.","열대 기후예요."],"asset":{"type":"passage","lines":["판매할 나라 — 브라질","특징(기후) — 일 년 내내 기온이 높고 기온 변화가 거의 없으며","　강수량이 많아 열대 우림이 펼쳐져 있어요.","판매 동기 — 이 지역에는 사람들에게 각종 전염병을 옮기는 해충이 많아요.","상품 — 해충 퇴치기","특징 — 목에 걸어 휴대하기 편리, 태양열로 자동 충전,","　인체에 해가 없는 초음파로 해충이 가까이 오지 못하게 함"],"numbered":false,"title":"상품 판매 계획 예시"},"mis":"SO6-2-u1-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_a#17','soc',6,2,'u1','','tb_g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C3',3,'essay','teacher','사진에는 많은 물이 높은 절벽 아래로 떨어지는 하천 지형과, 그 앞 다리 위에 모인 많은 관광객이 보여요. ⑴ 사진에서 볼 수 있는 지형의 이름을 쓰고, ⑵ 이런 하천 지형이 관광지로 발달한 까닭을 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"SO6-2-u1-C3","difficulty":3,"kind":"essay","stem":"사진에는 많은 물이 높은 절벽 아래로 떨어지는 하천 지형과, 그 앞 다리 위에 모인 많은 관광객이 보여요. ⑴ 사진에서 볼 수 있는 지형의 이름을 쓰고, ⑵ 이런 하천 지형이 관광지로 발달한 까닭을 쓰세요.","answer_guide":{"answer":"예: ⑴ 폭포 ⑵ 웅장한 지형 경관을 보려고 많은 관광객이 찾아오기 때문이에요. 매력적인 지형 경관이 나타나기 때문이에요.","scoring_points":["⑴ 폭포를 썼는가","⑵ 웅장하거나 매력적인 지형 경관을 까닭으로 썼는가","관광객이 찾아온다는 점을 이었는가"]},"explanation":["물이 절벽 아래로 떨어져요.","폭포예요.","웅장한 경관을 보러 관광객이 와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_a#18','soc',6,2,'u1','','tb_g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C4',3,'essay','teacher','관광지로 이용하는 세계의 아름다운 지형 경관을 지키기 위한 노력을 두 가지 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"SO6-2-u1-C4","difficulty":3,"kind":"essay","stem":"관광지로 이용하는 세계의 아름다운 지형 경관을 지키기 위한 노력을 두 가지 쓰세요.","answer_guide":{"answer":"예: 쓰레기를 버리지 않아요. 지나친 개발을 하지 않아요. 관광객의 수를 제한해요.","scoring_points":["노력을 두 가지 썼는가","지형 경관을 지키는 데 알맞은가","실천할 수 있는 노력인가"]},"explanation":["관광지에서 생긴 문제를 떠올려요.","쓰레기와 지나친 개발이에요.","그것을 줄이는 노력을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_a#19','soc',6,2,'u1','','tb_g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C9',3,'essay','teacher','극지방을 중심으로 색칠된 지도 속 지역을 여행할 때, 이 지역의 기후와 관련하여 필요한 준비물을 두 가지 쓰고 그렇게 적은 까닭을 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"essay","stem":"극지방을 중심으로 색칠된 지도 속 지역을 여행할 때, 이 지역의 기후와 관련하여 필요한 준비물을 두 가지 쓰고 그렇게 적은 까닭을 쓰세요.","answer_guide":{"answer":"예: 준비물 — 털모자, 장갑. 까닭 — 겨울이 길고 기온이 매우 낮기 때문이에요.","scoring_points":["준비물을 두 가지 썼는가","추위를 막는 준비물인가","한대 기후의 특징을 까닭으로 썼는가"]},"explanation":["극지방은 한대 기후예요.","겨울이 길고 기온이 매우 낮아요.","추위를 막을 준비물을 챙겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_a#20','soc',6,2,'u1','','tb_g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C9',3,'essay','teacher','알파카나 라마로 보이는 동물 옆에 선 사람이 챙이 있는 둥근 모자를 쓰고, 여러 겹 옷 위에 망토를 두르고 있어요. ⑴ 이런 전통 의상을 볼 수 있는 기후 지역을 쓰고, ⑵ 이러한 의상을 입는 까닭을 쓰세요.','{}'::text[],false,'{"seq":20,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"essay","stem":"알파카나 라마로 보이는 동물 옆에 선 사람이 챙이 있는 둥근 모자를 쓰고, 여러 겹 옷 위에 망토를 두르고 있어요. ⑴ 이런 전통 의상을 볼 수 있는 기후 지역을 쓰고, ⑵ 이러한 의상을 입는 까닭을 쓰세요.","answer_guide":{"answer":"예: ⑴ 고산 기후 ⑵ 강한 햇빛을 막고, 낮과 밤의 기온 차이가 큰 기후에 적응하기 위해서예요.","scoring_points":["⑴ 고산 기후를 썼는가","⑵ 강한 햇빛을 막는다는 점을 썼는가","⑵ 큰 기온 차이에 적응한다는 점을 썼는가"]},"explanation":["알파카와 라마를 떠올려요.","고산 기후예요.","모자와 망토는 햇빛과 기온 차이 때문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_a#21','soc',6,2,'u1','','tb_g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C5',3,'mc','auto','세계 여행 박람회에서 친구 ❶이 가고 싶어 하는 나라로 알맞은 곳은 어디인가요?',ARRAY['SO6-2-u1-X02']::text[],false,'{"seq":21,"concept":"SO6-2-u1-C5","difficulty":3,"kind":"mc","stem":"세계 여행 박람회에서 친구 ❶이 가고 싶어 하는 나라로 알맞은 곳은 어디인가요?","options":[{"t":"모로코","correct":true},{"t":"캐나다","mis":"SO6-2-u1-X02"},{"t":"브라질","mis":"SO6-2-u1-X02"},{"t":"네팔","mis":"SO6-2-u1-X02"}],"explanation":["친구 ❶의 말을 읽어요.","건조한 기후, 모래 비탈, 흙벽돌 집이 나와요.","모로코예요."],"asset":{"type":"speech","turns":[{"who":"친구 ❶","text":"건조한 기후가 나타나는 나라에 가고 싶어. 땀이 나도 금방 마르잖아. 모래 비탈에서 보드도 타고 흙벽돌로 만든 집에도 가 보고 싶어."},{"who":"친구 ❷","text":"여름에도 빙하나 눈을 볼 수 있는 곳에 가 보고 싶어. 이누이트족의 생활을 체험하고 기념품도 사고 싶어."},{"who":"친구 ❸","text":"여름에는 물놀이가 제일이지. 야자수가 펼쳐진 바닷가에서 수영하고 열대 과일도 먹고 싶어. 거대한 폭포도 보러 가고 말이야."},{"who":"친구 ❹","text":"여름에는 시원한 곳이 최고야. 지대가 높은 산은 일 년 내내 시원하니까 유명한 산이 있는 나라로 여행 가서 트레킹을 해 보고 싶어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_a#22','soc',6,2,'u1','','tb_g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C1',3,'blank','auto','생각 그물에서 하천 지형의 지형 경관을 「하천, 계곡, 평야, (    ) 등」으로 정리했어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":22,"concept":"SO6-2-u1-C1","difficulty":3,"kind":"blank","stem":"생각 그물에서 하천 지형의 지형 경관을 「하천, 계곡, 평야, (    ) 등」으로 정리했어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"폭포","correct":true},{"t":"갯벌","mis":"SO6-2-u1-X03"},{"t":"고원","mis":"SO6-2-u1-X03"},{"t":"모래사장","mis":"SO6-2-u1-X03"}],"explanation":["하천을 따라 나타나는 경관을 떠올려요.","물이 절벽 아래로 떨어져요.","폭포예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_a#23','soc',6,2,'u1','','tb_g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C10',4,'essay','teacher','빙고 놀이처럼 정답 낱말을 말하지 않고 친구에게 낼 문제를 만들어 보세요. 함께 빙고 판의 낱말 「화전 농업」, 「계단식 논」, 「고산 기후」, 「해안 지형」 가운데 하나를 골라 그 낱말을 설명하는 문제를 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO6-2-u1-C10","difficulty":4,"kind":"essay","stem":"빙고 놀이처럼 정답 낱말을 말하지 않고 친구에게 낼 문제를 만들어 보세요. 함께 빙고 판의 낱말 「화전 농업」, 「계단식 논」, 「고산 기후」, 「해안 지형」 가운데 하나를 골라 그 낱말을 설명하는 문제를 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 고른 낱말 — 고산 기후. 문제 — 이 기후는 해발 고도가 높은 지역에 나타나. 이 기후 지역 사람들은 챙이 넓고 둥근 모자를 쓰고 알파카와 라마를 길러.","scoring_points":["정답 낱말을 직접 말하지 않았는가","낱말의 뜻이나 특징을 바르게 담았는가","두 문장으로 정답을 찾을 수 있는가"]},"explanation":["낱말 하나를 골라요.","뜻과 특징을 떠올려요.","정답을 말하지 않고 설명해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_a#24','soc',6,2,'u1','','tb_g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C10',4,'essay','teacher','이 단원에서 배운 내용 가운데 사람들이 자연환경에 적응하거나 극복하며 살아가는 모습을 지형에서 하나, 기후에서 하나 골라 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-2-u1-C10","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 내용 가운데 사람들이 자연환경에 적응하거나 극복하며 살아가는 모습을 지형에서 하나, 기후에서 하나 골라 쓰세요.","answer_guide":{"answer":"예: 지형 — 필리핀 바나우에 사람들은 가파른 산비탈을 계단처럼 다듬어 논을 만들었어요. 기후 — 사막 지역 사람들은 강한 햇볕과 모래바람을 막으려고 온몸을 감싸는 옷을 입어요.","scoring_points":["지형에서 예를 하나 들었는가","기후에서 예를 하나 들었는가","적응하거나 극복하는 모습임이 드러나는가"]},"explanation":["지형과 기후를 나눠요.","사람들이 바꾸거나 맞춘 모습을 찾아요.","하나씩 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_a#25','soc',6,2,'u1','','tb_g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C10',4,'essay','teacher','「세계의 자연환경」 단원을 공부하며 새로 알게 된 점이나 느낀 점을 지형과 기후를 모두 넣어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-2-u1-C10","difficulty":4,"kind":"essay","stem":"「세계의 자연환경」 단원을 공부하며 새로 알게 된 점이나 느낀 점을 지형과 기후를 모두 넣어 쓰세요.","answer_guide":{"answer":"예: 세계에는 산지, 하천, 해안 같은 다양한 지형 경관과 열대부터 한대, 고산까지 다양한 기후가 있고, 이것이 사람들의 집, 옷, 음식, 하는 일에 영향을 미친다는 것을 알게 됐어요. 사람들이 자연환경에 적응하고 극복하며 살아가는 모습이 놀라웠어요.","scoring_points":["지형에 관해 알게 된 점을 썼는가","기후에 관해 알게 된 점을 썼는가","자연환경과 생활을 이어 썼는가"]},"explanation":["지형과 기후를 떠올려요.","생활과의 관계를 생각해요.","알게 된 점과 느낌을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_b#1','soc',6,2,'u1','','tb_g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C1',1,'mc','auto','땅의 모양을 뜻하는 말로, 산지·하천·해안·사막을 함께 부르는 말은 무엇인가요?',ARRAY['SO6-2-u1-X08','SO6-2-u1-X09']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C1","difficulty":1,"kind":"mc","stem":"땅의 모양을 뜻하는 말로, 산지·하천·해안·사막을 함께 부르는 말은 무엇인가요?","options":[{"t":"지형","correct":true},{"t":"기후","mis":"SO6-2-u1-X08"},{"t":"날씨","mis":"SO6-2-u1-X08"},{"t":"위도","mis":"SO6-2-u1-X09"}],"explanation":["산지, 하천, 해안, 사막을 떠올려요.","모두 땅의 모양이에요.","지형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_b#2','soc',6,2,'u1','','tb_g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C2',1,'mc','auto','산지 지형에서 말하는 해발 고도는 무엇을 기준으로 잰 높이인가요?',ARRAY['SO6-2-u1-X04','SO6-2-u1-X03','SO6-2-u1-X09']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C2","difficulty":1,"kind":"mc","stem":"산지 지형에서 말하는 해발 고도는 무엇을 기준으로 잰 높이인가요?","options":[{"t":"바다 표면","correct":true},{"t":"산꼭대기","mis":"SO6-2-u1-X04"},{"t":"강바닥","mis":"SO6-2-u1-X03"},{"t":"적도","mis":"SO6-2-u1-X09"}],"explanation":["해발 고도의 뜻을 떠올려요.","바다 표면으로부터 재요.","바다 표면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_b#3','soc',6,2,'u1','','tb_g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C2',1,'mc','auto','칠레 추키카마타에서 광업이 발달한 까닭은 무엇인가요?',ARRAY['SO6-2-u1-X03','SO6-2-u1-X04']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C2","difficulty":1,"kind":"mc","stem":"칠레 추키카마타에서 광업이 발달한 까닭은 무엇인가요?","options":[{"t":"구리 매장량이 많기 때문이에요","correct":true},{"t":"화산 분출을 볼 수 있기 때문이에요","mis":"SO6-2-u1-X03"},{"t":"풀이 잘 자라기 때문이에요","mis":"SO6-2-u1-X04"},{"t":"계단식 논이 많기 때문이에요","mis":"SO6-2-u1-X03"}],"explanation":["교과서 17쪽 사진이에요.","땅속에 구리가 많아요.","그래서 광업이 발달했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_b#4','soc',6,2,'u1','','tb_g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C3',1,'mc','auto','울창한 숲 사이로 큰 강이 구불구불 흐르는 아마존강이 있는 나라는 어디인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C3","difficulty":1,"kind":"mc","stem":"울창한 숲 사이로 큰 강이 구불구불 흐르는 아마존강이 있는 나라는 어디인가요?","options":[{"t":"브라질","correct":true},{"t":"이집트","mis":"SO6-2-u1-X03"},{"t":"미국","mis":"SO6-2-u1-X03"},{"t":"잠비아","mis":"SO6-2-u1-X03"}],"explanation":["교과서 19쪽 사진 ㉠이에요.","아마존강은 남아메리카에 있어요.","브라질이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_b#5','soc',6,2,'u1','','tb_g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C3',1,'mc','auto','흐르는 물의 힘을 이용해 전기를 만드는 것을 무엇이라고 하나요?',ARRAY['SO6-2-u1-X05']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C3","difficulty":1,"kind":"mc","stem":"흐르는 물의 힘을 이용해 전기를 만드는 것을 무엇이라고 하나요?","options":[{"t":"수력 발전","correct":true},{"t":"화전 농업","mis":"SO6-2-u1-X05"},{"t":"양식업","mis":"SO6-2-u1-X05"},{"t":"광업","mis":"SO6-2-u1-X05"}],"explanation":["노르웨이를 떠올려요.","물의 힘으로 전기를 만들어요.","수력 발전이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_b#6','soc',6,2,'u1','','tb_g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C4',1,'mc','auto','깔때기 모양의 지형으로 조수 간만의 차가 매우 큰 것으로 유명한 캐나다 동부 해안의 갯벌은 어디인가요?',ARRAY['SO6-2-u1-X03','SO6-2-u1-X06']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C4","difficulty":1,"kind":"mc","stem":"깔때기 모양의 지형으로 조수 간만의 차가 매우 큰 것으로 유명한 캐나다 동부 해안의 갯벌은 어디인가요?","options":[{"t":"펀디만","correct":true},{"t":"마케나 모래사장","mis":"SO6-2-u1-X03"},{"t":"포트 캠벨 국립 공원","mis":"SO6-2-u1-X03"},{"t":"게랑드","mis":"SO6-2-u1-X06"}],"explanation":["교과서 23쪽 사진 ①이에요.","캐나다의 갯벌이에요.","펀디만이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_b#7','soc',6,2,'u1','','tb_g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C4',1,'mc','auto','갯벌이 넓게 펼쳐진 해안에 발달하기도 하는 것은 무엇인가요?',ARRAY['SO6-2-u1-X06','SO6-2-u1-X03','SO6-2-u1-X05']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C4","difficulty":1,"kind":"mc","stem":"갯벌이 넓게 펼쳐진 해안에 발달하기도 하는 것은 무엇인가요?","options":[{"t":"염전","correct":true},{"t":"항구","mis":"SO6-2-u1-X06"},{"t":"스키장","mis":"SO6-2-u1-X03"},{"t":"수력 발전소","mis":"SO6-2-u1-X05"}],"explanation":["게랑드를 떠올려요.","갯벌을 이용해 소금을 만들어요.","염전이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_b#8','soc',6,2,'u1','','tb_g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C1',1,'match','auto','지형과 그 지형을 이용하는 사람들의 생활을 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u1-C1","difficulty":1,"kind":"match","stem":"지형과 그 지형을 이용하는 사람들의 생활을 이으세요.","pairs":[{"l":"산지","r":"계단식 농사"},{"l":"하천","r":"수상 시장"},{"l":"해안","r":"염전"}],"mis":"SO6-2-u1-X03","explanation":["지형마다 이용을 떠올려요.","가파른 산지는 계단식 농사예요.","하천은 수상 시장, 해안은 염전이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_b#9','soc',6,2,'u1','','tb_g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C5',2,'mc','auto','저위도, 중위도, 고위도 가운데 햇볕을 가장 많이 받아 연평균 기온이 가장 높은 곳은 어디인가요?',ARRAY['SO6-2-u1-X09']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"mc","stem":"저위도, 중위도, 고위도 가운데 햇볕을 가장 많이 받아 연평균 기온이 가장 높은 곳은 어디인가요?","options":[{"t":"저위도","correct":true},{"t":"중위도","mis":"SO6-2-u1-X09"},{"t":"고위도","mis":"SO6-2-u1-X09"},{"t":"셋 모두 같아요","mis":"SO6-2-u1-X09"}],"explanation":["적도에 가까운 곳을 떠올려요.","햇볕을 가장 많이 받아요.","저위도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_b#10','soc',6,2,'u1','','tb_g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C5',2,'mc','auto','세계의 기후를 구분할 때 주로 쓰는 기준을 바르게 고른 것은 무엇인가요?',ARRAY['SO6-2-u1-X10','SO6-2-u1-X08']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"mc","stem":"세계의 기후를 구분할 때 주로 쓰는 기준을 바르게 고른 것은 무엇인가요?","options":[{"t":"기온과 강수량","correct":true},{"t":"산의 높이와 바다의 깊이","mis":"SO6-2-u1-X10"},{"t":"사람 수와 나라 크기","mis":"SO6-2-u1-X10"},{"t":"하루의 날씨","mis":"SO6-2-u1-X08"}],"explanation":["교과서 33쪽 글을 읽어요.","주로 두 가지로 구분해요.","기온과 강수량이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_b#11','soc',6,2,'u1','','tb_g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C6',2,'mc','auto','쿠알라룸푸르처럼 일 년 내내 비가 많이 내리는 열대 기후 지역에 나타나는 자연 경관은 무엇인가요?',ARRAY['SO6-2-u1-X15','SO6-2-u1-X13','SO6-2-u1-X11']::text[],false,'{"seq":11,"concept":"SO6-2-u1-C6","difficulty":2,"kind":"mc","stem":"쿠알라룸푸르처럼 일 년 내내 비가 많이 내리는 열대 기후 지역에 나타나는 자연 경관은 무엇인가요?","options":[{"t":"열대 우림","correct":true},{"t":"초원","mis":"SO6-2-u1-X15"},{"t":"침엽수림","mis":"SO6-2-u1-X13"},{"t":"사막","mis":"SO6-2-u1-X11"}],"explanation":["비가 일 년 내내 많아요.","숲이 빽빽하게 자라요.","열대 우림이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_b#12','soc',6,2,'u1','','tb_g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C5',2,'mc','auto','적도 지방에서 극지방으로 갈 때 온대 기후 다음에 나타나는 기후는 무엇인가요?',ARRAY['SO6-2-u1-X10','SO6-2-u1-X14']::text[],false,'{"seq":12,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"mc","stem":"적도 지방에서 극지방으로 갈 때 온대 기후 다음에 나타나는 기후는 무엇인가요?","options":[{"t":"냉대 기후","correct":true},{"t":"건조 기후","mis":"SO6-2-u1-X10"},{"t":"열대 기후","mis":"SO6-2-u1-X10"},{"t":"고산 기후","mis":"SO6-2-u1-X14"}],"explanation":["기후의 차례를 떠올려요.","온대 다음은 냉대예요.","그다음은 한대예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_b#13','soc',6,2,'u1','','tb_g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C7',2,'mc','auto','건조 기후 지역 가운데 약간의 비나 눈이 내리는 곳에 넓게 펼쳐지는 경관은 무엇인가요?',ARRAY['SO6-2-u1-X11','SO6-2-u1-X13','SO6-2-u1-X14']::text[],false,'{"seq":13,"concept":"SO6-2-u1-C7","difficulty":2,"kind":"mc","stem":"건조 기후 지역 가운데 약간의 비나 눈이 내리는 곳에 넓게 펼쳐지는 경관은 무엇인가요?","options":[{"t":"초원","correct":true},{"t":"열대 우림","mis":"SO6-2-u1-X11"},{"t":"침엽수림","mis":"SO6-2-u1-X13"},{"t":"빙하","mis":"SO6-2-u1-X14"}],"explanation":["교과서 36쪽 글을 읽어요.","비가 조금 내려요.","초원이 넓게 펼쳐져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_b#14','soc',6,2,'u1','','tb_g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C8',2,'mc','auto','여름에 강수량이 집중되는 우리나라를 비롯한 아시아에서 많이 짓는 농사는 무엇인가요?',ARRAY['SO6-2-u1-X13','SO6-2-u1-X12']::text[],false,'{"seq":14,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"mc","stem":"여름에 강수량이 집중되는 우리나라를 비롯한 아시아에서 많이 짓는 농사는 무엇인가요?","options":[{"t":"벼농사","correct":true},{"t":"올리브 재배","mis":"SO6-2-u1-X13"},{"t":"대추야자 재배","mis":"SO6-2-u1-X12"},{"t":"카카오 재배","mis":"SO6-2-u1-X12"}],"explanation":["여름에 비가 많아요.","물이 많이 필요한 작물이 잘 자라요.","벼농사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_b#15','soc',6,2,'u1','','tb_g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C8',2,'mc','auto','냉대 기후 지역 사람들이 겨울의 추위를 이겨 내려고 입는 옷은 무엇인가요?',ARRAY['SO6-2-u1-X12','SO6-2-u1-X14']::text[],false,'{"seq":15,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"mc","stem":"냉대 기후 지역 사람들이 겨울의 추위를 이겨 내려고 입는 옷은 무엇인가요?","options":[{"t":"두꺼운 털옷과 털모자","correct":true},{"t":"얇고 바람이 잘 통하는 옷","mis":"SO6-2-u1-X12"},{"t":"온몸을 감싸는 흰 옷","mis":"SO6-2-u1-X12"},{"t":"여러 겹 옷과 망토","mis":"SO6-2-u1-X14"}],"explanation":["냉대 기후의 겨울을 떠올려요.","몹시 추워요.","두꺼운 털옷과 털모자를 입어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
