INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_b#18','soc',6,2,'u1','','tb_g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C4',3,'mc','auto','보라카이섬과 에베레스트산 이야기에서 공통으로 알 수 있는 것은 무엇인가요?',ARRAY['SO6-2-u1-X07','SO6-2-u1-X02']::text[],false,'{"seq":18,"concept":"SO6-2-u1-C4","difficulty":3,"kind":"mc","stem":"보라카이섬과 에베레스트산 이야기에서 공통으로 알 수 있는 것은 무엇인가요?","options":[{"t":"관광은 주민에게 수입을 주지만 쓰레기로 환경을 오염시키기도 해요","correct":true},{"t":"관광은 좋은 점만 있어요","mis":"SO6-2-u1-X07"},{"t":"관광객은 쓰레기를 남기지 않아요","mis":"SO6-2-u1-X07"},{"t":"관광과 주민 생활은 관계가 없어요","mis":"SO6-2-u1-X02"}],"explanation":["두 이야기를 견줘요.","모두 수입이 생겼어요.","모두 쓰레기 문제도 생겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_b#19','soc',6,2,'u1','','tb_g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C9',3,'mc','auto','한대 기후 지역 여행에서 체험하기 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X14']::text[],false,'{"seq":19,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"mc","stem":"한대 기후 지역 여행에서 체험하기 알맞은 것은 무엇인가요?","options":[{"t":"오로라와 빙하 관광","correct":true},{"t":"사막 모래 썰매","mis":"SO6-2-u1-X14"},{"t":"지중해 해수욕","mis":"SO6-2-u1-X14"},{"t":"열대 과일 따기","mis":"SO6-2-u1-X14"}],"explanation":["한대 기후 지역을 떠올려요.","오로라와 빙하가 있어요.","오로라와 빙하 관광이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_b#20','soc',6,2,'u1','','tb_g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C9',3,'mc','auto','고산 기후 지역 사람들이 낮은 기온에서도 잘 자라 주로 재배하는 작물은 무엇인가요?',ARRAY['SO6-2-u1-X14','SO6-2-u1-X12']::text[],false,'{"seq":20,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"mc","stem":"고산 기후 지역 사람들이 낮은 기온에서도 잘 자라 주로 재배하는 작물은 무엇인가요?","options":[{"t":"감자와 옥수수","correct":true},{"t":"카카오와 바나나","mis":"SO6-2-u1-X14"},{"t":"올리브와 포도","mis":"SO6-2-u1-X14"},{"t":"대추야자","mis":"SO6-2-u1-X12"}],"explanation":["교과서 42쪽 글을 읽어요.","서늘한 곳에서도 잘 자라요.","감자와 옥수수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_b#21','soc',6,2,'u1','','tb_g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C5',3,'mc','auto','세계 여행 박람회에서 친구 ❷가 가고 싶어 하는 나라로 알맞은 곳은 어디인가요?',ARRAY['SO6-2-u1-X02']::text[],false,'{"seq":21,"concept":"SO6-2-u1-C5","difficulty":3,"kind":"mc","stem":"세계 여행 박람회에서 친구 ❷가 가고 싶어 하는 나라로 알맞은 곳은 어디인가요?","options":[{"t":"캐나다","correct":true},{"t":"모로코","mis":"SO6-2-u1-X02"},{"t":"브라질","mis":"SO6-2-u1-X02"},{"t":"네팔","mis":"SO6-2-u1-X02"}],"explanation":["친구 ❷의 말을 읽어요.","빙하와 눈, 이누이트족의 생활이 나와요.","캐나다예요."],"asset":{"type":"speech","turns":[{"who":"친구 ❶","text":"건조한 기후가 나타나는 나라에 가고 싶어. 땀이 나도 금방 마르잖아. 모래 비탈에서 보드도 타고 흙벽돌로 만든 집에도 가 보고 싶어."},{"who":"친구 ❷","text":"여름에도 빙하나 눈을 볼 수 있는 곳에 가 보고 싶어. 이누이트족의 생활을 체험하고 기념품도 사고 싶어."},{"who":"친구 ❸","text":"여름에는 물놀이가 제일이지. 야자수가 펼쳐진 바닷가에서 수영하고 열대 과일도 먹고 싶어. 거대한 폭포도 보러 가고 말이야."},{"who":"친구 ❹","text":"여름에는 시원한 곳이 최고야. 지대가 높은 산은 일 년 내내 시원하니까 유명한 산이 있는 나라로 여행 가서 트레킹을 해 보고 싶어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_b#22','soc',6,2,'u1','','tb_g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C7',3,'blank','auto','생각 그물에서 건조 기후의 생활 모습을 「(    )(으)로 만든 집, 유목과 이동식 가옥에서 생활 등」으로 정리했어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-2-u1-X12']::text[],false,'{"seq":22,"concept":"SO6-2-u1-C7","difficulty":3,"kind":"blank","stem":"생각 그물에서 건조 기후의 생활 모습을 「(    )(으)로 만든 집, 유목과 이동식 가옥에서 생활 등」으로 정리했어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"흙벽돌","correct":true},{"t":"통나무","mis":"SO6-2-u1-X12"},{"t":"얼음","mis":"SO6-2-u1-X12"},{"t":"대나무","mis":"SO6-2-u1-X12"}],"explanation":["사막의 집을 떠올려요.","벽이 두껍고 창문이 작아요.","흙벽돌로 만든 집이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_b#23','soc',6,2,'u1','','tb_g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C7',4,'mc','auto','빙고 놀이에서 친구가 「이 기후 지역에서는 오아시스 주변에서 농사를 지어. 이 기후의 초원에서는 사람들이 이동식 가옥에 살아.」라고 문제를 냈어요. 정답과 관계있는 함께 빙고 판의 낱말은 무엇인가요?',ARRAY['SO6-2-u1-X11','SO6-2-u1-X13','SO6-2-u1-X14']::text[],false,'{"seq":23,"concept":"SO6-2-u1-C7","difficulty":4,"kind":"mc","stem":"빙고 놀이에서 친구가 「이 기후 지역에서는 오아시스 주변에서 농사를 지어. 이 기후의 초원에서는 사람들이 이동식 가옥에 살아.」라고 문제를 냈어요. 정답과 관계있는 함께 빙고 판의 낱말은 무엇인가요?","options":[{"t":"건조 기후","correct":true},{"t":"열대 우림","mis":"SO6-2-u1-X11"},{"t":"침엽수림","mis":"SO6-2-u1-X13"},{"t":"고산 기후","mis":"SO6-2-u1-X14"}],"explanation":["두 문장의 실마리를 모아요.","오아시스와 이동식 가옥이에요.","건조 기후예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_b#24','soc',6,2,'u1','','tb_g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C8',4,'mc','auto','「같은 기후 환경에서도 다양한 생활 모습이 나타난다」는 것을 보여 주는 예로 가장 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X15','SO6-2-u1-X19']::text[],false,'{"seq":24,"concept":"SO6-2-u1-C8","difficulty":4,"kind":"mc","stem":"「같은 기후 환경에서도 다양한 생활 모습이 나타난다」는 것을 보여 주는 예로 가장 알맞은 것은 무엇인가요?","options":[{"t":"같은 온대 기후라도 서부 유럽은 밀과 낙농업, 지중해 주변은 올리브와 포도, 아시아는 벼농사를 해요","correct":true},{"t":"열대 기후 지역은 모두 일 년 내내 비가 많이 와요","mis":"SO6-2-u1-X15"},{"t":"한 나라에는 한 가지 기후만 나타나요","mis":"SO6-2-u1-X19"},{"t":"기후가 같으면 하는 일도 모두 같아요","mis":"SO6-2-u1-X15"}],"explanation":["같은 기후 안을 견줘요.","온대 기후 지역의 농업이 여러 가지예요.","생활이 다양해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_b#25','soc',6,2,'u1','','tb_g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C2',4,'essay','teacher','세계의 유명한 지형 경관 가운데 한 곳을 골라 그곳의 지형 경관 특징, 사람들의 생활 모습, 관광이 그곳에 주는 영향을 차례로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-2-u1-C2","difficulty":4,"kind":"essay","stem":"세계의 유명한 지형 경관 가운데 한 곳을 골라 그곳의 지형 경관 특징, 사람들의 생활 모습, 관광이 그곳에 주는 영향을 차례로 쓰세요.","answer_guide":{"answer":"예: 네팔의 에베레스트산은 세계에서 가장 높은 산이에요. 주민들은 관광객에게 음식과 잠자리를 내주고 셰르파로 일하며 수입을 얻어요. 하지만 관광객이 버린 쓰레기로 환경이 오염되어 정부가 쓰레기를 되가져오게 하고 있어요.","scoring_points":["지형 경관의 특징을 썼는가","그곳 사람들의 생활 모습을 썼는가","관광의 좋은 점과 문제를 함께 썼는가"]},"explanation":["한 곳을 골라요.","경관과 생활을 써요.","관광의 두 면을 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_c#1','soc',6,2,'u1','','tb_g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C1',1,'ox','auto','같은 산지에 들어도 마우나로아, 울루루, 호라이마산의 경관 특징은 서로 달라요.',ARRAY['SO6-2-u1-X01']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C1","difficulty":1,"kind":"ox","stem":"같은 산지에 들어도 마우나로아, 울루루, 호라이마산의 경관 특징은 서로 달라요.","answer":"O","reason_options":[{"t":"화산·거대한 바위산·위가 평평한 산처럼 같은 갈래 안에서도 특징이 다르기 때문에","correct":true},{"t":"같은 갈래의 지형은 모습이 모두 같기 때문에","mis":"SO6-2-u1-X01"}],"mis":"SO6-2-u1-X01","explanation":["세 곳의 특징을 견줘요.","화산, 바위산, 평평한 산이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 송네 피오르(노르웨이) — 가파른 산으로 둘러싸인 매우 좁고 긴 해안선","② 사하라 사막(리비아) — 광활하게 펼쳐진 모래 언덕","③ 황허강(중국) — 황토가 섞여 색이 누런 강물이 굽이쳐 길게 흐름","④ 울루루(오스트레일리아) — 하나의 거대한 암석 바위산이 드넓은 평지에 솟음","⑤ 마우나로아(미국) — 용암이 흐르는 모습을 볼 수 있는 화산","⑥ 엘 아르코(멕시코) — 바다 위에 우뚝 솟은 아치 모양의 바위","⑦ 호라이마산(베네수엘라 볼리바르) — 우뚝 솟아 있지만 위쪽이 평평함"],"numbered":false,"title":"교과서 13~14쪽 세계의 유명한 지형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_c#2','soc',6,2,'u1','','tb_g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C2',1,'ox','auto','산지에는 정상이 움푹 파이거나 물이 고여 있는 화산도 있어요.',ARRAY['SO6-2-u1-X04']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C2","difficulty":1,"kind":"ox","stem":"산지에는 정상이 움푹 파이거나 물이 고여 있는 화산도 있어요.","answer":"O","reason_options":[{"t":"교과서 15쪽처럼 산지에는 화산의 모습도 있기 때문에","correct":true},{"t":"산지는 모두 꼭대기가 뾰족한 모습뿐이기 때문에","mis":"SO6-2-u1-X04"}],"mis":"SO6-2-u1-X04","explanation":["파리나코타화산을 떠올려요.","화산도 산지예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_c#3','soc',6,2,'u1','','tb_g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C2',1,'ox','auto','스위스의 알프스산맥은 아름다운 지형 경관을 이용한 관광지가 발달했어요.',ARRAY['SO6-2-u1-X04']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C2","difficulty":1,"kind":"ox","stem":"스위스의 알프스산맥은 아름다운 지형 경관을 이용한 관광지가 발달했어요.","answer":"O","reason_options":[{"t":"교과서 16쪽처럼 아름다운 지형 경관을 관광지로 이용하기 때문에","correct":true},{"t":"산지는 관광지로 쓸 수 없기 때문에","mis":"SO6-2-u1-X04"}],"mis":"SO6-2-u1-X04","explanation":["알프스산맥 사진이에요.","경관이 아름다워요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_c#4','soc',6,2,'u1','','tb_g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C3',1,'ox','auto','하천을 따라 거대한 폭포 같은 웅장한 경관이 나타나기도 해요.',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C3","difficulty":1,"kind":"ox","stem":"하천을 따라 거대한 폭포 같은 웅장한 경관이 나타나기도 해요.","answer":"O","reason_options":[{"t":"교과서 19쪽 빅토리아 폭포처럼 하천을 따라 폭포가 나타나기 때문에","correct":true},{"t":"폭포는 바닷가에만 있기 때문에","mis":"SO6-2-u1-X03"}],"mis":"SO6-2-u1-X03","explanation":["빅토리아 폭포를 떠올려요.","강물이 절벽 아래로 떨어져요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_c#5','soc',6,2,'u1','','tb_g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C3',1,'ox','auto','타이 짜오프라야강에서는 사람들이 배 위에서 물건을 사고팔아요.',ARRAY['SO6-2-u1-X05']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C3","difficulty":1,"kind":"ox","stem":"타이 짜오프라야강에서는 사람들이 배 위에서 물건을 사고팔아요.","answer":"O","reason_options":[{"t":"짜오프라야강에는 수상 시장이 발달했기 때문에","correct":true},{"t":"강 위에서는 물건을 사고팔 수 없기 때문에","mis":"SO6-2-u1-X05"}],"mis":"SO6-2-u1-X05","explanation":["교과서 21쪽 사진이에요.","수상 시장이 열려요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_c#6','soc',6,2,'u1','','tb_g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C4',1,'ox','auto','해안에서는 갯벌, 모래사장, 거대한 절벽이나 돌기둥 같은 지형 경관을 볼 수 있어요.',ARRAY['SO6-2-u1-X01']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C4","difficulty":1,"kind":"ox","stem":"해안에서는 갯벌, 모래사장, 거대한 절벽이나 돌기둥 같은 지형 경관을 볼 수 있어요.","answer":"O","reason_options":[{"t":"교과서 23쪽에서 해안 지역의 지형 경관으로 소개했기 때문에","correct":true},{"t":"해안에는 모래사장 하나만 있기 때문에","mis":"SO6-2-u1-X01"}],"mis":"SO6-2-u1-X01","explanation":["교과서 23쪽 글을 읽어요.","해안에는 여러 모습이 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_c#7','soc',6,2,'u1','','tb_g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C4',1,'ox','auto','경관이 아름다운 해안에는 관광지가 형성돼요.',ARRAY['SO6-2-u1-X02']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C4","difficulty":1,"kind":"ox","stem":"경관이 아름다운 해안에는 관광지가 형성돼요.","answer":"O","reason_options":[{"t":"멕시코 해변처럼 아름다운 모래사장에 관광객이 많이 찾아오기 때문에","correct":true},{"t":"아름다운 해안에는 사람이 찾아오지 않기 때문에","mis":"SO6-2-u1-X02"}],"mis":"SO6-2-u1-X02","explanation":["멕시코 해변을 떠올려요.","관광객이 많이 찾아와요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_c#8','soc',6,2,'u1','','tb_g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C1',1,'match','auto','교과서에 나온 곳과 그곳의 지형을 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u1-C1","difficulty":1,"kind":"match","stem":"교과서에 나온 곳과 그곳의 지형을 이으세요.","pairs":[{"l":"알프스산맥","r":"산지"},{"l":"빅토리아 폭포","r":"하천"},{"l":"펀디만","r":"해안"},{"l":"사하라","r":"사막"}],"mis":"SO6-2-u1-X03","explanation":["곳마다 모습을 떠올려요.","산맥은 산지, 폭포는 하천이에요.","펀디만은 해안, 사하라는 사막이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_c#9','soc',6,2,'u1','','tb_g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C5',2,'ox','auto','대체로 적도 지방에서 극지방으로 갈수록 기온은 점차 높아져요.',ARRAY['SO6-2-u1-X09']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"ox","stem":"대체로 적도 지방에서 극지방으로 갈수록 기온은 점차 높아져요.","answer":"X","reason_options":[{"t":"적도 지방에서 극지방으로 갈수록 햇볕을 적게 받아 기온이 점차 낮아지기 때문에","correct":true},{"t":"극지방이 해에 더 가깝기 때문에","mis":"SO6-2-u1-X09"}],"mis":"SO6-2-u1-X09","explanation":["극지방을 떠올려요.","햇볕을 적게 받아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_c#10','soc',6,2,'u1','','tb_g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C5',2,'ox','auto','세계의 기후는 열대, 건조, 온대, 냉대, 한대, 고산 기후 등으로 구분할 수 있어요.',ARRAY['SO6-2-u1-X10']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"ox","stem":"세계의 기후는 열대, 건조, 온대, 냉대, 한대, 고산 기후 등으로 구분할 수 있어요.","answer":"O","reason_options":[{"t":"교과서 32~33쪽 세계의 기후 분포도에서 이렇게 구분했기 때문에","correct":true},{"t":"세계의 기후는 더운 기후와 추운 기후 두 가지뿐이기 때문에","mis":"SO6-2-u1-X10"}],"mis":"SO6-2-u1-X10","explanation":["기후 분포도의 기후를 세어요.","여섯 가지가 나와요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_c#11','soc',6,2,'u1','','tb_g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C6',2,'ox','auto','열대 기후 지역은 모두 일 년 내내 비가 많이 내려요.',ARRAY['SO6-2-u1-X15']::text[],false,'{"seq":11,"concept":"SO6-2-u1-C6","difficulty":2,"kind":"ox","stem":"열대 기후 지역은 모두 일 년 내내 비가 많이 내려요.","answer":"X","reason_options":[{"t":"므완자처럼 건기와 우기가 번갈아 나타나 초원이 넓게 펼쳐진 곳도 있기 때문에","correct":true},{"t":"열대 기후는 어디서나 똑같기 때문에","mis":"SO6-2-u1-X15"}],"mis":"SO6-2-u1-X15","explanation":["므완자를 떠올려요.","건기와 우기가 번갈아 나타나요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_c#12','soc',6,2,'u1','','tb_g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C5',2,'ox','auto','건조 기후는 열대 기후보다 적도에 더 가까운 곳에 주로 나타나요.',ARRAY['SO6-2-u1-X10']::text[],false,'{"seq":12,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"ox","stem":"건조 기후는 열대 기후보다 적도에 더 가까운 곳에 주로 나타나요.","answer":"X","reason_options":[{"t":"적도 지방에서 극지방으로 가면서 열대 기후 다음에 건조 기후가 나타나기 때문에","correct":true},{"t":"건조 기후가 가장 더운 기후이기 때문에","mis":"SO6-2-u1-X10"}],"mis":"SO6-2-u1-X10","explanation":["적도에서 가장 가까운 기후를 찾아요.","열대 기후예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_c#13','soc',6,2,'u1','','tb_g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C7',2,'ox','auto','건조 기후 지역은 낮과 밤의 기온 차이가 커요.',ARRAY['SO6-2-u1-X11']::text[],false,'{"seq":13,"concept":"SO6-2-u1-C7","difficulty":2,"kind":"ox","stem":"건조 기후 지역은 낮과 밤의 기온 차이가 커요.","answer":"O","reason_options":[{"t":"교과서 36쪽에서 건조 기후는 낮과 밤의 기온 차이가 크다고 했기 때문에","correct":true},{"t":"건조한 곳은 낮과 밤이 똑같이 덥기 때문에","mis":"SO6-2-u1-X11"}],"mis":"SO6-2-u1-X11","explanation":["건조 기후의 특징을 떠올려요.","낮과 밤의 기온 차이가 커요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_c#14','soc',6,2,'u1','','tb_g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C8',2,'ox','auto','지중해 주변 지역은 덥고 건조한 여름에 비해 겨울이 따뜻하고 강수량이 많아요.',ARRAY['SO6-2-u1-X13']::text[],false,'{"seq":14,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"ox","stem":"지중해 주변 지역은 덥고 건조한 여름에 비해 겨울이 따뜻하고 강수량이 많아요.","answer":"O","reason_options":[{"t":"교과서 37쪽에서 지중해 주변 지역의 기후를 이렇게 설명했기 때문에","correct":true},{"t":"지중해 주변은 여름에 비가 가장 많이 오기 때문에","mis":"SO6-2-u1-X13"}],"mis":"SO6-2-u1-X13","explanation":["로마의 그래프를 떠올려요.","겨울에 강수량이 많아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_c#15','soc',6,2,'u1','','tb_g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C8',2,'ox','auto','냉대 기후는 겨울이 여름보다 짧고 따뜻해요.',ARRAY['SO6-2-u1-X13']::text[],false,'{"seq":15,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"ox","stem":"냉대 기후는 겨울이 여름보다 짧고 따뜻해요.","answer":"X","reason_options":[{"t":"냉대 기후는 겨울이 여름보다 길고 몹시 추우며 눈이 많이 내리기 때문에","correct":true},{"t":"냉대 기후는 적도 주변에 나타나기 때문에","mis":"SO6-2-u1-X13"}],"mis":"SO6-2-u1-X13","explanation":["냉대 기후의 특징을 떠올려요.","겨울이 길고 몹시 추워요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_c#16','soc',6,2,'u1','','tb_g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C6',2,'ox','auto','열대 기후 지역에서는 사파리 관광, 전통 부족 생활 체험 같은 생태 관광 산업도 이루어져요.',ARRAY['SO6-2-u1-X02']::text[],false,'{"seq":16,"concept":"SO6-2-u1-C6","difficulty":2,"kind":"ox","stem":"열대 기후 지역에서는 사파리 관광, 전통 부족 생활 체험 같은 생태 관광 산업도 이루어져요.","answer":"O","reason_options":[{"t":"교과서 35쪽에서 열대 기후 지역의 생태 관광 산업을 소개했기 때문에","correct":true},{"t":"열대 기후 지역은 관광과 관계가 없기 때문에","mis":"SO6-2-u1-X02"}],"mis":"SO6-2-u1-X02","explanation":["교과서 35쪽 글을 읽어요.","생태 관광 산업이 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_c#17','soc',6,2,'u1','','tb_g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C3',3,'mc','auto','하천 주변의 지형과 그곳 생활을 바르게 이은 것은 무엇인가요?',ARRAY['SO6-2-u1-X06','SO6-2-u1-X05']::text[],false,'{"seq":17,"concept":"SO6-2-u1-C3","difficulty":3,"kind":"mc","stem":"하천 주변의 지형과 그곳 생활을 바르게 이은 것은 무엇인가요?","options":[{"t":"하천이 운반한 퇴적물이 쌓인 넓은 평야 — 큰 규모의 농사","correct":true},{"t":"하천이 깎아 만든 깊은 계곡 — 염전","mis":"SO6-2-u1-X06"},{"t":"높은 폭포 — 대형 농기계 농사","mis":"SO6-2-u1-X05"},{"t":"울창한 숲 — 갯벌 양식업","mis":"SO6-2-u1-X06"}],"explanation":["평야가 생기는 까닭을 떠올려요.","퇴적물이 쌓여 넓은 평야가 돼요.","큰 규모로 농사를 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_c#18','soc',6,2,'u1','','tb_g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C4',3,'ox','auto','관광지의 환경을 지키려면 관광객 한 사람 한 사람의 노력도 필요해요.',ARRAY['SO6-2-u1-X07']::text[],false,'{"seq":18,"concept":"SO6-2-u1-C4","difficulty":3,"kind":"ox","stem":"관광지의 환경을 지키려면 관광객 한 사람 한 사람의 노력도 필요해요.","answer":"O","reason_options":[{"t":"관광객이 자기 쓰레기를 가져오는 등 함께 노력해야 환경이 지켜지기 때문에","correct":true},{"t":"환경 보호는 정부만 하면 되기 때문에","mis":"SO6-2-u1-X07"}],"mis":"SO6-2-u1-X07","explanation":["에베레스트산의 노력을 떠올려요.","관광객이 쓰레기를 되가져와요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_c#19','soc',6,2,'u1','','tb_g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C9',3,'ox','auto','한대 기후 지역은 일 년 내내 눈과 얼음으로 덮여 있는 곳이 많아요.',ARRAY['SO6-2-u1-X14']::text[],false,'{"seq":19,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"ox","stem":"한대 기후 지역은 일 년 내내 눈과 얼음으로 덮여 있는 곳이 많아요.","answer":"O","reason_options":[{"t":"겨울이 길고 기온이 매우 낮기 때문에","correct":true},{"t":"한대 기후 지역은 일 년 내내 덥기 때문에","mis":"SO6-2-u1-X14"}],"mis":"SO6-2-u1-X14","explanation":["교과서 41쪽 글을 읽어요.","기온이 매우 낮아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_c#20','soc',6,2,'u1','','tb_g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C9',3,'ox','auto','교과서 30쪽 사진전의 전통 의상처럼, 기후는 사람들의 옷차림에 영향을 줘요.',ARRAY['SO6-2-u1-X02']::text[],false,'{"seq":20,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"ox","stem":"교과서 30쪽 사진전의 전통 의상처럼, 기후는 사람들의 옷차림에 영향을 줘요.","answer":"O","reason_options":[{"t":"고산 기후의 모자와 망토처럼 옷은 그 지역의 기후에 맞추어 만들어지기 때문에","correct":true},{"t":"옷차림은 기후와 관계없이 유행으로만 정해지기 때문에","mis":"SO6-2-u1-X02"}],"mis":"SO6-2-u1-X02","explanation":["고산 기후의 옷차림을 떠올려요.","햇빛과 기온 차이에 맞춰요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_c#21','soc',6,2,'u1','','tb_g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C5',3,'mc','auto','세계 여행 박람회에서 친구 ❸이 가고 싶어 하는 나라로 알맞은 곳은 어디인가요?',ARRAY['SO6-2-u1-X02']::text[],false,'{"seq":21,"concept":"SO6-2-u1-C5","difficulty":3,"kind":"mc","stem":"세계 여행 박람회에서 친구 ❸이 가고 싶어 하는 나라로 알맞은 곳은 어디인가요?","options":[{"t":"브라질","correct":true},{"t":"모로코","mis":"SO6-2-u1-X02"},{"t":"캐나다","mis":"SO6-2-u1-X02"},{"t":"네팔","mis":"SO6-2-u1-X02"}],"explanation":["친구 ❸의 말을 읽어요.","야자수 바닷가, 열대 과일, 거대한 폭포가 나와요.","브라질이에요."],"asset":{"type":"speech","turns":[{"who":"친구 ❶","text":"건조한 기후가 나타나는 나라에 가고 싶어. 땀이 나도 금방 마르잖아. 모래 비탈에서 보드도 타고 흙벽돌로 만든 집에도 가 보고 싶어."},{"who":"친구 ❷","text":"여름에도 빙하나 눈을 볼 수 있는 곳에 가 보고 싶어. 이누이트족의 생활을 체험하고 기념품도 사고 싶어."},{"who":"친구 ❸","text":"여름에는 물놀이가 제일이지. 야자수가 펼쳐진 바닷가에서 수영하고 열대 과일도 먹고 싶어. 거대한 폭포도 보러 가고 말이야."},{"who":"친구 ❹","text":"여름에는 시원한 곳이 최고야. 지대가 높은 산은 일 년 내내 시원하니까 유명한 산이 있는 나라로 여행 가서 트레킹을 해 보고 싶어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_c#22','soc',6,2,'u1','','tb_g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C9',3,'blank','auto','생각 그물에서 한대 기후의 생활 모습을 「(    ) 유목, 지하자원 개발, 오로라·빙하 관광 등」으로 정리했어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-2-u1-X14','SO6-2-u1-X12','SO6-2-u1-X13']::text[],false,'{"seq":22,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"blank","stem":"생각 그물에서 한대 기후의 생활 모습을 「(    ) 유목, 지하자원 개발, 오로라·빙하 관광 등」으로 정리했어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"순록","correct":true},{"t":"알파카","mis":"SO6-2-u1-X14"},{"t":"낙타","mis":"SO6-2-u1-X12"},{"t":"젖소","mis":"SO6-2-u1-X13"}],"explanation":["한대 기후의 유목을 떠올려요.","이끼가 자라는 곳에서 길러요.","순록이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_c#23','soc',6,2,'u1','','tb_g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C8',4,'mc','auto','함께 빙고 판의 낱말 「올리브」와 「침엽수림」이 각각 어느 기후와 이어지는지 바르게 말한 것은 무엇인가요?',ARRAY['SO6-2-u1-X13']::text[],false,'{"seq":23,"concept":"SO6-2-u1-C8","difficulty":4,"kind":"mc","stem":"함께 빙고 판의 낱말 「올리브」와 「침엽수림」이 각각 어느 기후와 이어지는지 바르게 말한 것은 무엇인가요?","options":[{"t":"올리브 — 온대 기후, 침엽수림 — 냉대 기후","correct":true},{"t":"올리브 — 열대 기후, 침엽수림 — 한대 기후","mis":"SO6-2-u1-X13"},{"t":"올리브 — 건조 기후, 침엽수림 — 온대 기후","mis":"SO6-2-u1-X13"},{"t":"올리브 — 냉대 기후, 침엽수림 — 온대 기후","mis":"SO6-2-u1-X13"}],"explanation":["올리브는 지중해 주변에서 길러요.","침엽수림은 냉대 기후에 넓어요.","온대와 냉대예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_c#24','soc',6,2,'u1','','tb_g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C5',4,'mc','auto','우리와 다른 기후 환경에서 살아가는 사람들의 생활 모습을 대하는 태도로 가장 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X02']::text[],false,'{"seq":24,"concept":"SO6-2-u1-C5","difficulty":4,"kind":"mc","stem":"우리와 다른 기후 환경에서 살아가는 사람들의 생활 모습을 대하는 태도로 가장 알맞은 것은 무엇인가요?","options":[{"t":"그 기후에 적응하고 극복하며 생긴 생활 모습임을 이해하고 존중해요","correct":true},{"t":"우리와 다르면 이상한 생활이라고 여겨요","mis":"SO6-2-u1-X02"},{"t":"우리나라 생활 방식만 옳다고 여겨요","mis":"SO6-2-u1-X02"},{"t":"기후와 관계없이 아무렇게나 생긴 모습이라고 여겨요","mis":"SO6-2-u1-X02"}],"explanation":["생활 모습에는 까닭이 있어요.","기후에 맞춘 지혜예요.","이해하고 존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_c#25','soc',6,2,'u1','','tb_g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C6',4,'essay','teacher','열대 기후 지역과 한대 기후 지역 모두 바닥을 땅에서 띄운 집을 짓기도 해요. 두 지역에서 그렇게 짓는 까닭을 견주어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-2-u1-C6","difficulty":4,"kind":"essay","stem":"열대 기후 지역과 한대 기후 지역 모두 바닥을 땅에서 띄운 집을 짓기도 해요. 두 지역에서 그렇게 짓는 까닭을 견주어 쓰세요.","answer_guide":{"answer":"예: 열대 기후 지역에서는 덥고 습한 기후에 맞게 바람이 잘 통하도록 기둥을 세워 바닥을 땅에서 띄우고 창을 크게 만들어요. 한대 기후 지역에서는 집의 열이 얼어 있는 땅에 전해져 땅이 녹으면 건물이 무너질 수 있어 바닥을 띄운 고상 가옥을 지어요. 생김새는 비슷하지만 까닭은 서로 달라요.","scoring_points":["열대 기후 지역의 까닭을 썼는가","한대 기후 지역의 까닭을 썼는가","두 까닭을 견주었는가"]},"explanation":["열대의 집을 떠올려요.","한대의 집을 떠올려요.","같은 모양, 다른 까닭을 견줘요."],"asset":{"type":"passage","lines":["기후 — 한대 기후 · 나라 — 노르웨이","한대 기후 지역은 집의 열이 지면에 전달되어 얼어 있는 땅이 녹으면","건물이 무너질 위험이 있어요.","그래서 집의 바닥을 땅에서 띄운 고상 가옥을 지어요."],"title":"활동지 예시 — 한대 기후의 생활 모습 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_d#1','soc',6,2,'u1','','tb_g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C1',1,'mc','auto','교과서 13~14쪽의 지형 가운데 바닷가에 있는 지형 두 곳을 바르게 모은 것은 무엇인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C1","difficulty":1,"kind":"mc","stem":"교과서 13~14쪽의 지형 가운데 바닷가에 있는 지형 두 곳을 바르게 모은 것은 무엇인가요?","options":[{"t":"송네 피오르, 엘 아르코","correct":true},{"t":"황허강, 울루루","mis":"SO6-2-u1-X03"},{"t":"사하라 사막, 호라이마산","mis":"SO6-2-u1-X03"},{"t":"호라이마산, 황허강","mis":"SO6-2-u1-X03"}],"explanation":["바다와 이어진 곳을 찾아요.","피오르는 해안선, 엘 아르코는 바다 위 바위예요.","송네 피오르와 엘 아르코예요."],"asset":{"type":"passage","lines":["① 송네 피오르(노르웨이) — 가파른 산으로 둘러싸인 매우 좁고 긴 해안선","② 사하라 사막(리비아) — 광활하게 펼쳐진 모래 언덕","③ 황허강(중국) — 황토가 섞여 색이 누런 강물이 굽이쳐 길게 흐름","④ 울루루(오스트레일리아) — 하나의 거대한 암석 바위산이 드넓은 평지에 솟음","⑤ 마우나로아(미국) — 용암이 흐르는 모습을 볼 수 있는 화산","⑥ 엘 아르코(멕시코) — 바다 위에 우뚝 솟은 아치 모양의 바위","⑦ 호라이마산(베네수엘라 볼리바르) — 우뚝 솟아 있지만 위쪽이 평평함"],"numbered":false,"title":"교과서 13~14쪽 세계의 유명한 지형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_d#2','soc',6,2,'u1','','tb_g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C2',1,'sa','auto','아프리카에서 가장 큰 고원으로 「아프리카의 지붕」이라고 불리는 곳은 어디인가요?','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u1-C2","difficulty":1,"kind":"sa","stem":"아프리카에서 가장 큰 고원으로 「아프리카의 지붕」이라고 불리는 곳은 어디인가요?","answer":["아비시니아고원","아비시니아 고원"],"explanation":["교과서 15쪽 사진 ②예요.","에티오피아에 있어요.","아비시니아고원이에요."],"mis":"SO6-2-u1-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_d#3','soc',6,2,'u1','','tb_g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C2',1,'mc','auto','아이슬란드에서 화산 분출을 볼 수 있는 지역을 이용하는 방법은 무엇인가요?',ARRAY['SO6-2-u1-X06','SO6-2-u1-X03']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C2","difficulty":1,"kind":"mc","stem":"아이슬란드에서 화산 분출을 볼 수 있는 지역을 이용하는 방법은 무엇인가요?","options":[{"t":"관광지로 활용해요","correct":true},{"t":"항구로 활용해요","mis":"SO6-2-u1-X06"},{"t":"염전으로 활용해요","mis":"SO6-2-u1-X06"},{"t":"계단식 논으로 활용해요","mis":"SO6-2-u1-X03"}],"explanation":["교과서 17쪽 사진이에요.","화산 분출은 독특한 경관이에요.","관광지로 활용해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_d#4','soc',6,2,'u1','','tb_g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C3',1,'mc','auto','강 옆으로 매우 넓은 농경지가 보이는 나일강 평야가 있는 나라는 어디인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C3","difficulty":1,"kind":"mc","stem":"강 옆으로 매우 넓은 농경지가 보이는 나일강 평야가 있는 나라는 어디인가요?","options":[{"t":"이집트","correct":true},{"t":"브라질","mis":"SO6-2-u1-X03"},{"t":"미국","mis":"SO6-2-u1-X03"},{"t":"타이","mis":"SO6-2-u1-X03"}],"explanation":["교과서 19쪽 사진 ㉡이에요.","나일강은 아프리카에 있어요.","이집트예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_d#5','soc',6,2,'u1','','tb_g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C3',1,'mc','auto','브라질과 아르헨티나 사이에 있어 웅장한 경관을 보려고 많은 관광객이 찾는 폭포는 무엇인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C3","difficulty":1,"kind":"mc","stem":"브라질과 아르헨티나 사이에 있어 웅장한 경관을 보려고 많은 관광객이 찾는 폭포는 무엇인가요?","options":[{"t":"이구아수 폭포","correct":true},{"t":"빅토리아 폭포","mis":"SO6-2-u1-X03"},{"t":"나이아가라 폭포","mis":"SO6-2-u1-X03"},{"t":"호스슈 벤드 계곡","mis":"SO6-2-u1-X03"}],"explanation":["교과서 21쪽 사진이에요.","두 나라 사이에 있어요.","이구아수 폭포예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_d#6','soc',6,2,'u1','','tb_g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C4',1,'sa','auto','우리나라 서·남해안, 유럽 북해 연안처럼 세계적으로 유명한 해안의 지형 경관은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-2-u1-C4","difficulty":1,"kind":"sa","stem":"우리나라 서·남해안, 유럽 북해 연안처럼 세계적으로 유명한 해안의 지형 경관은 무엇인가요? 두 글자로 쓰세요.","answer":["갯벌"],"explanation":["교과서 23쪽 물음을 떠올려요.","밀물과 썰물이 드나드는 곳이에요.","갯벌이에요."],"mis":"SO6-2-u1-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_d#7','soc',6,2,'u1','','tb_g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C4',1,'mc','auto','해안 지역 주민들이 주로 하는 일로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u1-X03','SO6-2-u1-X12','SO6-2-u1-X05']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C4","difficulty":1,"kind":"mc","stem":"해안 지역 주민들이 주로 하는 일로 알맞은 것은 무엇인가요?","options":[{"t":"어업이나 양식업","correct":true},{"t":"광업과 목축업","mis":"SO6-2-u1-X03"},{"t":"화전 농업","mis":"SO6-2-u1-X12"},{"t":"수력 발전","mis":"SO6-2-u1-X05"}],"explanation":["교과서 24쪽 글을 읽어요.","바다에서 물고기를 잡거나 길러요.","어업이나 양식업이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_d#8','soc',6,2,'u1','','tb_g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C1',1,'match','auto','지형과 그 지형에서 볼 수 있는 관광 모습을 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u1-C1","difficulty":1,"kind":"match","stem":"지형과 그 지형에서 볼 수 있는 관광 모습을 이으세요.","pairs":[{"l":"산지","r":"스키장과 휴양림"},{"l":"하천","r":"폭포 관광"},{"l":"해안","r":"해수욕장"}],"mis":"SO6-2-u1-X07","explanation":["지형마다 관광을 떠올려요.","산지는 스키장과 휴양림이에요.","하천은 폭포, 해안은 해수욕장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_d#9','soc',6,2,'u1','','tb_g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C5',2,'mc','auto','연평균 기온이 26.6℃인 아부자, 11.9℃인 리옹, -0.5℃인 키루나를 적도에서 가까운 차례대로 놓은 것은 무엇인가요?',ARRAY['SO6-2-u1-X09']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"mc","stem":"연평균 기온이 26.6℃인 아부자, 11.9℃인 리옹, -0.5℃인 키루나를 적도에서 가까운 차례대로 놓은 것은 무엇인가요?","options":[{"t":"아부자 → 리옹 → 키루나","correct":true},{"t":"키루나 → 리옹 → 아부자","mis":"SO6-2-u1-X09"},{"t":"리옹 → 아부자 → 키루나","mis":"SO6-2-u1-X09"},{"t":"아부자 → 키루나 → 리옹","mis":"SO6-2-u1-X09"}],"explanation":["적도에 가까울수록 기온이 높아요.","기온이 높은 도시부터 놓아요.","아부자, 리옹, 키루나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_d#10','soc',6,2,'u1','','tb_g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C5',2,'blank','auto','「세계의 기후는 지역의 (    )뿐만 아니라, 위치와 지형, 해발 고도에 따라 다르게 나타납니다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-2-u1-X09','SO6-2-u1-X08']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"blank","stem":"「세계의 기후는 지역의 (    )뿐만 아니라, 위치와 지형, 해발 고도에 따라 다르게 나타납니다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"위도","correct":true},{"t":"나라 이름","mis":"SO6-2-u1-X09"},{"t":"사람 수","mis":"SO6-2-u1-X09"},{"t":"날씨","mis":"SO6-2-u1-X08"}],"explanation":["교과서 32쪽 글이에요.","햇볕의 양을 정하는 것이에요.","위도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_d#11','soc',6,2,'u1','','tb_g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C6',2,'mc','auto','기후 그래프에서 막대와 선이 나타내는 것을 바르게 짝지은 것은 무엇인가요?',ARRAY['SO6-2-u1-X21']::text[],false,'{"seq":11,"concept":"SO6-2-u1-C6","difficulty":2,"kind":"mc","stem":"기후 그래프에서 막대와 선이 나타내는 것을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"막대 — 강수량, 선 — 기온","correct":true},{"t":"막대 — 기온, 선 — 강수량","mis":"SO6-2-u1-X21"},{"t":"막대 — 위도, 선 — 기온","mis":"SO6-2-u1-X21"},{"t":"막대 — 강수량, 선 — 해발 고도","mis":"SO6-2-u1-X21"}],"explanation":["그래프 옆 말풍선을 떠올려요.","막대는 강수량이에요.","선은 기온이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_d#12','soc',6,2,'u1','','tb_g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C5',2,'sa','auto','「적도 지방에서 극지방으로 가면서 열대 기후, 건조 기후, 온대 기후, 냉대 기후, (    ) 기후 순으로 나타납니다.」 빈칸에 알맞은 말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"sa","stem":"「적도 지방에서 극지방으로 가면서 열대 기후, 건조 기후, 온대 기후, 냉대 기후, (    ) 기후 순으로 나타납니다.」 빈칸에 알맞은 말을 두 글자로 쓰세요.","answer":["한대"],"explanation":["꼭 기억해요를 떠올려요.","극지방에 가장 가까운 기후예요.","한대예요."],"mis":"SO6-2-u1-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_d#13','soc',6,2,'u1','','tb_g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C7',2,'mc','auto','교과서 40쪽에서 물이 부족한 건조 기후 지역의 이집트 사람들이 즐겨 먹는 음식은 무엇인가요?',ARRAY['SO6-2-u1-X12']::text[],false,'{"seq":13,"concept":"SO6-2-u1-C7","difficulty":2,"kind":"mc","stem":"교과서 40쪽에서 물이 부족한 건조 기후 지역의 이집트 사람들이 즐겨 먹는 음식은 무엇인가요?","options":[{"t":"에이쉬라는 빵","correct":true},{"t":"국수","mis":"SO6-2-u1-X12"},{"t":"죽","mis":"SO6-2-u1-X12"},{"t":"똠얌꿍","mis":"SO6-2-u1-X12"}],"explanation":["기후가 만든 독특한 문화예요.","빵은 적은 물로 만들어요.","에이쉬라는 빵이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_d#14','soc',6,2,'u1','','tb_g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C8',2,'mc','auto','온대 기후 지역 가운데 여름이 서늘하고 겨울이 따뜻하며 연중 강수량이 고른 곳은 어디인가요?',ARRAY['SO6-2-u1-X13','SO6-2-u1-X11']::text[],false,'{"seq":14,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"mc","stem":"온대 기후 지역 가운데 여름이 서늘하고 겨울이 따뜻하며 연중 강수량이 고른 곳은 어디인가요?","options":[{"t":"서부 유럽","correct":true},{"t":"지중해 주변","mis":"SO6-2-u1-X13"},{"t":"우리나라","mis":"SO6-2-u1-X13"},{"t":"적도 주변","mis":"SO6-2-u1-X11"}],"explanation":["교과서 37쪽 글을 읽어요.","런던이 있는 곳이에요.","서부 유럽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_d#15','soc',6,2,'u1','','tb_g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C8',2,'sa','auto','냉대 기후 지역의 침엽수림에서 생산하는 것으로, 나무에서 뽑아내 종이의 원료로 쓰는 것은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"sa","stem":"냉대 기후 지역의 침엽수림에서 생산하는 것으로, 나무에서 뽑아내 종이의 원료로 쓰는 것은 무엇인가요? 두 글자로 쓰세요.","answer":["펄프"],"explanation":["교과서 39쪽 낱말 풀이예요.","종이의 원료예요.","펄프예요."],"mis":"SO6-2-u1-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_d#16','soc',6,2,'u1','','tb_g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C6',2,'mc','auto','열대 기후 지역 사람들이 주로 입는 옷은 무엇인가요?',ARRAY['SO6-2-u1-X12','SO6-2-u1-X14']::text[],false,'{"seq":16,"concept":"SO6-2-u1-C6","difficulty":2,"kind":"mc","stem":"열대 기후 지역 사람들이 주로 입는 옷은 무엇인가요?","options":[{"t":"얇고 바람이 잘 통하는 옷","correct":true},{"t":"두꺼운 털옷","mis":"SO6-2-u1-X12"},{"t":"동물 가죽으로 된 옷","mis":"SO6-2-u1-X12"},{"t":"여러 겹 옷과 망토","mis":"SO6-2-u1-X14"}],"explanation":["열대 기후는 덥고 습해요.","시원하게 입어야 해요.","얇고 바람이 잘 통하는 옷이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_d#17','soc',6,2,'u1','','tb_g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C3',3,'ox','auto','노르웨이에서 수력 발전이 발달한 것은 하천의 풍부한 물을 이용한 생활 모습이에요.',ARRAY['SO6-2-u1-X05']::text[],false,'{"seq":17,"concept":"SO6-2-u1-C3","difficulty":3,"kind":"ox","stem":"노르웨이에서 수력 발전이 발달한 것은 하천의 풍부한 물을 이용한 생활 모습이에요.","answer":"O","reason_options":[{"t":"강이 많고 물의 양이 풍부해 전기의 대부분을 수력 발전으로 만들기 때문에","correct":true},{"t":"수력 발전은 바닷물의 소금으로 하기 때문에","mis":"SO6-2-u1-X05"}],"mis":"SO6-2-u1-X05","explanation":["노르웨이를 떠올려요.","물이 풍부해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_d#18','soc',6,2,'u1','','tb_g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C4',3,'mc','auto','아름다운 지형 경관을 지키기 위한 노력으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO6-2-u1-X07']::text[],false,'{"seq":18,"concept":"SO6-2-u1-C4","difficulty":3,"kind":"mc","stem":"아름다운 지형 경관을 지키기 위한 노력으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"관광객을 더 많이 받으려고 해안을 모두 개발해요","correct":true},{"t":"관광객의 수를 제한해요","mis":"SO6-2-u1-X07"},{"t":"쓰레기를 되가져오게 해요","mis":"SO6-2-u1-X07"},{"t":"일정 기간 관광지를 쉬게 해요","mis":"SO6-2-u1-X07"}],"explanation":["지나친 개발을 떠올려요.","경관을 해칠 수 있어요.","모두 개발하는 것은 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_d#19','soc',6,2,'u1','','tb_g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C9',3,'mc','auto','누크(그린란드)의 기후 그래프에서 알 수 있는 한대 기후의 특징은 무엇인가요?',ARRAY['SO6-2-u1-X11','SO6-2-u1-X13','SO6-2-u1-X14']::text[],false,'{"seq":19,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"mc","stem":"누크(그린란드)의 기후 그래프에서 알 수 있는 한대 기후의 특징은 무엇인가요?","options":[{"t":"겨울이 길고 기온이 매우 낮아요","correct":true},{"t":"일 년 내내 기온이 높아요","mis":"SO6-2-u1-X11"},{"t":"여름보다 겨울에 비가 많고 따뜻해요","mis":"SO6-2-u1-X13"},{"t":"일 년 내내 서늘해 사람이 많이 모여 살아요","mis":"SO6-2-u1-X14"}],"explanation":["누크는 그린란드에 있어요.","극지방 가까이예요.","겨울이 길고 기온이 매우 낮아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_d#20','soc',6,2,'u1','','tb_g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C9',3,'mc','auto','고산 기후 지역에 발달한 도시를 바르게 모은 것은 무엇인가요?',ARRAY['SO6-2-u1-X14','SO6-2-u1-X09','SO6-2-u1-X13']::text[],false,'{"seq":20,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"mc","stem":"고산 기후 지역에 발달한 도시를 바르게 모은 것은 무엇인가요?","options":[{"t":"보고타, 키토, 라파스","correct":true},{"t":"누크, 오슬로, 키루나","mis":"SO6-2-u1-X14"},{"t":"카이로, 아부자, 쿠알라룸푸르","mis":"SO6-2-u1-X09"},{"t":"런던, 로마, 서울","mis":"SO6-2-u1-X13"}],"explanation":["교과서 42쪽 고산 도시를 떠올려요.","높은 산지에 있어요.","보고타, 키토, 라파스예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_d#21','soc',6,2,'u1','','tb_g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C5',3,'mc','auto','세계 여행 박람회에서 친구 ❹가 가고 싶어 하는 나라로 알맞은 곳은 어디인가요?',ARRAY['SO6-2-u1-X02']::text[],false,'{"seq":21,"concept":"SO6-2-u1-C5","difficulty":3,"kind":"mc","stem":"세계 여행 박람회에서 친구 ❹가 가고 싶어 하는 나라로 알맞은 곳은 어디인가요?","options":[{"t":"네팔","correct":true},{"t":"모로코","mis":"SO6-2-u1-X02"},{"t":"캐나다","mis":"SO6-2-u1-X02"},{"t":"브라질","mis":"SO6-2-u1-X02"}],"explanation":["친구 ❹의 말을 읽어요.","지대가 높은 산, 트레킹이 나와요.","네팔이에요."],"asset":{"type":"speech","turns":[{"who":"친구 ❶","text":"건조한 기후가 나타나는 나라에 가고 싶어. 땀이 나도 금방 마르잖아. 모래 비탈에서 보드도 타고 흙벽돌로 만든 집에도 가 보고 싶어."},{"who":"친구 ❷","text":"여름에도 빙하나 눈을 볼 수 있는 곳에 가 보고 싶어. 이누이트족의 생활을 체험하고 기념품도 사고 싶어."},{"who":"친구 ❸","text":"여름에는 물놀이가 제일이지. 야자수가 펼쳐진 바닷가에서 수영하고 열대 과일도 먹고 싶어. 거대한 폭포도 보러 가고 말이야."},{"who":"친구 ❹","text":"여름에는 시원한 곳이 최고야. 지대가 높은 산은 일 년 내내 시원하니까 유명한 산이 있는 나라로 여행 가서 트레킹을 해 보고 싶어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_d#22','soc',6,2,'u1','','tb_g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C2',3,'blank','auto','생각 그물에서 산지 지형의 생활 모습을 「(    ) 농사, 스키장, 광업, 온천」으로 정리했어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-2-u1-X05','SO6-2-u1-X06','SO6-2-u1-X12']::text[],false,'{"seq":22,"concept":"SO6-2-u1-C2","difficulty":3,"kind":"blank","stem":"생각 그물에서 산지 지형의 생활 모습을 「(    ) 농사, 스키장, 광업, 온천」으로 정리했어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"계단식","correct":true},{"t":"평야","mis":"SO6-2-u1-X05"},{"t":"양식","mis":"SO6-2-u1-X06"},{"t":"화전","mis":"SO6-2-u1-X12"}],"explanation":["가파른 산비탈을 떠올려요.","계단처럼 논을 만들어요.","계단식 농사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_d#23','soc',6,2,'u1','','tb_g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C6',4,'mc','auto','함께 빙고 판의 낱말 가운데 「사파리 관광」과 같은 기후 지역에서 볼 수 있는 것은 무엇인가요?',ARRAY['SO6-2-u1-X13','SO6-2-u1-X03']::text[],false,'{"seq":23,"concept":"SO6-2-u1-C6","difficulty":4,"kind":"mc","stem":"함께 빙고 판의 낱말 가운데 「사파리 관광」과 같은 기후 지역에서 볼 수 있는 것은 무엇인가요?","options":[{"t":"화전 농업","correct":true},{"t":"올리브","mis":"SO6-2-u1-X13"},{"t":"침엽수림","mis":"SO6-2-u1-X13"},{"t":"계단식 논","mis":"SO6-2-u1-X03"}],"explanation":["사파리 관광은 열대 기후 지역이에요.","열대 기후의 전통 농업을 찾아요.","화전 농업이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_d#24','soc',6,2,'u1','','tb_g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C7',4,'ox','auto','건조 기후 지역 사람들이 오아시스 주변에서 밀이나 대추야자를 재배하는 것은 어려운 자연환경 속에서도 땅을 이용하며 살아가는 모습이에요.',ARRAY['SO6-2-u1-X18']::text[],false,'{"seq":24,"concept":"SO6-2-u1-C7","difficulty":4,"kind":"ox","stem":"건조 기후 지역 사람들이 오아시스 주변에서 밀이나 대추야자를 재배하는 것은 어려운 자연환경 속에서도 땅을 이용하며 살아가는 모습이에요.","answer":"O","reason_options":[{"t":"물이 있는 오아시스와 강 주변을 찾아 농사를 지으며 건조한 환경에 적응하기 때문에","correct":true},{"t":"건조 기후 지역에서는 농사를 지을 수 없기 때문에","mis":"SO6-2-u1-X18"}],"mis":"SO6-2-u1-X18","explanation":["오아시스를 떠올려요.","물이 있어 농사를 지어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u1_review_d#25','soc',6,2,'u1','','tb_g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C10',4,'essay','teacher','교과서의 방한용 안전 신발처럼, 세계의 다양한 자연환경 가운데 한 곳을 골라 그곳 사람들에게 필요한 상품을 구상하고, 판매 동기와 상품의 특징이 자연환경과 어떻게 이어지는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-2-u1-C10","difficulty":4,"kind":"essay","stem":"교과서의 방한용 안전 신발처럼, 세계의 다양한 자연환경 가운데 한 곳을 골라 그곳 사람들에게 필요한 상품을 구상하고, 판매 동기와 상품의 특징이 자연환경과 어떻게 이어지는지 쓰세요.","answer_guide":{"answer":"예: 몽골 같은 건조 기후의 초원 지역 사람들은 물과 풀을 찾아 자주 옮겨 다녀요. 판매 동기 — 이동식 가옥을 자주 접고 펴야 해서 힘들어요. 상품 — 가볍고 빨리 펼쳐지는 이동식 가옥. 특징 — 가축의 털로 만든 덮개로 밤의 추위를 막고, 낮에는 바람이 통하게 열 수 있어요.","scoring_points":["자연환경을 골라 특징을 썼는가","자연환경에서 오는 불편을 판매 동기로 썼는가","상품의 특징이 자연환경과 이어지는가"]},"explanation":["자연환경 하나를 골라요.","그곳의 불편을 찾아요.","불편을 덜어 줄 상품을 구상해요."],"asset":{"type":"passage","lines":["판매할 나라 — 노르웨이","특징(기후) — 냉대 기후가 나타나 겨울이 여름보다 길고 몹시 추우며 눈이 많이 와요.","판매 동기 — 겨울이 길고 눈이 많이 내려 이동할 때 불편해요.","상품 — 방한용 안전 신발","특징 — 바닥의 스파이크로 얼음 위에서도 미끄러지지 않음,","　스키를 붙여 눈에서 편리하게 이동, 태양열로 충전되는 열선으로 발을 따뜻하게"],"numbered":false,"title":"교과서 49쪽 상품 판매 계획 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
